"use strict";
/* Toxicología (3er parcial): plaguicidas, metales y otros contaminantes. index.html carga este archivo en vez de ../data.js */
const SUBJECT = { id: "toxi", name: "Toxicología", exam: "3er parcial", topics: [1, 2, 3], game: false, studyFirst: 1 };
const TOPICS = {
  1:{name:"Plaguicidas",desc:"Temas 26-29 (generalidades, insecticidas, rodenticidas, molusquicidas, herbicidas y fungicidas)"},
  2:{name:"Metales",desc:"Temas 30-33 (quelantes; mercurio, cadmio, plomo, cobre, molibdeno, selenio, flúor, arsénico, cinc y talio)"},
  3:{name:"Otros contaminantes",desc:"Temas 34-35 (retardantes de llama, bisfenol A y radiaciones ionizantes)"}
};

/* t = tema, q = pregunta, o = opciones (orden original), a = índice correcto,
   m = índice marcado en la recopilación cuando NO coincide con la correcta, d = pregunta dudosa, n = explicación */
const QUESTIONS = [
/* examen del 3er parcial (15/5/25) */
{t:1,q:"Dos insecticidas llevan la misma sustancia activa, con idéntica DL50 oral en rata, pero uno está formulado al 10 % y el otro al 2 %. ¿Cuál es menos peligroso como preparado?",o:["El del 2 %, porque la DL50 del preparado es (L × 100) / C y sube al bajar el porcentaje","El del 10 %, porque al llevar más activo hace falta aplicar mucha menos dosis de producto","Los dos igual, porque la DL50 del preparado solo depende de la sustancia activa","El del 2 %, porque la DL50 del preparado se obtiene multiplicando L por C y por 100"],a:0,
n:"Cayó en el 3er parcial (15/5/25) como pregunta de desarrollo de 2 puntos: un ganadero busca un insecticida para insectos voladores, le dan dos productos con su dosis y sus componentes, los dos con la misma DL50, y hay que razonar cuál es mejor.<br><b>Regla (apuntes p. 2):</b> la DL50 de un formulado con una sola sustancia activa se calcula como <b>L × 100 / C</b>, donde L es la DL50 oral en rata de la sustancia activa y C su porcentaje en el preparado. A igual L, cuanto menor es C mayor es la DL50 del preparado, es decir, menos tóxico.<br>Si el producto lleva varias sustancias activas se usa la fórmula de mezclas de la p. 3: Ca/Ta + Cb/Tb + … + Cz/Tz = 100/Tm."},
/* examen del 3er parcial (15/5/25) */
{t:1,q:"Con dos insecticidas cuya sustancia activa tiene la misma DL50, ¿qué permite razonar el tema para elegir el menos peligroso?",o:["El porcentaje de activo del preparado, su estado de presentación y la clase de OMS o GHS que resulta","Solo la DL50 de la sustancia activa, que por sí misma ya define la peligrosidad del preparado","Solo la DL50 dérmica en conejo, porque es la única vía que recoge la clasificación de la OMS en el tema","El número de ingredientes inertes, porque los coadyuvantes aumentan siempre la toxicidad final"],a:0,
n:"Cayó en el 3er parcial (15/5/25) dentro de la pregunta de desarrollo de los dos insecticidas con la misma DL50.<br>Para razonarlo hay que apoyarse en: <b>1)</b> la DL50 del preparado, L × 100 / C (p. 2), o la fórmula de mezclas si hay varios activos (p. 3); <b>2)</b> la categoría que sale en los cuadros de GHS (p. 2) y de la OMS (p. 3), donde los límites son distintos para <b>sólidos y líquidos</b> y para vía oral y dérmica; <b>3)</b> el estado de presentación (gases, fumigantes y aerosoles, polvos &lt; 50 µ, sólidos, líquidos, cebos y tabletas, p. 3), que para insectos voladores condiciona la exposición del aplicador y del ganado.<br>Recuerda que los fumigantes gaseosos o volátiles quedan fuera de la clasificación de peligrosidad de la OMS (p. 4)."},
/* examen del 3er parcial (15/5/25) */
{t:1,q:"De los siguientes insecticidas, ¿cuál es el más tóxico?",o:["Aldicarb","Carbofurano","Carbaril","Benomilo"],a:0,
n:"Cayó en el 3er parcial (15/5/25) y era una pregunta repetida.<br>Por las DL50 orales en rata que dan los apuntes (p. 20): <b>aldicarb 0,65 mg/kg</b>, carbofurano 6,0-7,8 mg/kg, carbaril 230 mg/kg y benomilo &gt; 10.000 mg/kg. Cuanto <b>menor es la DL50, más tóxico</b> es el compuesto, así que el aldicarb es con diferencia el más tóxico (y el benomilo, el menos)."},
/* examen del 3er parcial (15/5/25) */
{t:1,q:"¿Qué síntomas corresponden a la 1.ª fase (muscarínica) de la intoxicación por organofosforados?",o:["Salivación intensa, lagrimeo, miosis y bradicardia","Taquicardia, midriasis y vasoconstricción periférica","Temblores y fasciculaciones que empiezan por la cabeza","Ansiedad con crisis convulsivas o bien depresión del SNC"],a:0,
n:"Cayó en el 3er parcial (15/5/25).<br>Apuntes p. 19: en la <b>fase muscarínica</b> hay aumento de secreciones y contracción de la musculatura lisa: salivación intensa, vómitos, diarreas mucosas, micción abundante, lagrimeo y miosis, hipersecreción bronquial con disnea y edema pulmonar, y <b>bradicardia</b> con bloqueos aurículo-ventriculares y choque vagal.<br>La <b>taquicardia es falsa</b> como síntoma muscarínico: aparece en la <b>fase nicotínica</b>, junto con midriasis, vasoconstricción, temblores que empiezan por la cabeza y desaparición de la hipersecreción. La ansiedad, las convulsiones o la depresión son la 3.ª fase (alteración del SNC)."},
/* examen del 3er parcial (15/5/25) */
{t:1,q:"Oveja en decúbito con pataleo y posibles convulsiones, restos de vómito y numerosas moscas muertas alrededor del vómito. ¿Qué intoxicación sugiere el cuadro?",o:["Por un insecticida anticolinesterásico (organofosforado o carbamato)","Por un rodenticida anticoagulante de segunda generación","Por un piretroide sintético aplicado de forma repetida","Por un exceso crónico de cobre en el pienso del rebaño"],a:0,
n:"Cayó en el 3er parcial (15/5/25) como caso clínico con dos fotos (había que describir la imagen: pataleo y posibles convulsiones, con muchas moscas muertas alrededor del vómito).<br>Los apuntes (p. 19) describen justo ese cuadro para los <b>OP y carbamatos</b>: fase muscarínica con <b>vómitos</b>, salivación y diarrea, y fase nicotínica con <b>temblores y convulsiones</b> que terminan en debilidad muscular. Además, los OP son <b>muy buenos insecticidas de contacto</b> (p. 15), lo que explica que las moscas que se posan en el vómito aparezcan muertas: el vómito sigue conteniendo el insecticida.<br>Los anticoagulantes cursan con hemorragias y anemia, y el cobre crónico en ovino con hemoglobinuria e ictericia, no con este cuadro nervioso."},
/* examen del 3er parcial (15/5/25) */
{t:1,q:"En ese mismo caso, ¿qué muestras hay que recoger para confirmar la intoxicación?",o:["El vómito y el contenido gástrico, además de hígado, riñón y orina","Solo sangre con EDTA para valorar el hematocrito y la anemia","Solo heces y orina recogidas unas 48 horas después del cuadro","Solo líquido cefalorraquídeo y humor acuoso del ojo del animal"],a:0,
n:"Cayó en el 3er parcial (15/5/25): tras describir las fotos de la oveja había una pregunta tipo test sobre <b>cómo hacer la toma de muestras correctamente</b>, con opciones del tipo «tomar por triplicado y hacer la toma de muestras en el centro intermedio», «cambiarse los guantes para evitar la contaminación cruzada» o «hacer la toma por cuatriplicado».<br><b>Ojo:</b> estos apuntes <b>no explican el procedimiento</b> de la toma de muestras (ni el triplicado ni los guantes). Lo único que recogen es <b>qué</b> muestras se toman en una intoxicación con cuadro nervioso (p. 27, estricnina): <b>contenido gástrico, hígado, riñón, orina, tejidos del SNC y cebos o vómitos</b>; esa es la opción que se apoya en los apuntes.<br>Como regla general de toxicología (fuera de estos apuntes), la toma oficial se hace <b>por triplicado</b> (muestra, contramuestra y dirimente), así que esa era la opción más probable en el examen."},
/* examen del 3er parcial (15/5/25) */
{t:1,q:"Mecanismo de acción de la estricnina. Señala la respuesta CORRECTA:",o:["Es un antagonista competitivo y reversible de los receptores de la glicina del SNC","Es un antagonista irreversible y no competitivo de los receptores de la glicina del SNC","Es un agonista competitivo y reversible de los receptores de la glicina del SNC","Es un antagonista competitivo y reversible de los receptores del GABA del SNC"],a:0,
n:"Cayó en el 3er parcial (15/5/25) y está marcada como repetida: la pregunta de la estricnina y la glicina.<br>Tus apuntes (Tema 28, p. 26): «Actúa a <b>nivel del SNC</b>. Es un <b>antagonista competitivo y reversible de los receptores de la glicina</b>, ocasionando así estimulación incontrolada de los músculos esqueléticos».<br>La glicina es el neurotransmisor <b>inhibidor</b> de la médula espinal: si se bloquea su receptor, se pierde la inhibición y la musculatura esquelética queda estimulada sin control."},
/* examen del 3er parcial (15/5/25) */
{t:1,q:"La estricnina bloquea los receptores de la glicina. ¿Qué cuadro clínico produce y cómo mata al animal?",o:["Contracciones tetánicas, postura en caballete y risa sardónica; muerte por parálisis medular","Contracciones tetánicas, postura en caballete y risa sardónica; muerte por shock cardiogénico","Parálisis flácida, decúbito y pupilas midriáticas; muerte por parálisis medular tras la anoxia","Vómitos sanguinolentos, temblores y miosis; muerte por parálisis medular tras la anoxia"],a:0,
n:"Cayó en el 3er parcial (15/5/25) la pregunta de la estricnina y la glicina (repetida); los compañeros avisan de que las preguntas del tipo 1 y del tipo 2 no eran iguales, así que conviene dominar también la clínica.<br>Tus apuntes (Tema 28, p. 26): latencia de <b>10 min – 2 horas</b>, «contracciones tetánicas violentas», «hiperexcitabilidad y postura caballete», «labios dirigidos hacia atrás <b>risa sardónica</b>» y «anoxia y por último, <b>muerte por parálisis medular</b>».<br>Al bloquearse la glicina (inhibidora) toda la musculatura esquelética se contrae: nunca hay parálisis flácida."},
/* examen del 3er parcial (15/5/25) */
{t:1,q:"Un perro ha ingerido un cebo de brodifacoum. ¿Cuál es el tratamiento correcto?",o:["Soporte de las funciones vitales y vitamina K1, porque es un anticoagulante de 2ª generación","Soporte de las funciones vitales y gluconato cálcico, porque es un anticoagulante de 2ª generación","Soporte de las funciones vitales y vitamina K1, porque es un glucósido cardiaco como la digitoxina","Soporte de las funciones vitales y apomorfina para la emesis, porque bloquea la citocromo C oxidasa"],a:0,
n:"Cayó en el 3er parcial (15/5/25): «intoxicación por un nombre que empezaba por bro: <b>vit. K1</b>». Los rodenticidas cuyo nombre empieza por «bro» son el <b>brodifacoum</b> y la <b>bromadiolona</b>, ambos anticoagulantes de <b>2ª generación</b> (Tema 28, p. 23).<br>Tratamiento (p. 25): «<b>Soporte normal de las funciones vitales y vit. K</b>».<br>Son los más tóxicos de la tabla de DL50 (p. 24): brodifacoum <b>0,26 mg/kg</b> y bromadiolona <b>1,12 mg/kg</b>, frente a los 58 mg/kg de la warfarina. Bloquean la regeneración de la vitamina K activa (vitamina K epóxido reductasa), por eso faltan los factores <b>II (protrombina), VII, IX y X</b> y el tiempo de protrombina se alarga a las 24-48 h.<br>El gluconato cálcico es del fluoroacetato (p. 30) y la citocromo C oxidasa, de la fosfina (p. 28)."},
/* examen del 3er parcial (15/5/25) */
{t:1,q:"Mecanismo de acción del diquat (herbicida bipiridílico), en una frase muy corta:",o:["Acepta electrones y genera radicales libres que peroxidan las membranas","Inhibe de forma irreversible la acetilcolinesterasa de las sinapsis","Desacopla la fosforilación oxidativa e inhibe la formación de ATP","Oxida el hierro de la hemoglobina y la transforma en metahemoglobina"],a:0,
n:"Cayó en el 3er parcial (15/5/25) como pregunta de desarrollo: decir el mecanismo de acción en una palabra o frase muy corta de diquat, carbamato, organofosforado y lindano.<br><b>Diquat (y paraquat): aceptores de electrones → radicales libres</b> que peroxidan los lípidos de las membranas. En tus apuntes (p. 40): los bipiridílicos son magníficos aceptores de electrones, se reducen con gran facilidad y dan radicales libres, responsables de su acción herbicida y de su toxicidad. El esquema de la p. 41 lo desarrolla: redox → e⁻ → O₂⁻ (superóxido) → SOD → H₂O₂ → catalasa → H₂O, y los lípidos poliinsaturados pasan a hidroperóxidos y a radicales libres lipídicos que alteran las membranas (la GSH-Px, con glutatión y selenio, los desvía a alcoholes atóxicos). Además son irritantes y cáusticos.<br>Para los otros tres, del tema de insecticidas: carbamato = inhibición <b>reversible</b> de la colinesterasa; organofosforado = inhibición <b>irreversible</b> de la colinesterasa; lindano = antagonismo del <b>GABA</b> (bloqueo del canal de cloro).<br>Aviso de la recopilación: cuando el examen dice <b>herbicida bipiridílico</b> se refiere sobre todo al <b>paraquat</b>."},
/* recopilación, reco p. 1 (Plaguicidas n.º 1); repetida en p. 2 (n.º 8) */
{t:1,q:"¿Cuál de las siguientes familias de plaguicidas es, en regla general, la que presenta mayor PERSISTENCIA a nivel ambiental?",o:["Carbamatos.","Organoclorados.","Organofosforados.","Rodenticidas anticoagulantes."],a:1,
n:"✓ Los organoclorados son <b>muy persistentes y poco biodegradables</b>, con gran capacidad de bioacumulación y biomagnificación, insolubles en agua y muy solubles en grasas (apuntes, p. 12).<br>✗ Los organofosforados <b>sustituyeron a los organoclorados precisamente por ser menos persistentes y bioacumulables</b> (apuntes, p. 15).<br>✗ Los carbamatos son <b>muy poco persistentes</b> en la naturaleza (apuntes, p. 20).<br>✗ Los rodenticidas anticoagulantes se emplean en cebos; no destacan por su persistencia ambiental."},
/* recopilación, reco p. 1 (Plaguicidas n.º 2) */
{t:1,q:"Señale las tres características más importantes de los plaguicidas organoclorados.",o:["Ninguna de las anteriores.","Persistencia, capacidad de bioacumulación y liposolubilidad.","Persistencia, hidrosolubilidad y toxicidad.","Capacidad de bioacumulación, amplio uso en la actualidad y efectos negativos."],a:1,
n:"✓ Apuntes, p. 12: «muy persistentes y poco biodegradables», «cloro muy reactivo: bioacumulación y biomagnificación», «insolubles en agua» y «muy solubles en solventes orgánicos y grasas» (liposolubilidad).<br>✗ Hidrosolubilidad: es justo lo contrario (son insolubles en agua).<br>✗ Amplio uso en la actualidad: <b>están prohibidos</b> (apuntes, p. 14); hoy dominan organofosforados, carbamatos y piretroides."},
/* recopilación, reco p. 1 (Plaguicidas n.º 3); variante en p. 10 (n.º 16) */
{t:1,q:"Señale el enunciado INCORRECTO sobre los plaguicidas y sus residuos:",o:["Los residuos de plaguicidas pueden ser metabolitos primarios libres potencialmente tóxicos.","Según el último informe del MAPAMA, son los fungicidas y bactericidas los plaguicidas fitosanitarios más utilizados.","Los límites máximos de residuos son equiparables a límites toxicológicos.","Son compuestos que han estado implicados en muchas intoxicaciones colectivas."],a:2,
n:"✗ Los <b>LMR no son límites toxicológicos</b>: se fijan a partir de las buenas prácticas agrícolas (límite por defecto 0,01 mg/kg) y sirven para controlar el uso correcto del plaguicida; la seguridad del consumidor se evalúa aparte, con los valores de referencia toxicológicos (apuntes, p. 5).<br>✓ Los residuos incluyen la sustancia activa y sus metabolitos/productos de degradación, que pueden ser tóxicos.<br>✓ Lo del MAPAMA (fungicidas y bactericidas como los más utilizados) es dato de clase: no está en tus apuntes, pero la clave lo da por bueno.<br>✓ Han provocado intoxicaciones colectivas."},
/* recopilación, reco p. 1 (Plaguicidas n.º 4); repetida en p. 3 (n.º 18) */
{t:1,q:"Sobre el compuesto PARAQUAT, señale el enunciado INCORRECTO:",o:["El daño tóxico causado por él se manifiesta fundamentalmente en tejidos ovárico y testicular.","La toxicidad en mamíferos es relativamente alta.","El mecanismo de acción consiste en provocar estrés oxidativo y se basa en la generación de radicales superóxido.","Es un herbicida no selectivo de amplio espectro que actúa por contacto."],a:0,
n:"✗ El paraquat se acumula <b>selectivamente en el pulmón</b> (órgano deficitario en superóxido dismutasa) y ahí aparece el daño: congestión, edema, hemorragias y fibrosis pulmonar (apuntes, pp. 40-41). El tejido ovárico y testicular no es su diana.<br>✓ Toxicidad alta: DL50 oral 150 mg/kg en rata, 100 en conejo y 60 en perro (apuntes, p. 40).<br>✓ Es un magnífico aceptor de electrones: se reduce con facilidad y genera radicales libres (superóxido) → estrés oxidativo (apuntes, p. 40).<br>✓ Bipiridílico no selectivo, de contacto."},
/* recopilación, reco p. 1-2 (Plaguicidas n.º 5) */
{t:1,q:"Respecto a los rodenticidas anticoagulantes, señale el enunciado INCORRECTO:",o:["En algunas ocasiones tienen toxicidad similar para roedores, animales domésticos y ser humano.","Todas son falsas.","Producen descenso de los factores de coagulación.","Procesos de hipovitaminosis K disminuyen la toxicidad de estos compuestos."],a:3,
n:"✗ La hipovitaminosis K <b>aumenta</b> su toxicidad, no la disminuye: la dieta rica en grasa y los tratamientos orales prolongados con antibióticos provocan deficiencia de vitamina K y las enfermedades hepáticas, menor producción de protrombina; ambos aumentan la susceptibilidad (apuntes, p. 24).<br>✓ «En ocasiones causan toxicidad similar para roedores y animales domésticos» es literal de los apuntes (p. 23).<br>✓ Inhiben el complejo protrombina: descienden los factores dependientes de vitamina K (II, VII, IX y X) y aumenta el tiempo de coagulación (apuntes, p. 24)."},
/* recopilación, reco p. 2 (n.º 6); repetida en p. 9 (n.º 20) y p. 13 (n.º 18) */
{t:1,q:"Sobre herbicidas, seleccione la respuesta INCORRECTA:",o:["Los boratos son herbicidas inorgánicos que pueden producir alteraciones circulatorias.","Los herbicidas clorofenoxi pueden dar lugar al cloroacné.","Los derivados fenólicos son metahemoglobinizantes.","El diquat presenta una DL50 tres veces superior al paraquat."],a:3,
n:"✗ Es <b>el doble, no el triple</b>: DL50 oral en rata diquat 300 mg/kg frente a paraquat 150 mg/kg (en conejo 190 frente a 100) (apuntes, p. 40).<br>✓ Los boratos (tetraborato sódico) figuran entre los herbicidas <b>inorgánicos</b> (apuntes, p. 35).<br>✓ Los derivados fenólicos (DNP, DNOC) tienen acción metahemoglobinizante, menor que la de los cloratos (apuntes, p. 39).<br>✓ El cloroacné de los clorofenoxi (por las dioxinas que los contaminan) no aparece en tus apuntes, pero la clave lo da por bueno.<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 39 (n.º 68).</span>"},
/* recopilación, reco p. 2 (n.º 9); repetida en p. 13 (n.º 16) y p. 16 (n.º 7) */
{t:1,q:"Hipertermia, fatiga, taquicardia, hipersalivación, hiperestesia y convulsiones son síntomas de intoxicación aguda por:",o:["Metaldehído.","Todas las anteriores.","Zearalenona.","Cumatetralilo."],a:0,
n:"✓ Cuadro típico del <b>metaldehído</b> (molusquicida): predominio nervioso con hiperestesia, espasmos, opistótonos y convulsiones tónico-clónicas, hipertermia severa, taquicardia, taquipnea, hipersalivación y fatiga (apuntes, pp. 33-34).<br>✗ La zearalenona es una micotoxina estrogénica (Fusarium): no da convulsiones.<br>✗ El cumatetralilo es un rodenticida anticoagulante: cursa con hemorragias, anemia y fatiga, no con convulsiones (apuntes, pp. 23-25).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 53 (n.º 29); reco p. 36 (n.º 29).</span>"},
/* recopilación, reco p. 2 (n.º 10) */
{t:1,q:"Seleccione la respuesta correcta:",o:["Actualmente, los organoclorados son la familia de plaguicidas más usados a nivel global, habiendo desplazado a los plaguicidas organofosforados.","La metabolización de algunos plaguicidas produce metabolitos o productos intermedios de naturaleza más tóxica que el compuesto original, como DDE o paraoxón.","Los carbamatos son plaguicidas inhibidores de los receptores de glicina.","Los plaguicidas organofosforados se acumulan principalmente en tejido adiposo."],a:3,d:true,
n:"La clave marca la <b>d</b>, básicamente por eliminación, ya que las otras tres son claramente falsas:<br>✗ a) Los organoclorados <b>están prohibidos</b> (apuntes, p. 14); los más usados hoy son los organofosforados y sobre todo los piretroides (más del 30 % de los insecticidas del mundo, apuntes p. 21).<br>✗ b) El <b>paraoxón</b> sí es más tóxico que su precursor (desulfuración oxidativa de los organofosforados, apuntes p. 16), pero el <b>DDE es menos tóxico que el DDT</b> (hacen falta 15 µg/g de DDE para igualar 1 µg/g de DDT, apuntes p. 11): el enunciado completo es falso.<br>✗ c) Los carbamatos inhiben la <b>acetilcolinesterasa</b> de forma reversible (apuntes, p. 21); quien bloquea los receptores de glicina es la estricnina (p. 26).<br>⚠ d) Tus apuntes dicen que los organofosforados son «muy liposolubles» (p. 15), pero <b>los que se acumulan en hígado y grasa son los organoclorados</b> (p. 13). Acéptala como la clave la da, pero ojo si te la preguntan al revés."},
/* recopilación, reco p. 2 (n.º 11) */
{t:1,q:"De entre estos compuestos, ¿cuál está clasificado como extremadamente tóxico por la OMS?",o:["Endosulfán.","Deltametrina.","Sulfato de cobre.","Aldicarb."],a:3,
n:"✓ El <b>aldicarb</b> (carbamato) tiene una DL50 oral en rata de <b>0,65 mg/kg</b> (apuntes, p. 20): clase Ia de la OMS, extremadamente tóxico.<br>✗ Endosulfán (organoclorado): DL50 43 mg/kg (apuntes, p. 11).<br>✗ Deltametrina (piretroide sintético): DL50 260-600 mg/kg, baja toxicidad en mamíferos (apuntes, p. 21).<br>✗ Sulfato de cobre: fungicida/alguicida mineral, muy lejos de esa categoría.<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 53 (n.º 11).</span>"},
/* recopilación, reco p. 2-3 (n.º 12) */
{t:1,q:"Señale el enunciado correcto:",o:["El paraquat se distribuye principalmente al pulmón.","El aldicarb es un insecticida cuyo mecanismo de acción es la inhibición de la acetilcolinesterasa con una DL50 < 1 mg/kg.","Los fungicidas suelen presentar toxicidad muy alta en mamíferos.","La deltametrina se biomagnifica a lo largo de la cadena trófica."],a:1,
n:"✓ b) El aldicarb es un carbamato inhibidor (reversible) de la acetilcolinesterasa con <b>DL50 oral en rata de 0,65 mg/kg</b>, es decir, < 1 mg/kg (apuntes, pp. 20-21).<br>✗ a) El paraquat se distribuye <b>de forma uniforme</b> por la sangre, sin unirse a proteínas; lo selectivo es su <b>acumulación</b> en pulmón (apuntes, p. 40). Ojo: en otro examen (p. 9, n.º 17) la clave sí dio por buena esta frase, porque allí la opción del aldicarb decía «piretroide» y era falsa.<br>✗ c) Los fungicidas suelen ser poco tóxicos para mamíferos (benomilo DL50 > 10.000 mg/kg, apuntes p. 20); las excepciones son los mercuriales y los fenólicos (apuntes, pp. 44-45).<br>✗ d) Los piretroides se degradan rápidamente y son selectivos para insectos: no se biomagnifican (apuntes, p. 21)."},
/* recopilación, reco p. 3 (n.º 13); variante en p. 16 (n.º 6) */
{t:1,q:"Señale la respuesta correcta:",o:["La estricnina es un antagonista competitivo y reversible de los receptores de glicina.","Todas son correctas.","El animal intoxicado por clorpirifós sufre un cuadro de debilidad y decaimiento en las primeras 24 horas.","El brodifacoum es un antagonista de la vitamina K, ya que deprime la síntesis hepática de las sustancias esenciales para la coagulación de la sangre que son dependientes de la vitamina K, a saber: protrombina (factor II) y los factores VII, IX y X."],a:1,d:true,
n:"La clave de este examen marcó «<b>todas son correctas</b>»:<br>✓ a) Literal de los apuntes (p. 26): la estricnina actúa en el SNC como antagonista competitivo y reversible de los receptores de glicina.<br>✓ d) El brodifacoum es un anticoagulante de 2.ª generación que deprime la síntesis de protrombina y de los factores VII, IX y X, dependientes de vitamina K (apuntes, pp. 23-24).<br>⚠ c) Es la dudosa: el cuadro agudo por organofosforados es de <b>hiperexcitación colinérgica</b>; la debilidad y el decaimiento corresponden al <b>síndrome intermedio</b>, que aparece a las <b>24-96 horas</b>, típicamente en gatos expuestos a clorpirifós (apuntes, p. 19). De hecho, en otro examen con esta misma frase (reco p. 16, n.º 6) la clave marcó solo la de la estricnina y anotó «al revés: hiperexcitable»."},
/* recopilación, reco p. 3 (n.º 14) */
{t:1,q:"En la Unión Europea no pueden autorizarse sustancias activas de productos fitosanitarios a menos que se haya probado científicamente antes que:",o:["Todas son correctas.","Son suficientemente eficaces.","No provocan efectos inaceptables en el medio ambiente.","No producen efectos perjudiciales en los consumidores, los agricultores ni terceros."],a:0,
n:"✓ Es el esquema del Reglamento (CE) n.º 1107/2009 de comercialización de productos fitosanitarios: la legislación europea persigue <b>proteger la salud humana, proteger el medio ambiente y evitar barreras al comercio</b> (apuntes, p. 4), de modo que la sustancia debe ser eficaz y no provocar efectos inaceptables ni en el medio ambiente ni en consumidores, agricultores o terceros."},
/* recopilación, reco p. 3 (n.º 15) */
{t:1,q:"Señale el enunciado INCORRECTO:",o:["La intoxicación por difenacoum produce alteraciones nerviosas.","El endosulfán y el DDT son insecticidas organoclorados.","La estricnina es un alcaloide de la nuez vómica y de otras especies del género Strychnos.","El clorfenvinfós interfiere en la transmisión del impulso nervioso."],a:0,
n:"✗ El difenacoum es un <b>rodenticida anticoagulante de 2.ª generación</b> (apuntes, p. 23): su cuadro es hemorrágico (epistaxis, hematuria, melena, anemia, disnea), no nervioso.<br>✓ El endosulfán (ciclodiénico) y el DDT (difenilalifático) son organoclorados (apuntes, p. 11).<br>✓ La estricnina es un alcaloide de <i>Strychnos nux-vomica</i> y otras especies del género (apuntes, p. 25).<br>✓ El clorfenvinfós es un organofosforado (fosfato) que inhibe la acetilcolinesterasa y altera la transmisión del impulso nervioso (apuntes, pp. 16-18)."},
/* recopilación, reco p. 3 (n.º 16); variante en p. 9 (n.º 16) */
{t:1,q:"Señale el enunciado correcto:",o:["Todas son correctas.","Los síntomas clínicos de envenenamiento por cumarina o indandiona empiezan generalmente después de varios días de la ingestión.","La risa sardónica es un signo característico de intoxicación por estricnina.","Son raras las intoxicaciones secundarias en los que estén implicados rodenticidas anticoagulantes."],a:0,d:true,
n:"La clave marcó «todas son correctas», y lo mismo se deduce de otro examen (p. 13, n.º 17), donde estas tres frases aparecen como verdaderas:<br>✓ b) El periodo de latencia de los anticoagulantes es largo: hay que agotar los factores de coagulación circulantes; el tiempo de protrombina se altera entre las 24-48 horas y 1-3 semanas (apuntes, p. 25). Tú anotaste que en clase se dijo «cumarina, curso agudo, muerte en 1-5 días».<br>✓ c) Labios dirigidos hacia atrás = <b>risa sardónica</b>, signo característico de la estricnina (apuntes, p. 26).<br>⚠ d) En otro examen (p. 9, n.º 16) la clave marcó solo la risa sardónica y tachó el «son raras», es decir, allí se consideró que las intoxicaciones secundarias <b>sí</b> ocurren. Tus apuntes no lo aclaran, así que ten cuidado con esta frase."},
/* recopilación, reco p. 3 (n.º 17) */
{t:1,q:"Sobre insecticidas organofosforados, señale la respuesta INCORRECTA:",o:["Su estabilidad en el medio ambiente depende, entre otros, de factores externos como temperatura, humedad y presencia de microorganismos.","Son potentes disruptores endocrinos.","Algunos de ellos se usan como aditivos de petróleo.","Son biotransformados a través de los microsomas hepáticos."],a:1,
n:"✗ b) La clave la marca como falsa (y se repite en p. 9, n.º 19): tus apuntes no atribuyen a los organofosforados un papel destacado como disruptores endocrinos; el disruptor endocrino de la asignatura es el bisfenol A (apuntes, p. 81).<br>✓ a) Su toxicidad y estabilidad disminuyen por acción del sol, aire, agua y microorganismos, y aumentan con el calor y los rayos UV (apuntes, p. 18).<br>✓ d) Se biotransforman en los microsomas hepáticos: la desulfuración oxidativa pasa las formas tiono a oxo (bioactivación) (apuntes, p. 16).<br>✓ c) El uso como aditivos de petróleo no está en tus apuntes, pero la clave lo da por bueno."},
/* recopilación, reco p. 3-4 (n.º 19) */
{t:1,q:"Sobre el aldicarb, señale la respuesta CORRECTA:",o:["El cuadro tóxico se inicia a los días después de la ingestión del cebo.","Rara vez se consigue tratar al animal aunque el tratamiento es conocido y fácil de aplicar.","Todas son incorrectas.","Es un insecticida piretroide cuyo mecanismo de acción es la inhibición de la colinesterasa."],a:1,
n:"✓ b) Con una DL50 de 0,65 mg/kg el cuadro es fulminante y rara vez da tiempo a tratar, aunque el tratamiento (atropina + descontaminación, sin pralidoxima) sea sencillo y conocido (apuntes, pp. 20-21).<br>✗ a) El cuadro empieza <b>en minutos</b>, no a los días (así lo da por bueno la clave en p. 16, n.º 5).<br>✗ d) Es un <b>carbamato</b>, no un piretroide; sí es cierto que inhibe la colinesterasa, pero de forma reversible y sin envejecimiento de la enzima (apuntes, p. 21)."},
/* recopilación, reco p. 8-9 (n.º 15) */
{t:1,q:"Sobre los insecticidas organoclorados, señale el enunciado correcto:",o:["Son los plaguicidas más utilizados en la actualidad.","Se caracterizan por ser muy hidrosolubles.","Producen anomalías comportamentales por agotamiento encefálico de neurotransmisores.","En el tratamiento de la intoxicación por estos productos es útil y recomendable el uso de estimulantes."],a:2,
n:"✓ c) Mecanismo de los organoclorados (apuntes, p. 13): penetran en la neurona → desequilibrio electrolítico → baja el umbral de excitabilidad → hiperexcitabilidad permanente → <b>agotamiento de neurotransmisores</b> → anomalías del comportamiento.<br>✗ a) Están prohibidos (apuntes, p. 14).<br>✗ b) Son <b>insolubles en agua</b> y muy liposolubles (apuntes, p. 12).<br>✗ d) Serían contraproducentes: los organoclorados ya son estimulantes del SNC. El tratamiento es sintomático (barbitúricos, metocarbamol) y están contraindicados la epinefrina y otras aminas adrenérgicas (apuntes, p. 14)."},
/* recopilación, reco p. 9 (n.º 17) */
{t:1,q:"Señale el enunciado correcto:",o:["El paraquat se distribuye principalmente al pulmón.","El aldicarb es un insecticida piretroide cuyo mecanismo de acción es la inhibición de la acetilcolinesterasa con una DL50 < 1 mg/kg.","Los fungicidas suelen presentar toxicidad muy alta en mamíferos.","La deltametrina se biomagnifica a lo largo de la cadena trófica."],a:0,d:true,
n:"Aquí la clave marca la <b>a</b> porque las otras tres son falsas:<br>✗ b) El aldicarb es un <b>carbamato</b>, no un piretroide (la DL50 < 1 mg/kg sí es correcta: 0,65 mg/kg, apuntes p. 20).<br>✗ c) Los fungicidas suelen tener baja toxicidad en mamíferos, salvo mercuriales y fenólicos (apuntes, pp. 43-45).<br>✗ d) Los piretroides se degradan rápido y son selectivos para insectos y organismos acuáticos; no se biomagnifican (apuntes, p. 21).<br>⚠ a) Matiz importante: según tus apuntes (p. 40) la <b>distribución</b> del paraquat por sangre es uniforme (no se une a proteínas) y lo que es selectivo es su <b>acumulación en pulmón</b>, órgano deficitario en SOD. En la versión de p. 2 (n.º 12) esta misma frase se consideró falsa."},
/* recopilación, reco p. 9 (n.º 18) */
{t:1,q:"Sobre rodenticidas anticoagulantes, señale el enunciado correcto:",o:["La clorofacinona es menos tóxica que la warfarina en humanos, en perro y en gato.","La susceptibilidad de los animales a la warfarina puede aumentar por un consumo de una dieta rica en grasa o de un prolongado tratamiento oral con antibióticos, y el brodifacoum es un antagonista de la vitamina K.","Producen aumento de los factores de coagulación.","El brodifacoum es un antagonista de la vitamina K, pero la clorofacinona es menos tóxica que la warfarina."],a:1,
n:"En el examen original las frases de la warfarina y del brodifacoum iban en opciones distintas y <b>las dos eran verdaderas</b>; aquí se han unido en la b para que solo haya una respuesta correcta.<br>✓ Dieta rica en grasa y antibióticos orales prolongados → deficiencia de vitamina K → mayor susceptibilidad a la warfarina (apuntes, p. 24).<br>✓ El brodifacoum (2.ª generación) antagoniza la vitamina K deprimiendo la síntesis de protrombina y de los factores VII, IX y X (apuntes, pp. 23-24).<br>✗ La clorofacinona es <b>más</b> tóxica que la warfarina: DL50 20,5 mg/kg frente a 58 mg/kg (apuntes, p. 24).<br>✗ Producen <b>descenso</b> de los factores de coagulación, no aumento."},
/* recopilación, reco p. 9 (n.º 19) */
{t:1,q:"Señale el enunciado correcto:",o:["La intoxicación por metaldehído produce bradicardia y depleción de las constantes vitales.","Los organofosforados son potentes disruptores endocrinos.","Algunos insecticidas organofosforados son biotransformados a través de los microsomas hepáticos.","Todas son correctas."],a:2,
n:"✓ c) Biotransformación microsomal hepática: la desulfuración oxidativa convierte las formas tiono en oxo (bioactivación, p. ej. paratión → paraoxón) (apuntes, p. 16).<br>✗ a) El metaldehído da <b>taquicardia, taquipnea, hipertermia severa e hiperestesia</b>, no bradicardia (apuntes, pp. 33-34).<br>✗ b) La clave considera falso que los organofosforados sean potentes disruptores endocrinos (igual que en p. 3, n.º 17)."},
/* recopilación, reco p. 10 (n.º 14) */
{t:1,q:"¿Cuál de los siguientes parámetros medirías en el caso de sospecha de intoxicación por cumarinas?",o:["Tiempo de protrombina.","Determinación de fibrinógeno.","Factores de coagulación.","Todas son correctas."],a:3,
n:"✓ El diagnóstico de los rodenticidas anticoagulantes se apoya en las pruebas de coagulación: el <b>tiempo de protrombina</b> es el parámetro indirecto de elección (se eleva por la reducción de protrombina plasmática, entre las 24-48 h y 1-3 semanas), junto con los factores de coagulación dependientes de vitamina K (II, VII, IX y X) y el fibrinógeno (apuntes, pp. 24-25)."},
/* recopilación, reco p. 10 (n.º 15) */
{t:1,q:"Generalidades sobre rodenticidas anticoagulantes; señale la INCORRECTA:",o:["Prohibidos desde los años 70 en España.","Las enfermedades hepáticas aumentan su toxicidad por menor producción de protrombina.","Pueden producir intoxicación secundaria en especies depredadoras.","La clorofacinona es la más comercializada en España."],a:0,
n:"✗ a) <b>No están prohibidos</b>: se siguen comercializando y tus apuntes recogen como fuentes el consumo de cebos y la exposición ocupacional durante su fabricación, formulación y aplicación (apuntes, p. 23). Lo que sí se prohibió en España (Orden de 4 de febrero de 1994) fue la <b>estricnina</b> (apuntes, p. 25).<br>✓ b) Enfermedades hepáticas → menor producción de protrombina → mayor susceptibilidad (apuntes, p. 24).<br>✓ c) La intoxicación secundaria del depredador que come roedores envenenados es un riesgo clásico de estos productos.<br>✓ d) Dato de clase sobre la comercialización en España (no está en tus apuntes)."},
/* recopilación, reco p. 11 (n.º 18) */
{t:1,q:"Respecto a la estricnina:",o:["Se usa como rodenticida y produce un descenso en los factores de coagulación (II, VII, IX y X) que necesitan la vitamina K para sintetizarse.","Se usa como rodenticida y es un antagonista competitivo y reversible de los receptores de la glicina.","Produce un descenso en los factores de coagulación (II, VII, IX y X) que necesitan la vitamina K para sintetizarse.","Las opciones a y c son correctas."],a:1,
n:"En el examen original «se usa como rodenticida» y «es antagonista de la glicina» iban separadas y <b>ambas eran ciertas</b>; aquí se han unido en una sola opción.<br>✓ La estricnina es un rodenticida y avicida usado contra plagas (apuntes, p. 25) y actúa en el SNC como <b>antagonista competitivo y reversible de los receptores de glicina</b>, provocando estimulación incontrolada de la musculatura esquelética (apuntes, p. 26).<br>✗ El descenso de los factores II, VII, IX y X dependientes de vitamina K corresponde a los <b>rodenticidas anticoagulantes</b> (apuntes, p. 24), no a la estricnina."},
/* recopilación, reco p. 11 (n.º 19) */
{t:1,q:"Sobre los insecticidas neonicotinoides, señale la correcta:",o:["Producen pérdida de orientación (entre otros efectos) en las abejas.","El imidacloprid tiene una toxicidad en torno a 1/3 de la del DDT.","Por presión administrativa no se van a prohibir hasta dentro de mucho tiempo.","Todas son correctas."],a:0,
n:"✓ a) Actúan de modo selectivo e irreversible sobre los receptores nicotínicos de la acetilcolina de los insectos; su toxicidad para las abejas es altísima: DL50 del imidacloprid de 60 ng/abeja a las 48 h y 40 ng/abeja a las 72-96 h (apuntes, p. 22), con pérdida de orientación y colapso de colmenas.<br>✗ b) DL50 oral en rata del imidacloprid: 424 mg/kg (apuntes, p. 22), frente a 113-450 mg/kg del DDT (apuntes, p. 11): toxicidad similar o incluso menor, no un tercio.<br>✗ c) La UE ha ido restringiendo y prohibiendo sus usos en exterior."},
/* recopilación, reco p. 13 (n.º 17) */
{t:1,q:"Sobre los rodenticidas anticoagulantes, señale el enunciado INCORRECTO:",o:["La clorofacinona es menos tóxica que la warfarina en humanos y en perros y gatos.","Los síntomas generales de envenenamiento por cumarina o indandiona empiezan generalmente después de varios días de la ingestión.","Son raras las intoxicaciones secundarias en los que estén implicados estos productos.","La susceptibilidad de los animales a la warfarina puede aumentar por consumo de una dieta rica en grasa o de un prolongado tratamiento con antibióticos."],a:0,
n:"✗ a) Es al revés: la <b>clorofacinona es más tóxica</b> que la warfarina (DL50 20,5 frente a 58 mg/kg, apuntes p. 24).<br>✓ b) El periodo de latencia es largo (hay que agotar los factores circulantes); el tiempo de protrombina se altera entre 24-48 h y 1-3 semanas (apuntes, p. 25).<br>✓ d) Dieta rica en grasa y antibióticos orales prolongados → deficiencia de vitamina K → mayor susceptibilidad (apuntes, p. 24).<br>⚠ c) La clave de este examen la da por verdadera, pero en p. 9 (n.º 16) el «son raras» aparece tachado: es una frase que el profesor ha usado en los dos sentidos.<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 39 (n.º 67).</span>"},
/* recopilación, reco p. 13 (n.º 19) */
{t:1,q:"Respecto a la estricnina, señale el enunciado correcto:",o:["En España se prohíbe en el año 2015.","Es un antagonista competitivo y reversible de los receptores de la acetilcolina.","La risa sardónica es un signo característico de intoxicación por ella.","Todas son correctas."],a:2,
n:"✓ c) Los labios dirigidos hacia atrás («risa sardónica») son un signo característico, junto con las contracciones tetánicas, la postura en caballete y el cuello arqueado (apuntes, p. 26).<br>✗ a) Se prohibió en <b>1994</b> (Orden de 4 de febrero de 1994, que prohíbe importar, comercializar y utilizar plaguicidas ambientales con estricnina) (apuntes, p. 25).<br>✗ b) Es antagonista de los receptores de <b>glicina</b>, no de la acetilcolina (apuntes, p. 26)."},
/* recopilación, reco p. 13-14 (n.º 20) */
{t:1,q:"Señale el enunciado INCORRECTO:",o:["La atropina es usada en el tratamiento de intoxicaciones por clorpirifós.","Los insecticidas organofosforados y carbamatos son insecticidas de uso habitual (enunciado cortado en el original).","Los piretroides son componentes de aerosoles domésticos.","La deltametrina se biomagnifica a lo largo de la cadena trófica."],a:3,
n:"✗ d) La deltametrina es un <b>piretroide sintético</b>: de alta degradación, selectivo para insectos y poco tóxico para animales superiores (salvo peces); <b>no se biomagnifica</b> (apuntes, p. 21).<br>✓ a) El clorpirifós es un organofosforado y su tratamiento genérico es el <b>sulfato de atropina</b> 0,2-1 mg/kg (¼ i.v. y el resto s.c.), repitiendo a las 6 h si recidiva, más pralidoxima (apuntes, p. 20).<br>✓ c) Los piretroides se formulan en aerosoles, polvos, champús, collares y sprays domésticos (apuntes, p. 21).<br>⚠ b) En la compilación esta opción aparece cortada («Los insecticidas organofosforados y carbamatos…»); tú anotaste que faltaban organoclorados y piretroides."},
/* recopilación, reco p. 15 (n.º 5; el enunciado estaba cortado en la compilación) */
{t:1,q:"Señale la respuesta INCORRECTA sobre los mecanismos de acción:",o:["El ácido cianhídrico inhibe la citocromo oxidasa alterando así la respiración celular.","El clorfenvinfós inhibe la glicina alterando la transmisión sináptica colinérgica.","El plomo inhibe la hemosintetasa alterando la síntesis hemática.","El arsénico inhibe la piruvato deshidrogenasa alterando el catabolismo oxidativo."],a:1,
n:"✗ b) El clorfenvinfós es un <b>organofosforado</b>: inhibe la <b>acetilcolinesterasa</b> (apuntes, pp. 16-18). Quien antagoniza los receptores de <b>glicina</b> es la estricnina (apuntes, p. 26). Además, la frase mezcla glicina (inhibitoria) con transmisión colinérgica.<br>✓ a) El ion cianuro bloquea la citocromo oxidasa → anoxia histotóxica.<br>✓ c) El plomo interfiere en la síntesis del grupo hemo (ALAD como biomarcador y bloqueo de la hemosintetasa/ferroquelatasa) (apuntes, pp. 55-56).<br>✓ d) El arsénico altera proteínas y enzimas con grupos sulfhidrilo y paraliza la respiración celular mitocondrial, con inhibición de la piruvato deshidrogenasa (apuntes, p. 72)."},
/* recopilación, reco p. 15-16 (n.º 5) */
{t:1,q:"Sobre el aldicarb, señale la respuesta INCORRECTA:",o:["El cuadro tóxico se inicia minutos después de la ingestión del cebo.","Es un insecticida piretroide cuyo mecanismo de acción es la inhibición de la acetilcolinesterasa.","Rara vez se consigue tratar al animal aunque el tratamiento es conocido y fácil de aplicar.","Es un carbamato con una DL50 < 1 mg/kg."],a:1,
n:"✗ b) El aldicarb es un <b>carbamato</b>, no un piretroide (apuntes, p. 20). Lo de inhibir la acetilcolinesterasa sí es cierto (de forma reversible y sin envejecimiento de la enzima, apuntes p. 21).<br>✓ d) DL50 oral en rata: <b>0,65 mg/kg</b> (apuntes, p. 20).<br>✓ a) y ✓ c) El cuadro es fulminante y rara vez da tiempo a tratarlo, aunque el tratamiento (atropina y descontaminación digestiva, sin pralidoxima) es sencillo.<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 19 (n.º 18).</span>"},
/* recopilación, reco p. 16 (n.º 8) */
{t:1,q:"Sobre generalidades de los rodenticidas anticoagulantes, señale el enunciado CORRECTO:",o:["Las enfermedades hepáticas hacen a los animales más sensibles a estos compuestos por una menor producción de protrombina.","Los síntomas clínicos de envenenamiento por cumarina o indandiona empiezan generalmente después de varios días de la ingestión.","La susceptibilidad de los animales a la warfarina puede aumentar por un consumo de una dieta rica en grasa o de un prolongado tratamiento oral con antibióticos.","Todas son correctas."],a:3,
n:"✓ Todas son ciertas: los factores que modifican la toxicidad de los anticoagulantes son la <b>dieta rica en grasa</b> y los <b>tratamientos orales prolongados con antibióticos</b> (deficiencia de vitamina K) y las <b>enfermedades hepáticas</b> (menor producción de protrombina), que aumentan la susceptibilidad a la warfarina (apuntes, p. 24); y el periodo de latencia es de varios días, porque hay que agotar los factores de coagulación circulantes (apuntes, p. 25).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 19 (n.º 20); reco p. 36 (n.º 24).</span>"},
/* recopilación, reco p. 7 (preguntas cortas, Plaguicidas n.º 1) */
{t:1,q:"¿En qué consiste el mecanismo de acción de los herbicidas cloratos?",o:["Irritación del tubo digestivo, acción metahemoglobinizante y hemólisis, que en conjunto provocan anoxia.","Desacoplamiento de la fosforilación oxidativa con hipertermia intensa.","Estrés oxidativo pulmonar por generación de radicales superóxido.","Inhibición irreversible de la acetilcolinesterasa."],a:0,
n:"✓ Apuntes, p. 36: los cloratos son irritantes del tubo digestivo, metahemoglobinizantes y hemolíticos, y los tres mecanismos acaban provocando <b>anoxia</b>. Por eso la sangre se ve «color chocolate» y el tratamiento es <b>azul de metileno al 1 %</b> i.v., que reduce la metahemoglobina a hemoglobina (apuntes, p. 37).<br>✗ Desacoplar la fosforilación oxidativa es el mecanismo de los <b>dinitrofenoles</b> (apuntes, p. 39).<br>✗ El estrés oxidativo pulmonar es del <b>paraquat</b> (apuntes, pp. 40-41).<br>✗ La inhibición de la colinesterasa es de organofosforados y carbamatos.<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Plaguicidas n.º 2) */
{t:1,q:"Cite al menos tres factores que puedan modificar (aumentar) la toxicidad de los rodenticidas anticoagulantes:",o:["Dieta rica en grasa, tratamientos orales prolongados con antibióticos y enfermedades hepáticas.","Dieta rica en vitamina K, ayuno prolongado y edad avanzada.","Dieta rica en proteínas, tratamiento con barbitúricos y temperatura ambiental baja.","Dieta rica en calcio, hipertiroidismo y ejercicio intenso."],a:0,
n:"✓ Apuntes, p. 24: <b>dieta rica en grasa</b> y <b>tratamiento oral prolongado con antibióticos</b> → deficiencia de vitamina K; <b>enfermedades hepáticas</b> → menor producción de protrombina. Todos aumentan la susceptibilidad (p. ej. a la warfarina).<br>✗ Una dieta rica en vitamina K protegería, no agravaría.<br>✗ El hipertiroidismo y el ejercicio aumentan la toxicidad de los <b>fungicidas fenólicos</b>, no de los anticoagulantes (apuntes, p. 45).<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Plaguicidas n.º 3) */
{t:1,q:"Ante un animal intoxicado por clorpirifós, ¿cuáles serían las pautas de tratamiento a seguir?",o:["Sulfato de atropina (0,2-1 mg/kg: ¼ i.v. y el resto s.c.), repitiendo a las 6 h si recidiva, pralidoxima i.m. o i.v., descontaminación digestiva (vómito si han pasado < 2 h o lavado gástrico con carbón activado) y vigilancia respiratoria.","Vitamina K1 durante varias semanas, transfusión si hay anemia y reposo absoluto.","Azul de metileno al 1 % i.v. y purgantes salinos.","BAL intramuscular cada 4 horas junto con fluidoterapia."],a:0,
n:"✓ El clorpirifós es un <b>organofosforado</b>: tratamiento genérico con sulfato de atropina (0,2-1 mg/kg, ¼ i.v. y el resto s.c.; repetir a las 6 h a 0,1-0,5 mg/kg), inducción del vómito antes de 2 h o lavado gástrico con carbón activado, diazepam, rehidratación, furosemida y vigilancia respiratoria; el tratamiento específico es la <b>pralidoxima</b> 20 mg/kg i.m./i.v., más eficaz junto a la atropina (apuntes, p. 20).<br>✗ La vitamina K1 es el antídoto de los rodenticidas anticoagulantes.<br>✗ El azul de metileno es para los cloratos (apuntes, p. 37).<br>✗ El BAL es un quelante de metales.<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Plaguicidas n.º 4) */
{t:1,q:"¿Cuáles son los principales hallazgos postmortem en un animal intoxicado por metaldehído?",o:["Olor estomacal a formaldehído, órganos muy congestivos, petequias en la mucosa gástrica, degeneración hepática y de las células ganglionares del cerebro, y edema agudo con hemorragias pulmonares.","Hemorragias generalizadas, corazón redondeado y flácido con hemorragias subepicárdicas y necrosis hepática centrolobulillar.","Rigidez cadavérica muy rápida, cianosis y ausencia de lesiones macroscópicas características, con el estómago lleno de cebo sin digerir.","Sangre de color chocolate, mucosas cianóticas y tejidos oscuros."],a:0,
n:"✓ Apuntes, p. 34: olor estomacal a formaldehído, intensa congestión hepática, renal, pulmonar y encefálica, petequias y hemorragias equimóticas en la mucosa gastrointestinal, edema agudo y hemorragias pulmonares y degeneración hepática y de las células ganglionares del cerebro.<br>✗ La segunda descripción es la de los <b>rodenticidas anticoagulantes</b> (apuntes, p. 25).<br>✗ La tercera es la de la <b>estricnina</b> (apuntes, p. 26).<br>✗ La cuarta es la de los <b>cloratos</b> (apuntes, p. 37).<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Plaguicidas n.º 5) */
{t:1,q:"¿Por qué se caracteriza el mecanismo de acción del DDT?",o:["Es un insecticida organoclorado estimulante del SNC: desequilibra los electrolitos de la neurona, baja el umbral de excitabilidad y acaba agotando los neurotransmisores.","Inhibe de forma irreversible la acetilcolinesterasa, con envejecimiento de la enzima.","Es un antagonista competitivo y reversible de los receptores de glicina.","Prolonga la apertura de los canales de sodio de la membrana nerviosa."],a:0,
n:"✓ Apuntes, p. 13: los organoclorados son <b>estimulantes del SNC</b> (sin receptores específicos): penetran en las neuronas → desequilibrio electrolítico → desciende el umbral de excitabilidad → hiperexcitabilidad permanente → agotamiento de neurotransmisores y anomalías del comportamiento; además aumentan el amoniaco y la glutamina (convulsiones y temblores).<br>✗ La inhibición irreversible con envejecimiento de la enzima es de los <b>organofosforados</b> (apuntes, p. 17).<br>✗ El antagonismo de la glicina es de la <b>estricnina</b> (apuntes, p. 26).<br>✗ La alteración de los canales de sodio es de los <b>piretroides</b> (apuntes, p. 21).<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 19 (n.º 16) */
{t:1,q:"¿Cuál de las siguientes familias de plaguicidas crees que, en regla general, presenta mayor persistencia ambiental?",o:["Carbamatos.","Organoclorados.","Organofosforados.","Rodenticidas."],a:1,
n:"Examen de junio de 2017.<br>✓ <b>B</b>: los organoclorados son «muy persistentes y poco biodegradables», con bioacumulación y biomagnificación (apuntes, p. 12; resumen de la recopilación, p. 54).<br>✗ Los carbamatos son «muy poco persistentes en la naturaleza» (apuntes, p. 20) y los organofosforados «sustituyeron a los OCl por ser menos persistentes y bioacumulables» (apuntes, p. 15).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 42 (n.º 200).</span>"},
/* recopilación, reco p. 19 (n.º 17) */
{t:1,q:"Selecciona la respuesta incorrecta.",o:["Los plaguicidas organofosforados se acumulan principalmente en el tejido adiposo.","La metabolización de algunos plaguicidas produce metabolitos o productos intermedios de naturaleza más tóxica que el compuesto original, como el DDE o el paratión.","Los carbamatos son plaguicidas anticolinesterásicos."],a:1,
n:"Examen de junio de 2017 (esta pregunta solo tenía tres opciones).<br>✗ <b>B</b> (la incorrecta): el principio es cierto, pero <b>los ejemplos están cambiados</b>. El DDE es un metabolito <b>menos</b> tóxico que el DDT (hacen falta 15 µg/g de DDE para igualar a 1 µg/g de DDT, apuntes, p. 11) y el paratión es el compuesto original: el metabolito más tóxico es el <b>paraoxón</b>, formado por desulfuración oxidativa (apuntes, p. 16). Los ejemplos correctos serían DDT→DDE (a la baja) y paratión→paraoxón (al alza).<br>✓ <b>C</b>: los carbamatos inhiben la AChE igual que los OP, pero de forma reversible y sin envejecimiento (apuntes, p. 21).<br>Matiz sobre <b>A</b>: los OP son muy liposolubles (apuntes, p. 15), pero los que de verdad se acumulan en la grasa son los <b>organoclorados</b> (apuntes, p. 12); aun así la clave del examen señala la B, que es falsa sin discusión."},
/* recopilación, reco p. 19 (n.º 19) */
{t:1,q:"Sobre los insecticidas neonicotinoides, señale el enunciado incorrecto:",o:["Imidacloprid es el más usado.","Pueden producir pérdidas de orientación en abejas.","La mayoría tienen una DL50 en abejas mucho más alta que la del DDT y aparecieron en los años 50.","Actúan de modo selectivo e irreversible sobre los receptores nicotínicos de la acetilcolina de los insectos."],a:2,d:true,
n:"Examen de junio de 2017. <b>Pregunta retocada</b>: en el original las opciones C («DL50 en abejas mucho más altas que el DDT») y D («aparecieron en los años 50») <b>eran falsas las dos</b>, así que se han juntado en una sola opción (la C) y la D se ha sustituido por un enunciado verdadero; la recopilación escribió «TODAS CORRECTAS», lo que contradice a tus apuntes.<br>✗ <b>C</b>: los neonicotinoides «fueron introducidos en la agricultura en los <b>años 90</b>» (apuntes, p. 22). Y su DL50 en abeja es muchísimo <b>más baja</b> (más tóxicos): imidacloprid 60 ng/abeja a las 48 h y 40 ng/abeja a las 72-96 h (apuntes, p. 22), frente a los 115-430 ng/abeja del DDT que anota el propio examen a mano.<br>✓ <b>A</b>, <b>B</b> y <b>D</b>: el imidacloprid es el más usado y actúan «de modo selectivo e irreversible sobre los receptores nicotínicos de la acetilcolina en las células nerviosas de los insectos», lo que explica la desorientación de las abejas (apuntes, p. 22)."},
/* recopilación, reco p. 53 (n.º 18) */
{t:1,q:"Identifica el grupo al que pertenecen, respectivamente, el endosulfán, el brodifacoum, el clorfenvinfos y el morfamquat:",o:["Organoclorado, rodenticida anticoagulante (derivado hidroxicumarínico), organofosforado y herbicida bipiridílico.","Organofosforado, rodenticida anticoagulante (indandiona), organoclorado y herbicida bipiridílico.","Organoclorado, molusquicida, carbamato y herbicida clorofenoxiderivado.","Carbamato, rodenticida anticoagulante (indandiona), organofosforado y fungicida ditiocarbamato."],a:0,
n:"Pregunta de examen de la recopilación (bloque 5: metales y plaguicidas); en el original era de respuesta abierta («identificar en una única palabra/frase el mecanismo de acción»), aquí se ha pasado a tipo test.<br>✓ <b>Endosulfán</b>: ciclodiénico organoclorado, DL50 43 mg/kg (apuntes, p. 11).<br>✓ <b>Brodifacoum</b>: rodenticida anticoagulante de <b>segunda</b> generación, derivado de la 4-hidroxicumarina, DL50 0,26 mg/kg (apuntes, pp. 23-24; resumen de la recopilación, p. 55).<br>✓ <b>Clorfenvinfos</b>: organofosforado del grupo fosfato (apuntes, p. 16), inhibidor irreversible de la AChE.<br>✓ <b>Morfamquat</b>: herbicida orgánico bipiridílico, como el paraquat y el diquat, de 1.ª categoría toxicológica (DL50 < 200 mg/kg) (apuntes, pp. 35-36)."},
/* recopilación, reco p. 51 (supuestos 1 y 2) */
{t:1,q:"Perro braco de 5 años y 25 kg que aparece en el jardín con temblores, hipersalivación y sin responder a la llamada. El veterinario observa salivación profusa, miosis pupilar persistente, respiración agitada, micción y defecación líquida involuntarias, temblores repetidos y pulso imperceptible con bradicardia; junto al animal había un trozo de pan con bolitas duras de color lila. ¿Cuál es el diagnóstico presuntivo y cómo se trata?",o:["Intoxicación por un inhibidor de la acetilcolinesterasa (organofosforado o carbamato): sulfato de atropina para contrarrestar el síndrome muscarínico, más el tratamiento general de la intoxicación; si es un carbamato, no se usa pralidoxima.","Intoxicación por un inhibidor de la acetilcolinesterasa: pralidoxima como antídoto de elección en cualquier caso, acompañada de barbitúricos de acción corta.","Intoxicación por organoclorado: lavado gástrico con carbón activo y estimulantes del SNC para revertir la depresión.","Intoxicación por rodenticida anticoagulante: vitamina K1 y transfusión de plasma, más sueroterapia."],a:0,
n:"Supuesto práctico de la recopilación. El cuadro es un <b>síndrome colinérgico</b> de libro: fase muscarínica con salivación intensa, miosis, broncoconstricción, bradicardia, diarrea y micción abundante, más la fase nicotínica con temblores y fasciculaciones (apuntes, p. 19). Las bolitas lilas del cebo apuntan a <b>carbofurano</b>, un carbamato.<br>✓ Tratamiento: sulfato de atropina 0,2-1 mg/kg (¼ IV y el resto SC), inducción del vómito o lavado gástrico con carbón activado, diazepam, fluidoterapia y vigilancia respiratoria (apuntes, p. 20).<br>✗ La <b>pralidoxima</b> es el tratamiento específico de los organofosforados, pero «no se debe usar» en carbamatos, porque su inhibición es reversible y no hay envejecimiento de la AChE (apuntes, p. 21).<br>Muestras: si el animal vive, sangre, orina, vómito y lavado gástrico; si muere, hígado, riñón, cerebro, sangre, orina y contenido intestinal."},
/* recopilación, reco p. 52 (supuesto 4) */
{t:1,q:"Perro que a las 9:30 se metió entre unos matorrales y a las 10:30 llega casi inconsciente tras ataques convulsivos. El veterinario ve salivación, temblores, contracciones musculares y convulsiones que se desencadenan al manipularlo, vista perdida, y el animal ha vomitado restos de paté junto con pellets cilíndricos de color verde. ¿Cuál es el diagnóstico presuntivo?",o:["Intoxicación por metaldehído (molusquicida).","Intoxicación por estricnina.","Intoxicación por rodenticida anticoagulante.","Intoxicación por organofosforado."],a:0,
n:"Supuesto práctico de la recopilación; la propia recopilación avisa de que «mucha gente hemos puesto Estricnina pero la solución era METALDEHÍDO».<br>✓ La clave son los <b>pellets cilíndricos verdes</b> (metaldehído, color verde; resumen de la recopilación, p. 55) dentro de un cebo apetecible como el paté, y el cuadro nervioso con convulsiones desencadenadas por estímulos táctiles, visuales y auditivos, hiperestesia, ataxia, hipersalivación e hipertermia (apuntes, pp. 33-34).<br>✗ La <b>estricnina</b> daría contracciones tetánicas violentas con postura en caballete y risa sardónica, y está prohibida desde la Orden de 4 de febrero de 1994 (apuntes, pp. 25-26).<br>Tratamiento: descontaminación digestiva (lavado gástrico bajo anestesia y carbón activado con catárticos; <b>no</b> provocar el vómito en animal sintomático), bajar la temperatura y barbitúricos de acción corta —pentobarbital/fenobarbital—. Buen pronóstico si sobrevive 24 horas (apuntes, pp. 34-35)."},
/* recopilación, reco p. 52 (supuesto 5) */
{t:1,q:"En la zona donde pastan unos caballos hay almendros, alfalfa y tréboles, y hace 15 días se pusieron bloques de raticida anticoagulante porque había muchas ratas. El caballo no tiene diarrea ni vómito, pero presenta petequias generalizadas sobre todo en pene y prepucio, líquido en cavidad torácica en la ecografía y una analítica normal salvo un retraso del tiempo de coagulación. ¿Cuál es el diagnóstico presuntivo?",o:["Intoxicación por rodenticida anticoagulante, agravada por el consumo de tréboles.","Intoxicación por cianuro procedente de las almendras amargas.","Intoxicación crónica por cobre con crisis hemolítica.","Intoxicación por fosfuro de cinc del cebo raticida."],a:0,
n:"Supuesto práctico de la recopilación («era intoxicación por rodenticida anticoagulante + tréboles»).<br>✓ Los anticoagulantes inhiben la síntesis de los factores de la coagulación dependientes de la vitamina K (protrombina, VII, IX y X) y aumentan la permeabilidad capilar: hemorragias, petequias, equimosis, edemas y derrames, con tiempo de protrombina alargado entre las 24-48 h y hasta 1-3 semanas (apuntes, pp. 24-25). Los <b>tréboles</b> (dicumarol del trébol enmohecido) producen el mismo cuadro y suman efecto: «síntomas igual que rodenticidas anticoagulantes. Tréboles, Férula» (resumen de la recopilación, p. 56).<br>✗ El cianuro mata en minutos con disnea y sangre brillante sin coagular; el cobre crónico cursa con hemoglobinuria e ictericia; el fosfuro de cinc da olor a ajo, vómitos con sangre y timpanismo, no coagulopatía.<br>Tratamiento: retirar la fuente, vitamina K y transfusión (de sangre si es severa, de plasma si es moderada) (resumen de la recopilación, pp. 55-56)."},
/* recopilación, reco p. 35 (n.º 13) */
{t:1,q:"Identifica la utilidad biocida de los siguientes plaguicidas: dicofol, 2,4-diclorofenoxiacético, diclorvos y bromadiolona",o:["Dicofol → insecticida (organoclorado); 2,4-D → herbicida; diclorvos → insecticida (organofosforado); bromadiolona → rodenticida","Dicofol → insecticida (organoclorado); 2,4-D → fungicida; diclorvos → insecticida (organofosforado); bromadiolona → rodenticida","Dicofol → insecticida (organoclorado); 2,4-D → herbicida; diclorvos → insecticida (organofosforado); bromadiolona → molusquicida","Dicofol → herbicida; 2,4-D → herbicida; diclorvos → rodenticida; bromadiolona → rodenticida"],a:0,
n:"En la recopilación es una pregunta de identificar cada plaguicida con una palabra, y las cuatro respuestas correctas se han agrupado en una sola opción (las demás llevan algún error). El <b>dicofol</b> es un insecticida-acaricida organoclorado difenilalifático, análogo del DDT (apuntes, p. 11); el <b>2,4-D</b> es un herbicida clorofenoxiderivado (p. 36); el <b>diclorvos</b> es un insecticida organofosforado del grupo fosfato (p. 16); y la <b>bromadiolona</b> es un rodenticida anticoagulante de segunda generación (p. 23)."},
/* recopilación, reco p. 35 (n.º 14) */
{t:1,q:"Sobre el DDT, señale la correcta",o:["Su alta acción fungicida es la responsable de su gran uso en la década de los 60","Es el tratamiento de elección recomendado en casos de plagas rebeldes","Es altamente persistente en medios acuáticos pero no en medios terrestres","Recientemente, la OMS ha vuelto a incorporarlo en su programa de erradicación de la malaria"],a:3,
n:"Tus apuntes dedican un apartado a <b>«El regreso del DDT»</b>: casi 40 años después de restringirse su uso, la OMS anunció que volvería a formar parte de su programa para erradicar la malaria, fumigando el interior de las viviendas (apuntes, p. 15). ✗ El DDT es un <b>insecticida</b> organoclorado, no un fungicida. ✗ Está prohibido como plaguicida agrícola, así que no es tratamiento de elección de ninguna plaga. ✗ Es muy persistente en <b>todos</b> los medios: poco biodegradable, se une a la fracción sólida del suelo y a los sedimentos y se bioacumula (apuntes, p. 12 y 14)."},
/* recopilación, reco p. 35 (n.º 15; repetida en p. 36 n.º 30) */
{t:1,q:"La pralidoxima previene el envejecimiento irreversible de la AChE intersináptica, que es el mecanismo tóxico de acción de alguno de los siguientes plaguicidas",o:["Organoclorados","Carbamatos","Organofosforados","B y C son ciertas"],a:2,
n:"El <b>envejecimiento</b> de la acetilcolinesterasa fosforilada es exclusivo de los <b>organofosforados</b>, y la pralidoxima (20 mg/kg IM o IV, repetible a las 12 h y más eficaz junto con atropina) es su tratamiento específico (apuntes, p. 17 y 20). ✗ En los <b>carbamatos</b> la inhibición es reversible y no hay envejecimiento, por lo que <b>no debe usarse pralidoxima</b> (apuntes, p. 21). ✗ Los organoclorados no actúan sobre la AChE: son estimulantes inespecíficos del SNC (apuntes, p. 13).<br>La misma pregunta se repite en p. 36 (n.º 30) con idéntica respuesta."},
/* recopilación, reco p. 35 (n.º 16) */
{t:1,q:"Solo uno de los plaguicidas siguientes puede tratarse eficazmente con pralidoxima dentro de las 24 h posteriores a la ingestión",o:["Diclorvos","Resmetrina","Carbaril","DDT"],a:0,
n:"El <b>diclorvos</b> es un organofosforado (grupo fosfato, apuntes, p. 16) y la pralidoxima solo reactiva la AChE inhibida por organofosforados, siempre que se administre antes de que la enzima envejezca (apuntes, p. 17 y 20). ✗ La <b>resmetrina</b> es un piretroide: actúa sobre los canales de sodio de la membrana nerviosa (p. 21). ✗ El <b>carbaril</b> es un carbamato: inhibición reversible, sin envejecimiento, y la pralidoxima está desaconsejada (p. 20-21). ✗ El <b>DDT</b> es un organoclorado, sin antídoto específico (p. 14)."},
/* recopilación, reco p. 35 (n.º 17) */
{t:1,q:"Identifica la clasificación química de los siguientes plaguicidas: endosulfán, brodifacoum, clorfenvinfos y morfamquat",o:["Endosulfán → organoclorado; brodifacoum → derivado hidroxicumarínico; clorfenvinfos → organofosforado; morfamquat → bipiridílico","Endosulfán → organofosforado; brodifacoum → derivado hidroxicumarínico; clorfenvinfos → organoclorado; morfamquat → bipiridílico","Endosulfán → organoclorado; brodifacoum → indandiona; clorfenvinfos → organofosforado; morfamquat → clorofenoxiderivado","Endosulfán → piretroide; brodifacoum → derivado hidroxicumarínico; clorfenvinfos → carbamato; morfamquat → bipiridílico"],a:0,
n:"Las cuatro parejas de la recopilación son correctas y se han agrupado en una sola opción. El <b>endosulfán</b> es un organoclorado ciclodiénico (DL50 43 mg/kg; apuntes, p. 11); el <b>brodifacoum</b> es un derivado de la <b>4-hidroxicumarina</b> de segunda generación (p. 23); el <b>clorfenvinfos</b> es un organofosforado del grupo fosfato (p. 16); y el <b>morfamquat</b> es un herbicida bipiridílico, como el paraquat y el diquat (p. 36). ✗ Las indandionas son clorofacinona, difacinona, pindona y valona."},
/* recopilación, reco p. 35 (n.º 18) */
{t:1,q:"Identifica el mecanismo de acción de los siguientes plaguicidas: diquat, bromadiolona, benfuracarb y malatión",o:["Diquat → peroxidación por radicales libres; bromadiolona → anticoagulante; benfuracarb → anticolinesterásico; malatión → anticolinesterásico","Diquat → anticolinesterásico; bromadiolona → anticoagulante; benfuracarb → peroxidación; malatión → anticolinesterásico","Diquat → peroxidación por radicales libres; bromadiolona → anticolinesterásico; benfuracarb → anticoagulante; malatión → anticolinesterásico","Diquat → peroxidación por radicales libres; bromadiolona → anticoagulante; benfuracarb → anticolinesterásico; malatión → antagonista de la glicina"],a:0,
n:"Las cuatro respuestas de la recopilación se han agrupado en una sola opción. El <b>diquat</b> (bipiridílico) es un magnífico aceptor de electrones: se reduce con facilidad, genera <b>radicales libres</b> y produce peroxidación lipídica (apuntes, p. 40). La <b>bromadiolona</b> es un anticoagulante de segunda generación (p. 23). El <b>benfuracarb</b> es un carbamato y el <b>malatión</b> un organofosforado (fosforoditioato): los dos <b>inhiben la acetilcolinesterasa</b>, de forma reversible el carbamato e irreversible el organofosforado (p. 16, 18 y 21). ✗ El antagonismo de la glicina es el mecanismo de la estricnina (p. 26)."},
/* recopilación, reco p. 35 (n.º 19) */
{t:1,q:"Sobre los compuestos organoclorados, señale la correcta",o:["Se eliminan por la leche (sin biotransformar), por los huevos y en menor medida por las heces y la orina","Las categorías más importantes de plaguicidas son: insecticidas, funguicidas, alguicidas, rodenticidas, planticidas y mamiferocidas","Entre los problemas más importantes derivados del excesivo uso de plaguicidas organoclorados se encuentran su elevada tasa de acumulación en plantas acuáticas y su persistencia en capas altas de la atmósfera","Los insecticidas organoclorados pueden agruparse por su estructura química en tres clases: dibencilotilfenildioxialifáticos (DDPs), hepatocilodienos fluorados y oximinoclorofluorohexaninos"],a:0,
n:"Por su enorme liposolubilidad los organoclorados pasan a la grasa y se excretan sin biotransformar con la <b>leche</b> y los <b>huevos</b>: de ahí que tus apuntes citen como fuente de intoxicación «carne con residuos de insecticidas o leche con residuos» (apuntes, p. 11); la eliminación es bifásica, un 50 % en los 3-4 primeros días y el resto muy lentamente desde hígado y grasa (p. 13). ✗ No existen las categorías «planticidas» ni «mamiferocidas». ✗ El problema de los organoclorados es su <b>bioacumulación y biomagnificación</b> en la cadena trófica y su persistencia en suelo y sedimentos; son insolubles en agua (p. 12 y 14). ✗ Se agrupan en <b>difenilalifáticos</b> (DDT y análogos, metoxicloro), <b>ciclodienos</b> (aldrín, dieldrín, endosulfán), <b>hexaclorociclohexanos</b> (lindano) y otros (p. 11)."},
/* recopilación, reco p. 35 (n.º 20) */
{t:1,q:"Señale la correcta",o:["El bromofos y el fosmet son insecticidas organofosforados","El clorfenvinfos y el DDT son insecticidas organoclorados","El paraquat es un herbicida nitrofenólico","El difenacoum es un avicida"],a:0,
n:"El <b>bromofos</b> (O-alquil fosforotioato) y el <b>fosmet</b> (fosforoditioato) figuran en la clasificación química de los organofosforados de tus apuntes (p. 16). ✗ El clorfenvinfos es un <b>organofosforado</b> (el DDT sí es organoclorado). ✗ El paraquat es un herbicida <b>bipiridílico</b>, no nitrofenólico (p. 36 y 40). ✗ El difenacoum es un <b>rodenticida</b> anticoagulante de segunda generación (p. 23)."},
/* recopilación, reco p. 35 (n.º 21) */
{t:1,q:"Sobre el aldicarb, señale la correcta",o:["Es un carbamato con una DL50 menor de 1 mg/kg","Es un organoclorado con una DL50 mayor de 100 mg/kg","Es un organofosforado con una DL50 de 230 mg/kg","Es un piretroide con una DL50 mayor de 1000 mg/kg"],a:0,d:true,
n:"El <b>aldicarb</b> es un carbamato (éster del ácido carbámico) y el más tóxico de su grupo: <b>DL50 oral en rata de 0,65 mg/kg</b>, frente a 6-7,8 del carbofurano, 230 del carbaril o más de 10.000 del benomilo (apuntes, p. 20). ⚠ En la recopilación esta pregunta solo conserva la opción correcta; las otras tres se han redactado a partir de tus apuntes para que el ítem sea utilizable."},
/* recopilación, reco p. 35-36 (n.º 22) */
{t:1,q:"Sobre el aldicarb, señale la INCORRECTA",o:["El cuadro tóxico se inicia minutos después de la ingestión del cebo","Es un insecticida piretroide cuyo mecanismo de acción es la inhibición de la acetilcolinesterasa","Rara vez se consigue tratar al animal, aunque el tratamiento es conocido y fácil de aplicar","Ha sido prohibida su venta, su uso y su tenencia"],a:1,
n:"El aldicarb es un <b>carbamato</b>, no un piretroide: los piretroides no inhiben la AChE, sino que <b>modifican los canales de sodio</b> de la membrana de la célula nerviosa (apuntes, p. 21), tal y como corrige a mano la recopilación. ✓ El cuadro se inicia en minutos por la inhibición anticolinesterásica, de ahí que el animal rara vez llegue vivo al tratamiento (atropina, lavado gástrico y carbón activado; nunca pralidoxima, apuntes, p. 20-21). ✓ Su venta, uso y tenencia están prohibidos."},
/* recopilación, reco p. 36 (n.º 23) */
{t:1,q:"Sobre el aldicarb, señale la INCORRECTA",o:["Es un metil-carbamato, de la misma familia que el carbofurano y el metomilo","El cuadro tóxico es rápido, se inicia en unos pocos minutos tras la ingestión del cebo, y el animal va cayendo en un profundo abatimiento que se continúa con una sintomatología típica de los inhibidores anticolinesterásicos","Se presenta como unas bolitas azules, de consistencia muy dura y olor a pescado, lo que justifica que sea el veneno ilegal más usado en toda España y en gran parte de Europa","Ha sido prohibida su venta, comercialización y tenencia"],a:2,d:true,
n:"El aldicarb se comercializaba como <b>gránulos negros</b> (así lo corrige a mano la recopilación), no azules. ✓ Es un metil-carbamato de la misma familia que el carbofurano y el metomilo (apuntes, p. 20). ✓ El cuadro es fulminante y anticolinesterásico. ✓ Están prohibidas su venta, comercialización y tenencia. ⚠ El color y el olor del gránulo <b>no están en tus apuntes</b>: apóyate en que las otras tres opciones son ciertas."},
/* recopilación, reco p. 36 (n.º 25) */
{t:1,q:"Sobre los rodenticidas anticoagulantes, señale la INCORRECTA",o:["Producen descenso en los factores de coagulación","En algunas ocasiones pueden disminuir la acción conglomerante de las plaquetas","Procesos de hipovitaminosis K disminuyen la toxicidad de estos compuestos","En España se han producido intoxicaciones secundarias en especies de aves rapaces"],a:2,
n:"Si ya existe <b>hipovitaminosis K</b>, la toxicidad <b>aumenta</b>, porque estos rodenticidas actúan precisamente inhibiendo los factores de coagulación vitamina K dependientes (protrombina, VII, IX y X) (apuntes, p. 24); la recopilación lo corrige con una flecha hacia arriba. ✓ Descenso de los factores de coagulación y aumento de la permeabilidad capilar. ✓ Pueden disminuir la acción agregante de las plaquetas por protrombina biológicamente inactiva (p. 24). ✓ Las rapaces sufren intoxicaciones secundarias al comer roedores envenenados."},
/* recopilación, reco p. 36 (n.º 26) */
{t:1,q:"Sobre los derivados cumarínicos, señale el enunciado correcto",o:["La warfarina, el brodifacoum y la bromadiolona son derivados cumarínicos de primera generación","El brodifacoum es eliminado a través de la orina sin sufrir procesos de biotransformación","Los rodenticidas de primera generación son más tóxicos que los de segunda generación, ya que una sola dosis puede ser letal","Todas son correctas"],a:1,d:true,
n:"Por descarte: ✗ solo la <b>warfarina</b> es de primera generación; el brodifacoum y la bromadiolona son de <b>segunda</b> (apuntes, p. 23). ✗ Son los de <b>segunda generación</b> los más tóxicos y los que pueden matar con una sola dosis (DL50 del brodifacoum 0,26 mg/kg frente a 58 mg/kg de la warfarina, p. 24). ⚠ La eliminación concreta del brodifacoum <b>no está en tus apuntes</b> (solo que se buscan hidroxicumarinas o sus metabolitos en orina y heces, p. 25): se da por buena la opción marcada por eliminación de las demás."},
/* recopilación, reco p. 36 (n.º 27) */
{t:1,q:"Sobre la cinética de los rodenticidas anticoagulantes, señale la correcta",o:["La vía predominante de exposición a estas sustancias es la ingestión","La degradación metabólica de la warfarina y de las indandionas es principalmente la hidroxilación por enzimas microsomales hepáticas","La vida media de eliminación de la warfarina varía entre 24 y 36 horas","Todas correctas"],a:3,
n:"La exposición se produce por <b>ingestión</b> de cebos o de roedores envenenados (apuntes, p. 23), la biotransformación es hepática microsomal (en el análisis se buscan hidroxicumarinas y sus metabolitos, p. 25) y la warfarina tiene una vida media corta, de en torno a un día, muy inferior a la de los anticoagulantes de segunda generación, que persisten semanas. Por tanto, <b>todas son correctas</b>."},
/* recopilación, reco p. 36 (n.º 28) */
{t:1,q:"Señale la correcta",o:["La aflatoxina B1 provoca un cuadro convulsivo con contracciones tetánicas entre 12 y 24 horas tras su ingestión","La estricnina es un antagonista competitivo y reversible de los receptores de glicina","El animal intoxicado por clorpirifos sufre un cuadro de debilidad y decaimiento en las primeras 24 horas","Todas son ciertas"],a:1,
n:"La <b>estricnina</b> actúa en el SNC como antagonista <b>competitivo y reversible</b> de los receptores de glicina, lo que desinhibe la motoneurona y provoca la estimulación incontrolada de la musculatura esquelética (apuntes, p. 26). ✗ La aflatoxina B1 es hepatotóxica y carcinógena, no convulsivante. ✗ El clorpirifos (organofosforado) produce en las primeras horas un cuadro colinérgico de excitación; la debilidad y el decaimiento son propios del <b>síndrome intermedio</b>, que aparece a las 24-96 h, sobre todo en gatos (apuntes, p. 19)."},
/* recopilación, reco p. 36 (n.º 31) */
{t:1,q:"El incremento del tiempo de coagulación y de hemorragia, junto con otras discrasias sanguíneas, pueden atribuirse a una intoxicación provocada por",o:["Clorofacinona","Estricnina","Vacor","Brometalina"],a:0,
n:"La <b>clorofacinona</b> es un rodenticida anticoagulante derivado de la indandiona (primera generación): inhibe los factores vitamina K dependientes y alarga el tiempo de protrombina y de hemorragia (apuntes, p. 23-25). ✗ La estricnina produce convulsiones tetánicas, no hemorragias (p. 26). ✗ El vacor es un derivado de la urea (PNU). ✗ La brometalina es un rodenticida no anticoagulante que desacopla la fosforilación oxidativa en el SNC (p. 23 y 32)."},
/* recopilación, reco p. 36 (n.º 32) */
{t:1,q:"Indique cuál de los siguientes parámetros sanguíneos utilizaría para valorar rutinariamente una intoxicación por cumarínicos",o:["Fibrinógeno","Niveles de factores activados","Tiempo de protrombina","Todos los anteriores"],a:2,m:3,d:true,
n:"El parámetro de uso <b>rutinario</b> es el <b>tiempo de protrombina</b>: tus apuntes lo citan como la prueba laboratorial del diagnóstico y como el análisis indirecto de los rodenticidas anticoagulantes (apuntes, p. 25). ⚠ En la recopilación el enunciado aparece subrayado en «tiempo de protrombina», pero hay un círculo a mano sobre «todos los anteriores»; y en la misma recopilación (p. 33, n.º 96), preguntando de forma general por los ensayos para evaluar una intoxicación por cumarinas, la respuesta que se da es «todas son válidas», porque también se alteran el fibrinógeno y los factores activados. Fíjate en la palabra <b>rutinariamente</b>."},
/* recopilación, reco p. 36 (n.º 33) */
{t:1,q:"Señale la respuesta correcta sobre la estricnina",o:["Está prohibida, por lo que ya no se utiliza para envenenar","Provoca un cuadro convulsivo muy violento con contracciones tetánicas que comienza entre las 12 y 24 horas tras la ingestión del cebo","Es un antagonista competitivo y reversible de los receptores de glicina","El animal intoxicado sufre un cuadro de debilidad y decaimiento"],a:2,
n:"Mecanismo de la estricnina: antagonista <b>competitivo y reversible</b> de los receptores de glicina del SNC (apuntes, p. 26). ✗ Está prohibida desde la Orden de 4 de febrero de 1994, pero sigue siendo una de las sustancias más implicadas en el envenenamiento de perros (p. 25). ✗ El periodo de latencia es de <b>10 minutos a 2 horas</b>, no de 12-24 h (p. 26). ✗ El cuadro es de hiperexcitabilidad, rigidez, contracciones tetánicas violentas, postura en caballete y risa sardónica, nunca de debilidad y decaimiento: por eso, si el enunciado pide la INCORRECTA (como lo reescribe a mano la recopilación), la respuesta sería esa última opción."},
/* recopilación, reco p. 36 (n.º 34) */
{t:1,q:"Entre los síntomas de la intoxicación aguda por la ingestión de metaldehído se encuentran",o:["Hipotermia, fatiga, bradicardia, vómito, convulsiones","Convulsiones, hiperestesia, hemorragias perianales, bradipnea","Hipertermia, fatiga, taquicardia, hipersalivación, hiperestesia, convulsiones","Hemorragias generalizadas, vómitos, miosis, hipersalivación"],a:2,
n:"El metaldehído produce <b>hipertermia severa</b>, taquicardia y taquipnea, hipersalivación espesa y espumosa, hiperestesia con sacudidas ante estímulos táctiles, visuales y auditivos, ataxia y convulsiones tónico-clónicas (apuntes, p. 33-34). ✗ Hipotermia y bradicardia son justo lo contrario. ✗ Las hemorragias son el cuadro de los rodenticidas anticoagulantes. ✗ Miosis con hipersalivación orienta a organofosforados o carbamatos (p. 19)."},
/* recopilación, reco p. 37 (n.º 35) */
{t:1,q:"Acerca de la estricnina, señale la INCORRECTA",o:["Es un alcaloide de la semilla de la planta Strychnos nux vomica y otras especies del mismo género","Se absorbe con relativa dificultad a través de las superficies mucosas y es eliminada con facilidad por la orina y la saliva","La mayor parte es oxidada en el hígado","Es una intoxicación que cursa de manera aguda"],a:1,
n:"La estricnina se absorbe <b>rápidamente</b> por el tracto gastrointestinal y las membranas mucosas, se distribuye ampliamente por todos los tejidos y se metaboliza sobre todo por <b>enzimas microsomales hepáticas</b>, con un modelo de eliminación lineal (apuntes, p. 26). ✓ Es el alcaloide de las semillas de Strychnos nux-vomica (p. 25). ✓ La intoxicación es agudísima: latencia de 10 min a 2 h y muerte entre 10 min y 24 h (p. 26)."},
/* recopilación, reco p. 37 (n.º 36) */
{t:1,q:"De los compuestos siguientes, uno de ellos puede presentar en sus formulaciones técnicas una elevada concentración de dioxinas cloradas. ¿Cuál?",o:["Paratión","Paraquat","p-nitrofenol","2,4-diclorofenoxiacético (2,4-D)"],a:3,d:true,
n:"Los herbicidas <b>clorofenoxiderivados</b> (2,4-D y sobre todo 2,4,5-T) arrastran <b>dioxinas cloradas</b> —en especial la 2,3,7,8-TCDD— como impureza de su síntesis: es el caso del agente naranja y del accidente de Seveso. ⚠ Tus apuntes recogen los clorofenoxiderivados (2,4-D, 2,4,5-T, MCPA, dalapon) en la p. 36-37, pero <b>no mencionan las dioxinas como impureza</b>: se mantiene la respuesta de la recopilación. ✗ El paratión es un organofosforado, el paraquat un herbicida bipiridílico y el p-nitrofenol un metabolito del paratión."},
/* recopilación, reco p. 37 (n.º 37) */
{t:1,q:"En relación con la toxicidad pulmonar del paraquat (herbicidas bipiridilos), señale la correcta",o:["La toxicidad alveolar del paraquat está relacionada con la interferencia en el transporte de electrones en la cadena respiratoria de la mitocondria","No es un tóxico pulmonar ya que es volátil","El paraquat es muy poco tóxico, su toxicidad está relacionada con la presencia de impurezas","Tiende a distribuirse en los tejidos más vascularizados, como los pulmones, generando radicales libres y peroxidación lipídica"],a:3,
n:"El paraquat se acumula <b>selectivamente en el pulmón</b>, que además es deficitario en superóxido dismutasa; al ser un magnífico <b>aceptor de electrones</b> se reduce con facilidad y genera <b>radicales libres</b> que producen peroxidación lipídica, edema, hemorragias y después fibrosis pulmonar (apuntes, p. 40-41). ✗ No interfiere en el transporte de electrones mitocondrial: lo que hace es captar electrones y formar radicales (así lo corrige a mano la recopilación). ✗ No es volátil y es un tóxico pulmonar de primer orden. ✗ Es muy tóxico por sí mismo (DL50 oral de 60 mg/kg en perro) y además cáustico, no por sus impurezas."},
/* recopilación, reco p. 27 (n.º 24) */
{t:1,q:"Sobre la eliminación de sustancias tóxicas, señale la correcta",o:["La eliminación por la bilis depende del gradiente de concentración de la sustancia a ambos lados de la membrana","Los líquidos volátiles se eliminan fácilmente por la orina por difusión simple","La eliminación por heces es más importante que la eliminación por orina","Los insecticidas organoclorados se eliminan fácilmente por leche"],a:3,
n:"Los organoclorados son <b>muy liposolubles e insolubles en agua</b>, así que pasan a la grasa y se excretan con la <b>leche</b> (y los huevos) sin biotransformar: por eso tus apuntes citan como fuente de intoxicación la «carne con residuos de insecticidas o leche con residuos» (apuntes, p. 11-12) y describen una eliminación bifásica, un 50 % en 3-4 días y el resto muy lentamente desde hígado y grasa (p. 13). ✗ La excreción biliar es un <b>transporte activo</b>, con circulación enterohepática (p. 47), no una simple difusión a favor de gradiente. ✗ Los líquidos volátiles se eliminan por vía <b>pulmonar</b>, con el aire espirado (como el acetaldehído procedente del metaldehído, p. 33). ✗ En general la vía más importante es la <b>orina</b>; por heces se excreta sobre todo lo no absorbido y lo eliminado por bilis (p. 47)."},
/* recopilación, reco p. 28 (n.º 41) */
{t:1,q:"Sobre las directivas y regulaciones europeas en las que se incluyen las evaluaciones de riesgos de las sustancias químicas, señale la correcta",o:["Los medicamentos veterinarios y la medicina humana se regulan por directivas específicas","Los aditivos en piensos se regulan por la directiva de sustancias químicas nuevas","Los cosméticos se regulan por la regulación de sustancias químicas ya existentes","La directiva de sustancias químicas nuevas es de aplicación para biocidas y plaguicidas"],a:0,
n:"Cada grupo de sustancias tiene su <b>normativa específica</b>, y es el caso de los medicamentos de uso humano y veterinario (igual que los aditivos de piensos y los cosméticos, que tampoco se regulan por las directivas generales de sustancias químicas nuevas o ya existentes). ✗ Los <b>plaguicidas y biocidas</b> tienen legislación propia: Reglamento (CE) 1107/2009 de comercialización de productos fitosanitarios, Reglamento (UE) 528/2012 de biocidas, Directiva 2009/128/CE de uso sostenible de los plaguicidas y Reglamento (CE) 1185/2009 de estadísticas (apuntes, p. 4), con los requisitos de datos de los Reglamentos (UE) 283/2013 (sustancias activas) y 284/2013 (productos fitosanitarios) (apuntes, p. 6-10). Recuerda también el límite máximo de residuos por defecto de 0,01 mg/kg (p. 5)."},
/* recopilación, reco p. 29 (n.º 51) */
{t:1,q:"Sobre características organolépticas de algunas sustancias químicas, señale la correcta",o:["Las almendras amargas son indicativas de alta cantidad de cianuro","El paraquat suele ser detectado por su suave olor a regaliz","Los rodenticidas no anticoagulantes suelen comercializarse en bloques, pellets o granos de cereales con colores como el rojo, verde o azul","El color a formaldehído en un estómago puede inducir a sospechar de la ingestión del herbicida metaldehído"],a:0,d:true,
n:"El <b>olor a almendras amargas</b> es el signo clásico del cianuro y de los glucósidos cianogénicos (el ácido cianhídrico se libera al romperse el glucósido). ✗ El <b>metaldehído</b> sí deja <b>olor estomacal a formaldehído</b> como hallazgo post mortem (apuntes, p. 34), pero es un <b>molusquicida</b>, no un herbicida: ahí está el error de esa opción. ✗ El olor del paraquat no figura en tus apuntes (sus formulaciones llevan colorante y un aditivo maloliente y emético, no un suave olor a regaliz). ⚠ Cuidado con la opción de los rodenticidas: tus apuntes describen cebos de <b>granos rojos o verdes con estricnina</b> (p. 25), cebos de granos o pasta con fosfuro de cinc (p. 28), cebos con base de cereales de escilirósido (p. 30) y pellets o gránulos de metaldehído (p. 33), todos no anticoagulantes, así que esa afirmación también es defendible; si piden una sola correcta, la segura es la del cianuro, que es la marcada."},
/* recopilación, reco p. 39 (n.º 69) */
{t:1,q:"Respecto a la estricnina. Señale la CORRECTA:",o:["En España se prohibió en el 2015","Es un antagonista competitivo y reversible de los receptores de la acetilcolina","La risa sardónica es un signo característico de intoxicación por ella","Todas son correctas"],a:2,
n:"✓ C: los labios dirigidos hacia atrás («risa sardónica») son un signo clásico, junto con las contracciones tetánicas y la postura «en caballete» (apuntes, p. 26).<br>✗ A: la prohibición en España es de la <b>Orden de 4 de febrero de 1994</b>, no de 2015 (apuntes, p. 25).<br>✗ B: es antagonista competitivo y reversible de los receptores de la <b>glicina</b>, no de la acetilcolina (apuntes, p. 26)."},
/* recopilación, reco p. 39 (n.º 70) */
{t:1,q:"Señale el enunciado incorrecto:",o:["La atropina se usa en el tratamiento de intoxicaciones por clorpirifós","Los insecticidas OF y carbamatos… (opción incompleta en la recopilación)","Los piretroides son componentes de aerosoles domésticos","La deltametrina se biomagnifica a lo largo de la cadena trófica"],a:3,
n:"✗ Los piretroides tienen <b>alta degradación y baja toxicidad animal</b>, no se bioacumulan ni biomagnifican (apuntes, p. 21). Los que bioacumulan y biomagnifican son los <b>organoclorados</b> (apuntes, p. 12).<br>✓ A: el clorpirifós es un organofosforado y su tratamiento genérico es el sulfato de atropina (apuntes, p. 16 y 20).<br>✓ C: los piretroides se formulan en aerosoles, polvos, champús, collares… (apuntes, p. 21).<br>La opción B aparece truncada en la recopilación."},
/* recopilación, reco p. 42 (n.º 98) */
{t:1,q:"Selecciona la respuesta incorrecta:",o:["Los plaguicidas organofosforados se acumulan principalmente en el tejido adiposo","La metabolización de algunos plaguicidas produce metabolitos o productos intermedios de naturaleza más tóxica que el compuesto original, como el DDE o el paratión","Los carbamatos son plaguicidas anticolinesterásicos","Actualmente, los organofosforados son la familia de plaguicidas más usados a nivel global, habiendo desplazado a los plaguicidas organoclorados"],a:1,d:true,
n:"✗ B: la bioactivación existe, pero los ejemplos están cambiados —la propia recopilación lo corrige con «→ DDT y paraoxón»—: el metabolito más tóxico es el <b>paraoxón</b> (procedente del paratión, por desulfuración oxidativa, apuntes p. 16), y el DDE es el metabolito persistente del DDT, no más tóxico que él (apuntes, p. 12).<br>✓ C: los carbamatos inhiben la AChE de forma reversible y sin envejecimiento de la enzima (apuntes, p. 21).<br>⚠ Ojo, hay más opciones discutibles: los que se acumulan en la grasa son los <b>organoclorados</b> (muy liposolubles, se acumulan en hígado y grasa, apuntes p. 12-13), no los OF (opción A); y según tus apuntes los insecticidas más usados eran los carbamatos (77 % frente al 6 % de OF, apuntes p. 11) y los piretroides suponen más del 30 % de los insecticidas del mundo (apuntes, p. 21), lo que deja coja la opción D."},
/* recopilación, reco p. 42 (n.º 99) */
{t:1,q:"Sobre insecticidas neonicotinoides. Señale el enunciado incorrecto:",o:["Imidacloprid es el más usado","Pueden producir pérdidas de orientación en abejas","La mayoría tienen una DL50 en abejas mucho más alta que la del DDT y aparecieron en los años 50","Imidacloprid es el más usado y pueden producir pérdidas de orientación en abejas"],a:2,
n:"En el original los dos enunciados falsos iban separados («DL50 en abejas mucho más alta que el DDT» —el subrayado de la recopilación— y «aparecieron en los años 50»); se han unido en una sola opción para que solo haya una respuesta correcta.<br>✗ DL50: la del imidacloprid en <i>Apis mellifera</i> es de <b>60 ng/abeja a las 48 h</b> (40 ng/abeja a las 72-96 h), es decir, bajísima = altísima toxicidad para las abejas, mucho mayor que la del DDT (apuntes, p. 22).<br>✗ Fecha: los neonicotinoides se introdujeron en la agricultura <b>en los años 90</b> (apuntes, p. 22).<br>✓ Imidacloprid, tiametoxam y clotianidina son los principales; actúan de modo selectivo e irreversible sobre los receptores nicotínicos de la ACh del insecto (apuntes, p. 22)."},
/* recopilación, reco p. 44 (n.º 26) */
{t:1,q:"Sobre plaguicidas, señale la incorrecta:",o:["Según el último informe de MAPAMA los fungicidas y bactericidas son los más utilizados","Han sido responsables de muchas intoxicaciones colectivas","Algunos de los residuos de los plaguicidas son metabolitos primarios altamente tóxicos","Los límites máximos de residuos son equiparables a los límites tóxicos"],a:3,
n:"✗ D: el <b>LMR no es un límite toxicológico</b>. Es el límite máximo de residuos que puede contener un alimento (por defecto 0,01 mg/kg) y se fija a partir de las buenas prácticas agrícolas y de la evaluación de la EFSA para proteger la salud, muy por debajo de las dosis tóxicas (apuntes, p. 5).<br>✓ A: los datos de MAPAMA no están en tus apuntes (los tuyos dan el reparto entre insecticidas: carbamatos 77 %, OF 6 %, OC 3 %, apuntes p. 11).<br>✓ C: la metabolización puede dar productos intermedios más tóxicos que el original (p. ej. paraoxón del paratión, apuntes p. 16)."},
/* recopilación, reco p. 44 (n.º 28) */
{t:1,q:"Respecto a la estricnina:",o:["Se usa como rodenticida y es un antagonista competitivo y reversible de los receptores de la glicina","Produce un descenso en los factores de coagulación (II, VII, IX y X), que necesitan la vitamina K para sintetizarse","Se usa como rodenticida y produce un descenso en los factores de coagulación (II, VII, IX y X), que necesitan la vitamina K para sintetizarse","Es un antagonista competitivo y reversible de los receptores de la glicina y produce un descenso en los factores de coagulación (II, VII, IX y X)"],a:0,
n:"En el original las opciones eran A) «se usa como rodenticida», B) «antagonista competitivo y reversible de los receptores de la glicina» (la marcada), C) «descenso de los factores de coagulación» y D) «A y C son correctas». Como <b>A y B son ciertas a la vez</b>, se han unido para que solo haya una respuesta correcta.<br>✓ La estricnina es un rodenticida y avicida (prohibido en España desde la Orden de 4 de febrero de 1994) y actúa como antagonista competitivo y reversible de los receptores de la <b>glicina</b> en el SNC, provocando estimulación incontrolada del músculo esquelético (apuntes, p. 25-26).<br>✗ El descenso de los factores de coagulación dependientes de la vitamina K (protrombina, VII, IX y X) es el mecanismo de los <b>rodenticidas anticoagulantes</b>, no de la estricnina (apuntes, p. 24)."},
/* examen del 3er parcial (15/5/25) */
{t:2,q:"El esquema de «plomo en aves» cuantifica la mortalidad que provoca el plumbismo. ¿Cuántas muertes al año se le atribuyen?",o:["Varios millones al año, incluidas especies en peligro o amenazadas","Varios centenares al año, casi siempre en especies cinegéticas","Unas mil al año, exclusivamente en aves acuáticas migradoras","Ninguna conocida, solo descensos poblacionales por infertilidad"],a:0,
n:"Cayó en el 3er parcial (15/5/25) — «pregunta sobre el plomo: cantidad de muertes anuales».<br>El esquema <b>PLOMO EN AVES</b> (p. 57) termina la rama del <b>plumbismo</b> (ingestión de Pb metálico → enfermedad clínica con secuelas o muerte) en el recuadro <b>VARIOS MILLONES DE MUERTES AL AÑO (incluidas especies en peligro o amenazadas)</b>. La otra rama, la de exposición crónica ambiental, es la que lleva a <b>descensos poblacionales</b> por alteraciones del comportamiento, la fertilidad y las infecciones."},
/* examen del 3er parcial (15/5/25) */
{t:2,q:"Halcón muy delgado con diarrea verdosa que le mancha las plumas pericloacales. Tras ingerir perdigones de plomo, ¿en cuánto tiempo aparecen la parálisis y las alteraciones de la locomoción?",o:["En unas 24 horas desde la ingestión de los perdigones","En unos 15 días desde la ingestión de los perdigones","En unos 50 días desde la ingestión de los perdigones","En unos 2 meses desde la ingestión de los perdigones"],a:0,
n:"Cayó en el 3er parcial (15/5/25) — en el caso del halcón preguntaba «hace cuántos días fue la intoxicación» (tres, quince, cincuenta días o dos meses).<br><b>Ojo</b>: los apuntes no dan ningún plazo en días, así que la pregunta se ha reformulado con el único dato temporal que sí aparece. En los <b>efectos del plumbismo</b> (p. 57) los síntomas nerviosos son: <b>parálisis y alteraciones de la locomoción (24 horas)</b>, postración, ausencia de reflejos, letargia y ataxia e incapacidad para el vuelo y la huida. Los síntomas digestivos (diarrea verdosa que mancha las plumas pericloacales y anorexia con pérdida de peso) indican un cuadro ya instaurado."},
/* examen del 3er parcial (15/5/25) */
{t:2,q:"Halcón caquéctico con diarrea verdosa en el que se sospecha una intoxicación por perdigones de plomo. ¿Cuál sería el primer paso diagnóstico?",o:["Una radiografía, para localizar los perdigones retenidos en la molleja","Una coprología, para descartar primero una parasitación intestinal","Un cultivo de heces, para confirmar el origen bacteriano del proceso","Una biopsia hepática, para medir el plomo acumulado en el hígado"],a:0,
n:"Cayó en el 3er parcial (15/5/25) — caso del halcón: «cuál sería el primer paso: coprología, radiografía u otras dos».<br>El plomo en aves produce <b>implantación del plomo en la molleja</b> (p. 58), de modo que los perdigones se ven como cuerpos radiopacos; además el tratamiento empieza por <b>eliminar la fuente de exposición, con eliminación quirúrgica si es necesario</b> (p. 56), lo que obliga a localizarlos antes. La diarrea verdosa que mancha las plumas pericloacales ya orienta al plumbismo, no a una parasitosis."},
/* examen del 3er parcial (15/5/25) */
{t:2,q:"En ese mismo halcón, con los perdigones todavía en la molleja y una debilidad extrema por intoxicación aguda por plomo, ¿cuál sería el tratamiento correcto para estabilizarlo?",o:["Edetato cálcico disódico (CaNa2 EDTA) y alimento proteico altamente digestible","Edetato disódico (NaEDTA) y alimento proteico de digestibilidad muy alta","Dimercaprol (BAL) en solitario y una dieta rica en calcio y en fósforo","Metalotioneínas inducidas con cinc en la dieta y fluidoterapia de soporte"],a:0,
n:"Cayó en el 3er parcial (15/5/25), y era pregunta repetida — caso del halcón.<br>En el <b>tratamiento del plomo</b> (p. 56) el quelante de elección es el <b>CaNa2 EDTA, muy utilizado</b>, y los apuntes avisan de <b>no usar NaEDTA</b>, porque puede unirse al calcio y provocar <b>hipocalcemia</b>. Se acompaña de tratamiento sintomático y fluidoterapia; el soporte nutricional proteico muy digestible es el que daba por buena la pregunta del examen. Inducir metalotioneínas con Zn, Se o Co es el tratamiento del <b>cadmio</b> (p. 59), no del plomo."},
/* examen del 3er parcial (15/5/25) */
{t:2,q:"Si en ese halcón intoxicado por plomo no dispusiésemos del quelante de primera elección (CaEDTA), ¿qué fármaco pondríamos en su lugar?",o:["D-penicilamina, porque también es un quelante útil frente al plomo","Acetilcisteína, porque aporta grupos tiol que atrapan el plomo","Bicarbonato de sodio, porque alcaliniza la orina y arrastra el plomo","Atropina, porque revierte los signos nerviosos de la intoxicación"],a:0,
n:"Cayó en el 3er parcial (15/5/25) — caso del halcón: «qué haríamos si no tuviésemos el cabaril» (se pone otro quelante).<br>Los quelantes que recogen los apuntes para el plomo (p. 56) son: <b>CaNa2 EDTA</b> (el más utilizado), la <b>combinación CaNa2 EDTA/BAL</b>, el <b>DMSA</b> (ácido dimercaptosuccínico o succímero, menos tóxico que el CaNa2 EDTA) y la <b>D-penicilamina</b>. Esta última es además la <b>tercera opción frente al plomo</b> según el tema de quelantes (p. 50). Ni la acetilcisteína, ni el bicarbonato, ni la atropina son quelantes."},
/* examen del 3er parcial (15/5/25) */
{t:2,q:"¿Qué es la «enfermedad del álcali»?",o:["Una intoxicación crónica por selenio que afecta sobre todo a pezuñas, cascos y pelo","Una intoxicación crónica por flúor que afecta sobre todo a dientes, huesos y articulaciones","Una intoxicación crónica por molibdeno con despigmentación del pelo alrededor de los ojos","Una intoxicación aguda por selenio con muerte por fallo respiratorio en horas o días"],a:0,
n:"Cayó en el 3er parcial (15/5/25): «Enfermedad del álcali – del selenio, que afecta a pezuñas y pelo».<br>Tus apuntes: el selenio <b>«Produce una enfermedad alcalina (crónica)»</b> (p. 66). En la tabla de intoxicación subaguda y crónica (p. 67), la <b>enfermedad del álcali («enfermedad de la cola cortada»)</b> se debe a <b>granos y pastos seleníferos</b> y da <b>cojera, pérdida de vitalidad, alargamiento de pezuñas y cascos y caída del pelo (melena y cola)</b>; en la vaca, el Se se acumula en pezuñas (5-8 ppm) y pelo (5-10 ppm).<br>Las otras opciones son la fluorosis crónica (p. 69-70), la molibdenosis (p. 65) y la intoxicación aguda por selenio (p. 67)."},
/* examen del 3er parcial (15/5/25) */
{t:2,q:"Sobre la relación cobre-molibdeno, señale la respuesta CORRECTA:",o:["En rumiantes, el Mo con sulfato frena el acúmulo hepático de Cu, y el exceso de Mo provoca carencia de Cu","En rumiantes, el Mo con sulfato favorece el acúmulo hepático de Cu, y la carencia de Mo protege frente al Cu","En no rumiantes, el Mo aislado frena el acúmulo de Cu, y el exceso de Mo aumenta las reservas hepáticas de Cu","El Mo y el Cu no interaccionan en rumiantes; solo el Fe y el Zn modifican la toxicidad del cobre en ellos"],a:0,
n:"Cayó en el 3er parcial (15/5/25): «Pregunta sobre la relación cobre-molibdeno».<br>Tus apuntes: en <b>rumiantes</b>, Mo y sulfato <b>controlan la acumulación de Cu en hígado</b>, facilitan su eliminación biliar y renal y forman un <b>complejo Cu/Mo de cociente molar 4/3</b> (p. 60). En <b>no rumiantes</b>, Mo y sulfato aislados NO afectan al Cu y solo combinados previenen su acúmulo; el Fe y el Zn protegen en monogástricos (p. 60).<br>La <b>carencia de Mo</b> es un factor que aumenta la toxicidad del Cu (p. 61) y, al revés, el exceso de Mo <b>obstaculiza el almacenamiento hepático de Cu (carencia)</b>: es la molibdenosis (p. 65)."},
/* examen del 3er parcial (15/5/25) */
{t:2,q:"Intoxicación crónica por cobre en un rebaño de ovejas. Sobre el cociente Cu/Mo y el tratamiento, señale la CORRECTA:",o:["Aparece con un cociente Cu/Mo > 6-10/1; se trata 3 semanas con 50-500 mg de molibdato amónico y 0,1-2 g de sulfato sódico","Aparece con un cociente Cu/Mo < 6/1; se trata 3 semanas con 50-500 mg de molibdato amónico y 0,1-2 g de sulfato sódico","Aparece con un cociente Cu/Mo > 6-10/1; se trata con 2 g/día de sulfato de cobre por vía oral hasta que cese la diarrea","Aparece con un cociente Cu/Mo > 6-10/1; se trata con sales de arsénico en la dieta y 4-5 g de naftaleno durante 5 días"],a:0,
n:"Cayó en el 3er parcial (15/5/25): «Tto. intoxicación por cobre en ovejas (creo que era un cociente 6:1)».<br>En tus apuntes no hay ningún cociente 6:1 dentro del tratamiento: el <b>6-10/1 es el cociente Cu/Mo de desequilibrio en el ovino</b> (recuadro de la p. 60, «Desequilibrio Cu/Mo → Ovino: 6-10/1»; p. 61, dosis crónica tóxica de los corderos «> 6-10/1»), así que lo más probable es que la opción buena incluyera ese cociente.<br>El tratamiento (p. 64) es <b>50-500 mg de molibdato amónico + 0,1-2 g de sulfato sódico durante 3 semanas</b> (facilita la eliminación del Cu y previene su acumulación), además de quelantes (BAL, EDTA, DMPS, penicilamina, TRIEN). No lo confundas con el <b>cociente molar 4/3</b> del complejo Cu/Mo (p. 60).<br>Los 2 g/día de sulfato de cobre son la prueba diagnóstica de la molibdenosis (p. 65) y el arsénico con naftaleno, el tratamiento del selenio (p. 68)."},
/* examen del 3er parcial (15/5/25) */
{t:2,q:"Sobre la eliminación del arsénico, señale la respuesta correcta",o:["Se elimina por todas las vías, sobre todo por orina, bilis y piel","Se elimina solo por bilis, y la orina no interviene en ninguna forma","Se elimina sobre todo por las heces y en menor medida por la leche","Se elimina únicamente por la piel y el pelo, nunca por la vía renal"],a:0,
n:"Cayó en el 3er parcial (15/5/25) como «sobre el arsénico: trivalente por orina».<br>Tus apuntes (p. 71) dicen: «La eliminación se produce por todas las vías, pero principalmente por <b>orina</b> (prevalente), <b>bilis</b> (trivalente) <b>y piel</b>».<br><b>Ojo con esa frase:</b> ese «prevalente» parece una errata de <b>pentavalente</b>, porque va en paralelo con «bilis (trivalente)». Leído así, el trivalente saldría sobre todo por bilis y el pentavalente por orina; en cualquier caso, la vía principal del arsénico en conjunto es la orina."},
/* examen del 3er parcial (15/5/25) */
{t:2,q:"Sobre la toxicidad de las distintas formas del arsénico, señale la correcta",o:["Los compuestos trivalentes son más tóxicos que los pentavalentes","Los compuestos pentavalentes son más tóxicos que los trivalentes","Los compuestos orgánicos son más tóxicos que todos los inorgánicos","Las dos formas inorgánicas tienen exactamente la misma toxicidad"],a:0,
n:"Cayó en el 3er parcial (15/5/25).<br>En los factores que afectan a la toxicidad del arsénico (p. 71): «Naturaleza del compuesto: <b>trivalentes más tóxicos</b>». Los trivalentes más comunes son el trióxido de As, el arsenito sódico y el tricloruro de As; los pentavalentes, el pentóxido de As, el ácido arsénico y los arsenatos de Pb y Ca.<br>Como dato de dosis: 1-25 mg/kg p.v. de arsenito sódico, y la del trióxido es 3-10 veces menor."},
/* recopilación, reco p. 4 (Metales n.º 1) */
{t:2,q:"Respecto a la toxicología del selenio, señale la respuesta correcta:",o:["El selenio se acumula principalmente en hígado y riñón.","Todas son correctas.","Una posible fuente de exposición son las plantas acumuladoras de Se.","Uno de sus mecanismos de acción es la sustitución de azufre por selenio en proteínas alterando su función, mecanismo por el cual el selenio afecta a pezuñas y pelo ante una intoxicación crónica."],a:1,
n:"✓ Todas son ciertas:<br>• Hígado y riñón son los órganos donde se detectan los niveles más altos y donde está la patología más relevante (atrofia y cirrosis hepática, nefritis) (apuntes, pp. 67-68).<br>• Las plantas indicadoras/acumuladoras (<i>Astragalus</i>, <i>Stanleya</i>, <i>Xylorriza</i>, <i>Oonopsis</i>…, y las facultativas <i>Aster</i>, <i>Atriplex</i>…) son fuente típica de intoxicación en terrenos seleníferos (apuntes, p. 66).<br>• Su mecanismo incluye la <b>sustitución de S por Se</b> en las proteínas; por eso la intoxicación crónica («enfermedad alcalina» o «de la cola cortada») afecta a pezuñas, cascos, melena y cola (apuntes, pp. 67-68)."},
/* recopilación, reco p. 4 (Metales n.º 2) */
{t:2,q:"Respecto al mecanismo de acción de los metales en general, señale la respuesta correcta:",o:["Pueden unirse a metalotioneínas y glutatión.","Pueden alterar la función celular mediante mimetismo de elementos esenciales.","Son capaces de generar estrés oxidativo.","Todas son correctas."],a:3,
n:"✓ Todas son ciertas:<br>• Los metales forman complejos uniéndose por el <b>grupo sulfhidrilo</b> a ligandos como las metalotioneínas o el glutatión (apuntes, p. 46; el Cd, el Pb y el Hg desplazan a los esenciales en las metalotioneínas).<br>• El mimetismo de elementos esenciales es clásico (el arseniato imita al fosfato, el talio al potasio, el plomo al calcio) (apuntes, pp. 47 y 76).<br>• Entre los efectos tóxicos de los metales, el primero que citan tus apuntes es la <b>inducción de estrés oxidativo</b>, con disfunción de proteínas, daño en el ADN y en la membrana celular (apuntes, p. 47)."},
/* recopilación, reco p. 4 (Metales n.º 3) */
{t:2,q:"Respecto a la sintomatología ante una intoxicación por metales, señale la respuesta INCORRECTA:",o:["Una diferencia entre la intoxicación crónica y aguda por cobre es que en la intoxicación crónica se observa un claro cuadro gastrointestinal.","Una intoxicación por cadmio produce daño renal y óseo.","La intoxicación por plomo presenta una sintomatología muy variada, produciendo efectos en el sistema nervioso, circulatorio y gastrointestinal entre otros.","Una intoxicación por mercurio orgánico (CH3Hg+) se caracteriza por un cuadro clínico neurológico."],a:0,
n:"✗ Es al revés: el <b>cuadro gastrointestinal es propio de la intoxicación AGUDA por cobre</b> (gastroenteritis por vía oral: dolor abdominal, salivación, diarrea líquida, vómito con moco de color azul intenso, shock) (apuntes, p. 62). La <b>crónica</b> cursa con debilidad, anorexia, hemoglobinuria, palidez de mucosas, ictericia y disnea por la crisis hemolítica (apuntes, p. 63).<br>✓ Cadmio: daño renal (necrosis tubular) y óseo (inhibe la formación de colágeno óseo, la absorción de Ca y P e interfiere en la vitamina D) (apuntes, pp. 58-59).<br>✓ Plomo: sintomatología muy variada e inespecífica (apuntes, p. 55).<br>✓ Metilmercurio: cuadro neurológico (apuntes, pp. 52-53)."},
/* recopilación, reco p. 4 (Metales n.º 4) */
{t:2,q:"Respecto al mecanismo de acción de los metales, señale la respuesta correcta:",o:["Los metales no esenciales no tienen capacidad de unirse al glutatión.","El ion arseniato tiene una estructura similar al fosfato y compiten en el transporte.","Los metales no esenciales no inducen la síntesis de metalotioneínas.","Los metales no alteran el sistema antioxidante celular."],a:1,
n:"✓ b) Es el ejemplo clásico de <b>mimetismo de elementos esenciales</b>: el arseniato (AsO4³⁻) se parece al fosfato (PO4³⁻) y compite con él en el transporte y en el metabolismo energético (en tus apuntes, el arsénico altera el metabolismo de grasas e hidratos de carbono y paraliza la respiración celular, p. 72).<br>✗ a y ✗ c: los metales no esenciales se unen al glutatión y a las metalotioneínas, y además las inducen: el cadmio, el plomo y el mercurio son los tres metales no esenciales capaces de desplazar a los esenciales en las metalotioneínas, y el arsénico es inductor de metalotioneínas in vivo (apuntes, pp. 46-47 y 72).<br>✗ d: inducen estrés oxidativo y alteran el sistema antioxidante (apuntes, p. 47)."},
/* recopilación, reco p. 4 (Metales n.º 5) */
{t:2,q:"Respecto a la toxicidad del zinc, señale la respuesta correcta:",o:["El Zn se distribuye transportado en plasma por la albúmina.","Todas son correctas.","Frecuentemente el animal se recupera al eliminar la fuente de exposición sin necesidad de tratamiento quelante.","La intoxicación aguda se caracteriza por irritación y corrosión gastrointestinal."],a:1,
n:"✓ Todas son ciertas:<br>• La sintomatología del zinc es de <b>irritación y corrosión</b>: dolor de boca, esófago, estómago e intestino, con vómitos y diarrea sanguinolentos (apuntes, p. 74).<br>• El zinc <b>no se acumula</b> y se elimina por heces, orina y leche, por lo que al retirar la fuente el animal suele recuperarse con tratamiento sintomático (impedir la absorción con carbonato sódico, ácido tánico o albúmina de huevo) (apuntes, pp. 74-75).<br>• El transporte plasmático unido a albúmina no aparece literal en tus apuntes, pero es correcto y la clave lo da por bueno."},
/* recopilación, reco p. 4 (Metales n.º 6) */
{t:2,q:"Respecto a la toxicidad del talio, señale la respuesta INCORRECTA:",o:["La intoxicación aguda se caracteriza por un cuadro renal.","Puede atravesar la barrera placentaria.","Se acumula principalmente en riñón.","Entre los mecanismos de acción del talio se encuentra su capacidad de interferir en la proliferación celular del folículo piloso."],a:0,
n:"✗ a) La intoxicación <b>aguda</b> por talio (1-4 días tras la ingesta) es sobre todo <b>digestiva y nerviosa</b>: cólicos, vómitos, diarrea a veces sanguinolenta, salivación, anorexia, depresión, parálisis motoras, alteraciones respiratorias, anoxia y muerte (úlceras linguales en el gato) (apuntes, p. 76). Las alteraciones cutáneas, nerviosas y renales aparecen en las formas subaguda y crónica.<br>✓ b) Atraviesa la barrera fetoplacentaria (apuntes, p. 75).<br>✓ c) Acumulación renal (apuntes, p. 75).<br>✓ d) Es <b>antimitótico</b>: de ahí la caída del pelo y las depilaciones (apuntes, pp. 75-76)."},
/* recopilación, reco p. 4-5 (Metales n.º 7) */
{t:2,q:"Respecto a la toxicología del flúor, señale la respuesta correcta:",o:["Entre los mecanismos de acción se encuentra su capacidad de reemplazar grupos hidroxilo de la hidroxiapatita formando fluorapatita y alterando la mineralización en hueso y dientes.","Una intoxicación crónica provoca principalmente alteraciones dentales y óseas.","Su principal vía de absorción es la gastrointestinal.","Todas son correctas."],a:3,
n:"✓ Todas son ciertas:<br>• El flúor se acumula en las partes duras del cuerpo (huesos y dientes), capta iones Ca, Mg y Fe y altera la mineralización: fluorosis dental y defectos de mineralización, alteración de la remodelación ósea, exostosis, esclerosis y osteoporosis (apuntes, p. 69).<br>• La intoxicación crónica es la típica (forrajes y aguas contaminadas): lesiones dentales (moteado marrón, desgaste irregular) y óseas (hiperostosis, cojeras) (apuntes, p. 70).<br>• La absorción es digestiva e inhalatoria, siendo la digestiva la vía principal en la contaminación crónica por alimentos y agua (apuntes, p. 69)."},
/* recopilación, reco p. 5 (Metales n.º 8) */
{t:2,q:"Respecto al tratamiento quelante ante una intoxicación por metales, señale la respuesta INCORRECTA:",o:["La intoxicación por mercurio orgánico se debe tratar con 2,3-dimercaptopropanol (anti-lewisita británica o BAL).","La intoxicación por plomo se puede tratar con CaNa2EDTA.","El tratamiento quelante será por lo general más efectivo cuando el metal está todavía en circulación.","La intoxicación por cadmio no se debe tratar con 2,3-dimercaptopropanol (anti-lewisita británica o BAL) ya que forma un complejo tóxico."],a:0,
n:"✗ a) El <b>BAL está contraindicado en el mercurio ORGÁNICO</b> (y en el cadmio): su indicación es el arsénico y el mercurio <b>inorgánico</b>, además del plomo y el oro (apuntes, p. 49). Para el Hg orgánico se usan DMPS o DMSA.<br>✓ b) El CaNa2EDTA es el quelante de elección en el plomo (forma PbNa2EDTA, hidrosoluble, que se elimina por orina) (apuntes, pp. 49 y 56).<br>✓ c) Cuanto más metal haya todavía en circulación (y menos fijado en los tejidos), más eficaz es la quelación.<br>✓ d) El BAL con el cadmio forma un complejo tóxico; en el cadmio se induce la síntesis de metalotioneínas con Zn, Se o Co (apuntes, p. 59)."},
/* recopilación, reco p. 5 (Metales n.º 9) */
{t:2,q:"Respecto a la acumulación de metales y elementos en el organismo, señale la respuesta correcta:",o:["El plomo y el flúor se pueden acumular en hueso.","El mercurio inorgánico (Hg2+) y el talio se acumulan principalmente en riñón.","El cobre se acumula principalmente en hígado.","Todas son correctas."],a:3,
n:"✓ Todas son ciertas:<br>• Plomo: acumulación en tejidos calcificados por su similitud con el calcio (apuntes, p. 47); flúor: huesos y dientes (p. 69).<br>• Mercurio inorgánico: acumulación renal mediada por su unión a metalotioneínas (p. 47); talio: acumulación en riñón (p. 75).<br>• Cobre: acumulación hepática, con metabolización hepática y eliminación biliar (p. 61)."},
/* recopilación, reco p. 5 (Metales n.º 10) */
{t:2,q:"Respecto al mercurio, marque la respuesta INCORRECTA:",o:["Existen unas recomendaciones de consumo de pescado por presencia de mercurio para mujeres embarazadas o en lactancia y niños.","El metilmercurio (CH3Hg+) provoca principalmente efectos gastrointestinales.","El metilmercurio (CH3Hg+) se acumula en encéfalo, riñón e hígado.","El mercurio inorgánico (Hg2+) se acumula principalmente en riñón."],a:1,
n:"✗ b) El metilmercurio es un <b>neurotóxico</b>: altera el neurodesarrollo (placenta y leche; casos de Minamata) y en adultos produce alteraciones neurológicas (parestesias, pérdida de memoria visual, menor destreza motora) y enfermedad cardiovascular (apuntes, pp. 52-53). El cuadro digestivo (y renal) corresponde al mercurio <b>inorgánico</b>.<br>✓ a) Existen recomendaciones de consumo de pescado (PTWI 1,6 µg/kg p.c.) para embarazadas, lactantes y niños: pez espada, tiburón, aguja y lucio (apuntes, p. 53).<br>✓ c) y ✓ d) Acumulación del metilmercurio en encéfalo, riñón e hígado y del Hg2+ en riñón (apuntes, pp. 47 y 53)."},
/* recopilación, reco p. 5 (Metales n.º 11) */
{t:2,q:"Respecto a la toxicología del cadmio, señale la respuesta INCORRECTA:",o:["El cadmio presenta baja afinidad por las metalotioneínas.","Uno de sus mecanismos de acción es su capacidad de producir estrés oxidativo.","La relación de la concentración de Cd en hígado y riñón nos ayuda a interpretar el tipo de exposición.","El cadmio está clasificado como carcinógeno humano por la Agencia Internacional para la Investigación del Cáncer (IARC)."],a:0,
n:"✗ a) El cadmio tiene <b>gran afinidad</b> por las metalotioneínas: su acumulación renal está mediada precisamente por esa unión, que explica su larguísima permanencia intracelular (vida media de unos 30 años), y el tratamiento consiste en inducir la síntesis de metalotioneínas con Zn, Se o Co (apuntes, pp. 47, 58 y 59). Junto con el plomo y el mercurio es uno de los tres metales no esenciales que desplazan a los esenciales en las metalotioneínas.<br>✓ c) Hígado alto con riñón bajo indica exposición reciente; riñón alto, exposición crónica (apuntes, p. 59: medición de Cd en vísceras).<br>✓ d) La clasificación del cadmio en el grupo 1 de la IARC no está en tus apuntes, pero es correcta."},
/* recopilación, reco p. 5 (Metales n.º 12) */
{t:2,q:"Respecto a la acumulación de metales y elementos en el organismo, señale la respuesta INCORRECTA:",o:["El flúor se acumula principalmente en huesos y dientes.","El cadmio se acumula principalmente en hígado y hueso.","El arsénico se acumula principalmente en hígado y riñón.","El mercurio elemental (Hg0) se acumula principalmente en tejido cerebral y riñón."],a:1,
n:"✗ b) El cadmio se acumula en <b>hígado y riñón</b> (50-75 % de la carga corporal; acumulación renal progresiva hasta los 50-60 años) (apuntes, p. 58). El hueso es un <b>órgano diana del daño</b> (desmineralización, Itai-Itai), no el depósito principal.<br>✓ a) Flúor: partes duras del cuerpo, huesos y dientes (apuntes, p. 69).<br>✓ c) Arsénico: hígado y riñón (también uñas y pelo) (apuntes, p. 71).<br>✓ d) El vapor de mercurio elemental se absorbe por vía inhalatoria (hasta el 80 %), atraviesa la BHE y se deposita en encéfalo y riñón (apuntes, pp. 47 y 52)."},
/* recopilación, reco p. 5 (Metales n.º 13) */
{t:2,q:"Respecto a la toxicología del cobre y el molibdeno, señale la respuesta correcta:",o:["La intoxicación por cobre puede deberse a una dosis elevada de este metal o a un desequilibrio cobre/molibdeno en rumiantes.","Las opciones a y c son correctas.","Ciertas razas de perro pueden presentar una predisposición genética a acumular cobre en hígado de forma similar a la enfermedad de Wilson en humanos.","La acción tóxica del molibdeno comienza por su acumulación en hígado, generando fallo hepático, liberación de Mo a sangre con crisis hemolítica y finalmente fallo renal."],a:1,
n:"✓ a) La intoxicación por cobre puede ser primaria (dosis elevada) o secundaria, por desequilibrio Cu/Mo/sulfato en rumiantes: el molibdeno controla la acumulación de Cu en hígado y facilita su eliminación biliar y renal (apuntes, pp. 60-61).<br>✓ c) La acumulación hepática de cobre con base genética (tipo enfermedad de Wilson) existe en ciertas razas de perro; tus apuntes recogen la enfermedad de Wilson humana (depósitos de Cu en hígado, cerebro, riñón, ojo).<br>✗ d) Esa secuencia (acumulación hepática → fallo hepático → liberación a sangre → crisis hemolítica → fallo renal) es el mecanismo del <b>cobre</b>, no del molibdeno (apuntes, p. 62). El molibdeno actúa <b>obstaculizando el almacenamiento hepático de cobre</b> (carencia): diarrea, adelgazamiento, despigmentación del pelo alrededor de los ojos y trastornos de locomoción (apuntes, p. 65)."},
/* recopilación, reco p. 6 (Metales n.º 14) */
{t:2,q:"Señale la respuesta correcta respecto a la toxicología de metales:",o:["La forma en la que se encuentre el metal (inorgánica u orgánica) puede afectar a su toxicidad.","Itai-Itai fue un caso de intoxicación masiva por cadmio que ocurrió en Japón en los años 40.","El plomo puede atravesar la barrera hematoencefálica, placentaria y hematomamaria.","Todas son correctas."],a:3,
n:"✓ Todas son ciertas:<br>• La forma química condiciona la toxicidad: <b>organometálicos > formas iónicas > forma elemental o metálica</b> (apuntes, p. 46).<br>• Itai-Itai: intoxicación masiva por cadmio en Japón (no aparece como tal en tus apuntes, pero sí el daño renal y óseo del Cd; el caso japonés del mercurio es Minamata, p. 52).<br>• El plomo atraviesa la BHE, la fetoplacentaria y la hematomamaria (apuntes, p. 54)."},
/* recopilación, reco p. 6 (Metales n.º 15) */
{t:2,q:"Señale la respuesta INCORRECTA respecto a la toxicología del arsénico:",o:["El arsénico se acumula principalmente en hígado y riñón.","La intoxicación aguda por arsénico produce síntomas a nivel óseo principalmente.","La intoxicación crónica produce síntomas iniciales inespecíficos de difícil diagnóstico.","El arsénico es capaz de inducir estrés oxidativo."],a:1,
n:"✗ b) La intoxicación aguda por arsénico es <b>digestiva y nerviosa</b>: dolor abdominal agudo, diarrea líquida, vómitos, atonía ruminal, marcha vacilante, debilidad extrema, temblores, salivación y shock (apuntes, p. 72). El hueso no es su diana (ahí piensa en flúor o cadmio).<br>✓ a) Acumulación en hígado y riñón, además de uñas y pelo (apuntes, p. 71).<br>✓ c) La crónica es muy inespecífica: agotamiento general, pelo áspero, mucosas rojizas (apuntes, p. 72).<br>✓ d) Altera proteínas y enzimas con grupos sulfhidrilo y afecta a tejidos ricos en sistemas oxidativos (apuntes, p. 72)."},
/* recopilación, reco p. 6 (Metales n.º 16) */
{t:2,q:"Respecto a los efectos ante una intoxicación por metales, señale la respuesta INCORRECTA:",o:["Tanto el mercurio elemental (Hg0) como el orgánico (CH3Hg+) pueden afectar al sistema nervioso.","La exposición a plomo puede afectar a la síntesis del grupo hemo.","Las intoxicaciones por cadmio y flúor pueden producir alteraciones óseas.","La intoxicación crónica por arsénico es muy específica y afecta principalmente al riñón."],a:3,
n:"✗ d) La intoxicación crónica por arsénico es justo lo contrario: <b>muy inespecífica</b> (agotamiento, pelo áspero, mucosas rojizas) y de difícil diagnóstico, con predominio digestivo y nervioso (apuntes, p. 72).<br>✓ a) El vapor de Hg0 atraviesa la BHE (temblores, déficit de memoria, irritabilidad) y el metilmercurio es neurotóxico (apuntes, pp. 47 y 52-53).<br>✓ b) El plomo interfiere en la síntesis del grupo hemo (ALAD como biomarcador) (apuntes, pp. 55-56).<br>✓ c) Cadmio: inhibe la formación de colágeno óseo y la absorción de Ca y P (apuntes, p. 59); flúor: fluorosis ósea (apuntes, pp. 69-70)."},
/* recopilación, reco p. 6 (Metales n.º 17) */
{t:2,q:"Señale la respuesta correcta respecto a la toxicología del plomo:",o:["Al observar una sintomatología compatible con intoxicación por Pb en un ave acuática viva, para confirmar el diagnóstico se llevará a cabo un análisis de Pb en sangre que puede complementarse con el análisis de la enzima ALAD y una radiografía.","El plomo se acumula principalmente en encéfalo y riñón.","La sintomatología ante una intoxicación por plomo es muy específica y se caracteriza por daño renal.","Todas son correctas."],a:0,
n:"✓ a) En el ave viva: plomo en sangre entera, <b>ALAD</b> como biomarcador (su descenso aparece ya con 5-15 µg/dl en pollos) y radiografía, porque los perdigones quedan implantados en la molleja (apuntes, pp. 56 y 58).<br>✗ b) El plomo se acumula en los <b>tejidos calcificados (hueso)</b>, por su similitud con el calcio (apuntes, p. 47).<br>✗ c) Su sintomatología es muy <b>variada e inespecífica</b>: nerviosa, digestiva (diarrea verdosa), hemática (anemia microcítica hipocrómica), renal, inmunitaria, cardiovascular y endocrina (apuntes, pp. 55-58)."},
/* recopilación, reco p. 6 (Metales n.º 18) */
{t:2,q:"Señale la respuesta correcta respecto a la toxicología de metales:",o:["La edad y el estado fisiológico del individuo pueden afectar a la toxicidad de los metales.","Todas son correctas.","Un quelante unido a un metal nunca puede formar complejos tóxicos.","El plomo es capaz de biomagnificarse en la cadena trófica."],a:0,
n:"✓ a) Entre los factores que determinan la toxicidad de los metales están la dosis, la forma química, el pH, la presencia de otros iones, la <b>edad</b> (fetos, lactantes y ancianos más sensibles), el <b>estado fisiológico</b> y las alteraciones previas de los órganos diana (apuntes, p. 46).<br>✗ c) Sí pueden: el BAL con el cadmio (y con el mercurio orgánico) forma un <b>complejo tóxico</b>, por eso está contraindicado (apuntes, pp. 49 y 59).<br>✗ d) El plomo se bioacumula, pero el metal que biomagnifica a lo largo de la cadena trófica es el <b>metilmercurio</b> (apuntes, p. 53)."},
/* recopilación, reco p. 8 (n.º 11); repetida en p. 15 (n.º 2) */
{t:2,q:"Sobre los metales, señale el enunciado INCORRECTO:",o:["El cadmio se acumula principalmente en la corteza renal.","Dentro de los alimentos de origen animal, los riñones son los que más Cd presentan.","De las formas en que se puede presentar el mercurio, la que más importancia tiene es el mercurio inorgánico, que es el acumulado por los animales marinos y por tanto incorporado a las cadenas tróficas con facilidad.","Los peces y mariscos son las principales fuentes de exposición de metilmercurio para los mamíferos, incluidos los seres humanos."],a:2,
n:"✗ c) La forma más importante desde el punto de vista toxicológico es el mercurio <b>orgánico (metilmercurio)</b>: es el que se biomagnifica por la cadena trófica y el que se acumula en los organismos marinos (apuntes, p. 53). El inorgánico se absorbe mal por vía digestiva (2-4 %) y no atraviesa las barreras (p. 47).<br>✓ a) Acumulación renal (corteza) mediada por metalotioneínas (apuntes, pp. 47 y 58).<br>✓ b) Por eso el Reglamento 1881/2006 fija contenidos máximos de Cd en despojos, riñón y vísceras (apuntes, p. 51).<br>✓ d) Pescado y marisco son la fuente principal de metilmercurio (apuntes, p. 53)."},
/* recopilación, reco p. 8 (n.º 12) */
{t:2,q:"Señale la respuesta correcta:",o:["El plomo es inductor del metabolismo.","La biotransformación del cadmio se realiza en el hígado.","El Zn disminuye la absorción de cadmio.","Todas son correctas."],a:2,
n:"✓ c) La absorción digestiva del cadmio <b>aumenta</b> con dietas deficientes en calcio, hierro y proteínas y con la <b>disminución de zinc</b> (apuntes, p. 58); es decir, el zinc reduce su absorción. Además, el Zn es antagonizado por el Cd (p. 74).<br>✗ a) El plomo no induce el metabolismo: <b>interfiere</b> (síntesis del grupo hemo, liberación de neurotransmisores, metabolismo del hierro, cobre y calcio) (apuntes, p. 55).<br>✗ b) Los metales <b>no son susceptibles de metabolización</b> (apuntes, p. 47); lo que hace el cadmio en el hígado es acumularse."},
/* recopilación, reco p. 8 (n.º 13); variante con clave distinta en p. 13 (n.º 14) */
{t:2,q:"Sobre el cobre, señale la respuesta INCORRECTA:",o:["Ictericia y hemoglobinuria son procesos que se pueden presentar tras una intoxicación crónica por este metal.","Forma parte de ciertas enzimas con funciones oxidativas, como la tirosina y citocromo oxidasa.","En caso de intoxicación en ganado ovino se ha comprobado que el uso de molibdeno y sulfato sódico no es efectivo para el tratamiento de la intoxicación por cobre en ovino.","La ceruloplasmina es la principal proteína transportadora de cobre en sangre."],a:2,d:true,
n:"✗ c) <b>Sí es efectivo</b>: el tratamiento preventivo del cobre incluye 50-500 mg de molibdato amónico y 0,1-2 g de sulfato sódico durante 3 semanas, que facilitan la eliminación del cobre y previenen su acumulación (apuntes, p. 64; prevención con pastos y piensos molibdenizados, p. 65).<br>✓ a) La crisis hemolítica de la intoxicación crónica da hemoglobinuria (orina oscura) e ictericia (apuntes, pp. 62-63).<br>✓ d) El cobre se transporta unido a ceruloplasmina (y a albúmina) (apuntes, p. 61).<br>⚠ b) Ojo: en otro examen (p. 13, n.º 14) la clave marcó esta opción como la falsa, porque el cobre es cofactor de la <b>tirosinasa</b> (y de la citocromo oxidasa, SOD, amina oxidasa y uricasa; apuntes, p. 62), no de «la tirosina», que es un aminoácido. Fíjate bien en cómo está escrito.<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 39 (n.º 66).</span>"},
/* recopilación, reco p. 8 (n.º 14) */
{t:2,q:"Sobre el cobre, señale el enunciado correcto:",o:["El cloruro de cobre es la forma química de presentación de cobre más estudiada.","No es capaz de atravesar la barrera fetoplacentaria.","Es un cofactor esencial en enzimas como la ALAD.","La acumulación de cobre en el hígado puede resultar en la aparición de crisis hemolíticas."],a:3,m:1,
n:"⚠ La clave de clase marcó la <b>b</b>, pero tus apuntes dicen lo contrario: el cobre <b>atraviesa la BFP</b> (apuntes, p. 61), así que esa opción es falsa.<br>✓ d) El mecanismo de acción del cobre es: acumulación hepática del cobre excedentario → insuficiencia hepática con menor eliminación biliar → salida masiva de cobre a sangre → <b>crisis hemolítica</b> (paso de Cu²⁺ a Cu⁺, caída del glutatión, peróxidos, metahemoglobina) → fallo renal (apuntes, p. 62).<br>✗ a) La forma más estudiada y usada es el <b>sulfato de cobre</b> (apuntes, pp. 60-61).<br>✗ c) La ALAD es la enzima de la síntesis del hemo inhibida por el <b>plomo</b> (apuntes, p. 56); el cobre es cofactor de tirosinasa, citocromo oxidasa, SOD, amina oxidasa y uricasa (p. 62)."},
/* recopilación, reco p. 10 (n.º 11) */
{t:2,q:"Acción de los hepatocitos en el metabolismo del cobre; señale la correcta:",o:["En el hepatocito se acumula y se induce la síntesis de metalotioneína que secuestra el cobre.","En el hepatocito se induce la síntesis de ceruloplasmina encargada del transporte del cobre en la sangre.","El hepatocito se encarga de regular la secreción biliar del cobre.","Todas son ciertas."],a:3,
n:"✓ Tus apuntes (p. 62) enumeran exactamente las cinco funciones del cobre en el interior del hepatocito: cofactor esencial de enzimas, almacenamiento como reserva, <b>inducción de metalotioneínas</b> (secuestro), <b>inducción de ceruloplasmina</b> (transporte) y <b>eliminación biliar</b>. La eliminación del cobre es biliar (y en menor medida renal), regulada por el molibdeno y el sulfato (p. 61).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 44 (n.º 23).</span>"},
/* recopilación, reco p. 10 (n.º 12) */
{t:2,q:"Sobre el cadmio:",o:["Tiene gran afinidad por las metalotioneínas, lo que se asocia a una gran permanencia intracelular.","Concentraciones bajas en riñón y altas en hígado se asocian a exposiciones recientes.","Sobre su tratamiento quelante, no se puede usar BAL por formación de componentes tóxicos.","Todas son ciertas."],a:3,
n:"✓ Todas son ciertas:<br>• La unión a metalotioneínas explica su acumulación renal y su vida media de unos 30 años (apuntes, pp. 47 y 58).<br>• El reparto hígado/riñón sirve para interpretar la exposición: hígado alto con riñón bajo indica exposición reciente; el riñón se va cargando con la exposición crónica (apuntes, pp. 58-59).<br>• El BAL está contraindicado en el cadmio porque forma un complejo tóxico; se induce la síntesis de metalotioneínas con Zn, Se o Co (apuntes, pp. 49 y 59).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 44 (n.º 24).</span>"},
/* recopilación, reco p. 10 (n.º 13) */
{t:2,q:"Sobre la toxicología del mercurio, elija el enunciado INCORRECTO:",o:["No se considera un factor de riesgo, pero la biomagnificación del metilmercurio por la cadena trófica hace que se acumule en fauna silvestre y seres humanos.","El mercurio elemental y el metilmercurio atraviesan las BHE y BFP acumulándose en el feto.","El mercurio elemental se absorbe eficazmente por las vías inhalatoria y gastrointestinal.","El mercurio inorgánico presenta una absorción gastrointestinal variable y no atraviesa las BHE y BFP."],a:2,
n:"✗ c) La absorción digestiva de las formas <b>elementales o metálicas es prácticamente nula</b>; lo que sí es muy eficaz (hasta el 80 %) es la absorción del <b>vapor de mercurio por vía inhalatoria</b> (apuntes, p. 47). Por eso los vapores mercuriales son extremadamente tóxicos y el mercurio líquido ingerido apenas lo es.<br>✓ b) El Hg0 y el metilmercurio atraviesan BHE y BFP: el metilmercurio pasa a placenta y leche y altera el neurodesarrollo (apuntes, p. 53).<br>✓ d) El inorgánico se absorbe poco (2-4 %) y no atraviesa las barreras; se acumula en riñón (apuntes, p. 47).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 44 (n.º 25).</span>"},
/* recopilación, reco p. 11 (n.º 17) */
{t:2,q:"Señale la correcta sobre las interacciones entre metales:",o:["El cadmio disminuye la absorción de zinc y afecta a su metabolismo.","Un elevado contenido de zinc en la dieta produce un déficit de cobre y calcio porque compiten por la absorción.","El selenio protege de la toxicidad del cadmio y del mercurio.","Todas son correctas."],a:3,
n:"✓ Todas son ciertas:<br>• El zinc es <b>antagonizado o inhibido por el cadmio</b> (apuntes, p. 74); además el Cd interfiere en el metabolismo del hierro (anemia) (p. 59).<br>• En monogástricos, el hierro y el zinc protegen frente a niveles elevados de cobre, de modo que un exceso de Zn provoca carencia de Cu (apuntes, p. 60).<br>• El selenio protege de la acumulación de cadmio y de la hipertensión por Cd, y <b>reduce la toxicidad del metilmercurio</b> (apuntes, p. 67).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 44 (n.º 27).</span>"},
/* recopilación, reco p. 11 (n.º 20) */
{t:2,q:"Toxicidad del plomo; señale la correcta:",o:["Ante la sospecha de una intoxicación por Pb en un ave acuática viva le haremos un análisis de sangre entera, análisis de la enzima ALAD y radiografía de molleja y aparato intestinal.","En el plomo uno de los mecanismos más destacados era la interferencia con el potasio.","Se trataría con la combinación de D-penicilamina, que moviliza y quela el plomo de los huesos, y CaNa2, que quela el plomo de los órganos.","Todas son correctas."],a:0,
n:"✓ a) En el ave viva: plomo en sangre entera, ALAD (biomarcador de la inhibición de la síntesis del hemo) y radiografía, porque los perdigones se implantan en la molleja (apuntes, pp. 56 y 58).<br>✗ b) El plomo se comporta como el <b>calcio</b> (acumulación en tejidos calcificados) e interfiere en el metabolismo del hierro, el cobre y el zinc (apuntes, pp. 47 y 55). El que compite con el <b>potasio</b> es el talio (p. 76).<br>✗ c) La combinación correcta es <b>CaNa2EDTA + BAL</b>: el CaNa2EDTA quela y moviliza el plomo acumulado en el hueso (aumentando el Pb en sangre y órganos) y el BAL quela el plomo de los órganos (apuntes, p. 56). La D-penicilamina es una alternativa posterior.<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 44 (n.º 29).</span>"},
/* recopilación, reco p. 12 (n.º 11); repetida en p. 15 (n.º 1) */
{t:2,q:"Sobre el mercurio:",o:["Los vapores mercuriales son extremadamente tóxicos.","El metilmercurio es la forma más importante del Hg en términos de toxicidad.","El Hg se acumula en tejido cerebral, riñón y testículos y se elimina vía renal fundamentalmente.","Todas son ciertas."],a:3,
n:"✓ Todas son ciertas:<br>• El vapor de mercurio se absorbe por vía inhalatoria en proporciones próximas al 80 % (apuntes, p. 47): de ahí su toxicidad extrema.<br>• El metilmercurio es la forma toxicológicamente más relevante: se biomagnifica, atraviesa BHE y BFP y es neurotóxico (apuntes, pp. 52-53).<br>• Se acumula en encéfalo, riñón, hígado y testículos y se elimina fundamentalmente por orina (apuntes, p. 47; es la respuesta que diste tú en la pregunta corta de p. 7, con el riñón como principal órgano acumulador del Hg2+).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 32 (n.º 78).</span>"},
/* recopilación, reco p. 13 (n.º 12) */
{t:2,q:"Sobre metales, señale la respuesta INCORRECTA:",o:["El Zn disminuye la absorción de cadmio.","La biotransformación del cadmio se realiza en el hígado.","La toxicidad de los metales no se ve influenciada por la temperatura.","La forma metálica o elemental no suele ser la más tóxica."],a:1,
n:"✗ b) Los metales <b>no son susceptibles de metabolización</b> (apuntes, p. 47): en el hígado el cadmio se <b>acumula</b> (junto con el riñón contiene el 50-75 % de la carga corporal, p. 58), no se biotransforma.<br>✓ a) La deficiencia de zinc aumenta la absorción de cadmio (apuntes, p. 58).<br>✓ c) Entre los factores que modifican la toxicidad de los metales tus apuntes citan dosis, forma química, pH, otros iones, edad, estado fisiológico y lesiones previas de los órganos diana; la temperatura no (apuntes, p. 46).<br>✓ d) Orden de toxicidad: organometálicos > formas iónicas > forma elemental o metálica (apuntes, p. 46).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 39 (n.º 64).</span>"},
/* recopilación, reco p. 13 (n.º 13) */
{t:2,q:"Señale la INCORRECTA:",o:["El plomo es inductor de metalotioneínas.","El cadmio se absorbe más por vía respiratoria que por vía digestiva.","El mercurio se usa como fungicida, insecticida y bactericida.","La enfermedad de Wilson es una afección genética relacionada con depósitos de Cu en el hígado, cerebro, riñón, ojo, etc."],a:2,d:true,
n:"⚠ La clave marca la <b>c</b>, pero cuidado: tus apuntes sí recogen <b>fungicidas mercuriales</b>, minerales inorgánicos (cloruro mercúrico y mercurioso) y orgánicos (cloruro de fenilmercurio y de etilmercurio, acetato de fenilmercurio), usados en el tratamiento de semillas, con las aves y el cerdo como especies más sensibles (apuntes, pp. 43-44). Lo que no aparece por ningún lado es su uso como insecticida ni como bactericida, y por ahí falla el enunciado. En otro examen con esta misma frase (p. 15, n.º 3) la clave la dio por buena y marcó otra opción.<br>✓ a) El cadmio, el plomo y el mercurio son los tres metales no esenciales capaces de desplazar a los esenciales y unirse a las metalotioneínas (preguntas cortas de p. 7).<br>✓ b) La absorción del cadmio es principalmente respiratoria (apuntes, p. 58)."},
/* recopilación, reco p. 13 (n.º 15) */
{t:2,q:"Sobre los metales, señale el enunciado correcto:",o:["Todos los metales son introducidos en el medio ambiente debido a actividades antropogénicas.","Son los responsables del 90 % de las intoxicaciones agudas producidas en el ganado.","Una vez que ingresan en el organismo pueden ser responsables de estrés oxidativo y han estado presentes en importantes catástrofes.","Han estado presentes en importantes catástrofes, pero una vez en el organismo no alteran el sistema antioxidante celular."],a:2,
n:"En el examen original las dos frases verdaderas iban en opciones separadas (y las dos estaban marcadas); aquí se han unido para que solo haya una correcta.<br>✓ El primer efecto tóxico que citan tus apuntes es la <b>inducción de estrés oxidativo</b> (apuntes, p. 47), y los metales han protagonizado catástrofes como Minamata (mercurio) o Itai-Itai (cadmio) (p. 52).<br>✗ a) Hay <b>emisiones naturales</b> (incendios, volcanes) además de las antropogénicas (apuntes, p. 46); el selenio, por ejemplo, procede de terrenos seleníferos y plantas acumuladoras (p. 66).<br>✗ b) En el ganado las intoxicaciones por metales suelen ser crónicas (el cobre es el ejemplo típico)."},
/* recopilación, reco p. 15 (n.º 3) */
{t:2,q:"Señale la respuesta INCORRECTA:",o:["Las formas más tóxicas de arsénico son las formas orgánicas.","El arsénico se destruye en el medio ambiente.","El mercurio se usa como fungicida, insecticida y bactericida.","La enfermedad de Wilson es una afección genética relacionada con depósitos de Cu en el hígado, cerebro, riñón, ojo, etc."],a:0,d:true,
n:"✗ a) Las formas más tóxicas del arsénico son las <b>inorgánicas trivalentes</b> (trióxido de arsénico, arsenito sódico, tricloruro de arsénico): «trivalentes más tóxicos» (apuntes, p. 71).<br>⚠ b) Ojo, esta también es falsa: el arsénico es un <b>elemento</b> y no se destruye; en el medio se transforma (las formas inorgánicas se metilan en tierra y agua) (apuntes, p. 71). La clave solo marcó la a, pero en esta pregunta hay dos enunciados falsos.<br>✓ c) Tus apuntes recogen los fungicidas mercuriales (apuntes, pp. 43-44) — aunque en otro examen (p. 13, n.º 13) esta misma frase se marcó como la incorrecta.<br>✓ d) Enfermedad de Wilson: depósitos de cobre en hígado, cerebro, riñón y ojo.<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 31 (n.º 74, segunda numeración).</span>"},
/* recopilación, reco p. 15 (n.º 4) */
{t:2,q:"Sobre el cadmio, señale el enunciado CORRECTO:",o:["Su absorción se ve aumentada por dietas ricas en calcio.","El órgano de acumulación por excelencia es el pulmón.","Su biotransformación se produce en el hígado.","Es clasificado como cancerígeno (Grupo 1) por la IARC."],a:3,
n:"✓ d) El cadmio está clasificado como cancerígeno del grupo 1 por la IARC (no está en tus apuntes, pero es lo que da por bueno la clave; encaja con que el Cd induzca anomalías cromosómicas y tumores, apuntes p. 58).<br>✗ a) Al revés: la absorción digestiva aumenta con dietas <b>deficientes</b> en calcio, hierro y proteínas (apuntes, p. 58).<br>✗ b) El pulmón es la principal <b>vía de absorción</b> (absorción respiratoria), pero la acumulación es en <b>hígado y riñón</b> (apuntes, p. 58).<br>✗ c) Los metales no se metabolizan (apuntes, p. 47).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 32 (n.º 80).</span>"},
/* recopilación, reco p. 7 (preguntas cortas, Metales n.º 1) */
{t:2,q:"Cite el principal órgano acumulador del mercurio inorgánico (Hg2+):",o:["Riñón.","Encéfalo.","Hueso.","Pulmón."],a:0,
n:"✓ El mercurio inorgánico se acumula principalmente en el <b>riñón</b>, mediado por su unión a metalotioneínas (apuntes, p. 47). En tu examen añadiste también testículos e hígado, pero el principal es el riñón.<br>✗ El encéfalo es diana del mercurio elemental (vapor) y del metilmercurio.<br>✗ El hueso es el depósito del plomo y del flúor.<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Metales n.º 2 y n.º 4) */
{t:2,q:"Enumere las tres fases del mecanismo de acción tóxica del cobre:",o:["Acumulación hepática del cobre excedentario → fallo hepático con liberación masiva de cobre a la sangre → crisis hemolítica y, finalmente, fallo renal.","Acumulación renal → fallo renal → crisis hemolítica.","Unión a metalotioneínas → desmineralización ósea → fallo hepático.","Inhibición de la ALAD → anemia → encefalopatía.","Acumulación en hueso → movilización por el molibdeno → insuficiencia respiratoria."],a:0,
n:"✓ Apuntes, p. 62: 1) acumulación hepática del cobre excedentario (hasta el límite); 2) insuficiencia hepática con disminución de la eliminación biliar y salida masiva de cobre a la sangre; 3) <b>crisis hemolítica</b> (Cu²⁺→Cu⁺, caída del glutatión, peróxidos, metahemoglobina) con hemoglobinuria e ictericia y, finalmente, fallo renal por obstrucción tubular y necrosis.<br>✗ La inhibición de la ALAD es del plomo (p. 56); la desmineralización ósea, del cadmio y el flúor.<br><i>(En el examen era una pregunta corta de desarrollo, repetida dos veces en la misma hoja: «mecanismo de acción del cobre» y «las tres fases»; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Metales n.º 3 y n.º 9) */
{t:2,q:"¿Cuál es el cuadro clínico característico (principal sistema afectado) en la intoxicación aguda o crónica por mercurio orgánico (CH3Hg+)?",o:["Nervioso: altera el SNC, con estimulación en perro, gato y ternero, depresión en vacuno adulto, cerdo y ave, y síndrome gastrointestinal en ovino.","Renal: necrosis tubular con oliguria y proteinuria.","Hematológico: anemia hemolítica con ictericia y hemoglobinuria.","Óseo: desmineralización, exostosis y fracturas espontáneas."],a:0,
n:"✓ El metilmercurio es <b>neurotóxico</b>: atraviesa la BHE y la BFP, altera el neurodesarrollo (Minamata) y en adultos produce alteraciones neurológicas (parestesias, pérdida de memoria visual y de destreza motora) (apuntes, pp. 52-53).<br>✗ El cuadro digestivo y renal corresponde al mercurio <b>inorgánico</b>.<br>✗ La crisis hemolítica con ictericia es del cobre (p. 62).<br><i>(En el examen era una pregunta corta de desarrollo, repetida dos veces en la hoja; las opciones se han redactado a partir de tus apuntes y de tu propia respuesta.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Metales n.º 5) */
{t:2,q:"Cite el elemento que controla la absorción, la acumulación y la eliminación del cobre en rumiantes:",o:["Molibdeno.","Zinc.","Selenio.","Hierro."],a:0,
n:"✓ El <b>molibdeno</b> (junto con el sulfato): en rumiantes controlan la acumulación de Cu en hígado y facilitan su eliminación biliar y renal, formando el complejo Cu/Mo con un cociente molar 4/3 (apuntes, p. 60). Por eso el tratamiento y la prevención se hacen con molibdato amónico y sulfato sódico, y con pastos y piensos molibdenizados (apuntes, pp. 64-65).<br>✗ El hierro y el zinc protegen frente al exceso de cobre en monogástricos, pero no son el elemento regulador en rumiantes.<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Metales n.º 6) */
{t:2,q:"¿Cómo se unen los metales a las metalotioneínas?",o:["A través de los grupos tiol (-SH) de la cisteína.","Por puentes de hidrógeno con los grupos amino de la lisina.","Mediante enlaces iónicos con grupos fosfato.","Por unión covalente al anillo porfirínico."],a:0,
n:"✓ Los complejos metálicos se forman por la unión del metal a los <b>grupos sulfhidrilo (-SH)</b> del ligando (igual que ocurre con los quelantes tipo penicilamina o BAL) (apuntes, p. 46); en las metalotioneínas esos grupos tiol los aportan sus numerosas cisteínas.<br>✗ El anillo porfirínico es el del grupo hemo, cuya síntesis altera el plomo (p. 56).<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Metales n.º 7) */
{t:2,q:"Cite el quelante contraindicado para el tratamiento de la intoxicación por cadmio, selenio y mercurio orgánico:",o:["BAL (2,3-dimercaptopropanol o anti-lewisita británica).","CaNa2EDTA.","D-penicilamina.","DMSA (ácido dimercaptosuccínico)."],a:0,
n:"✓ El <b>BAL</b> está indicado frente al arsénico y el mercurio <b>inorgánico</b> (también plomo y oro), pero está <b>contraindicado en el cadmio y en el mercurio orgánico</b>, porque forma complejos tóxicos (apuntes, pp. 49 y 59).<br>✗ El CaNa2EDTA se usa en plomo y zinc; el DMSA y el DMPS sirven para plomo, mercurio (orgánico e inorgánico) y arsénico; la D-penicilamina es el quelante del cobre (apuntes, pp. 49-50).<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Metales n.º 8) */
{t:2,q:"El plomo afecta a la síntesis del grupo hemo. Cite la enzima principalmente afectada, que puede utilizarse como biomarcador:",o:["ALAD (ácido δ-aminolevulínico deshidratasa).","Fosfatasa alcalina.","Ceruloplasmina.","Acetilcolinesterasa."],a:0,
n:"✓ La <b>ALAD</b> es el biomarcador clásico de exposición a plomo: su descenso se detecta ya con niveles bajos (5-15 µg/dl en pollos, 20-50 en adultos) y se usa junto con el plomo en sangre entera y la radiografía en aves (apuntes, pp. 55-56 y 58).<br>✗ La acetilcolinesterasa es el marcador de organofosforados y carbamatos; la ceruloplasmina es la transportadora del cobre (p. 61).<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Metales n.º 10) */
{t:2,q:"Cite los dos principales sistemas afectados ante una intoxicación aguda por mercurio inorgánico (Hg2+):",o:["Digestivo y renal.","Nervioso y respiratorio.","Óseo y hematopoyético.","Cardiovascular y reproductor."],a:0,
n:"✓ El mercurio inorgánico se absorbe poco por vía digestiva (2-4 %) pero es corrosivo e irritante, y se acumula en el <b>riñón</b> unido a metalotioneínas: de ahí el cuadro <b>digestivo y renal</b> (apuntes, p. 47; en niños expuestos directamente, alteraciones nerviosas, digestivas y renales, p. 52).<br>✗ El cuadro puramente nervioso es el del mercurio elemental (vapor) y el del metilmercurio.<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Metales n.º 11) */
{t:2,q:"¿En qué tres tejidos se acumula principalmente el mercurio orgánico (CH3Hg+)?",o:["Encéfalo, riñón e hígado.","Hueso, dientes y pelo.","Pulmón, bazo y timo.","Músculo, tejido adiposo y piel."],a:0,
n:"✓ <b>Encéfalo, riñón e hígado</b>: el metilmercurio se absorbe muy bien (las formas orgánicas tienen absorción digestiva alta), atraviesa la BHE y la BFP y se deposita sobre todo en el tejido nervioso, además de riñón e hígado (apuntes, pp. 47 y 52-53).<br>✗ Hueso y dientes son el depósito del flúor y del plomo.<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 7 (preguntas cortas, Metales n.º 12) */
{t:2,q:"Cite los tres principales metales no esenciales capaces de desplazar a los esenciales y unirse a las metalotioneínas:",o:["Cadmio, plomo y mercurio.","Hierro, cobre y zinc.","Arsénico, selenio y flúor.","Talio, cromo y níquel."],a:0,
n:"✓ <b>Cadmio, plomo y mercurio</b>: son los tres metales no esenciales que desplazan a los esenciales y se unen a las metalotioneínas por los grupos tiol de la cisteína; esa unión explica la acumulación renal del Cd y del Hg (apuntes, pp. 46-47).<br>✗ Hierro, cobre y zinc son esenciales.<br>✗ El arsénico también induce metalotioneínas in vivo (apuntes, p. 72), pero el trío clásico es Cd, Pb y Hg.<br><i>(En el examen era una pregunta corta de desarrollo; las opciones se han redactado a partir de tus apuntes.)</i>"},
/* recopilación, reco p. 18 (n.º 11) */
{t:2,q:"Señale la respuesta correcta respecto a las interacciones entre los metales.",o:["El arsénico puede aumentar la excreción del selenio.","Dietas ricas en selenio provocan mayor sensibilidad a la intoxicación crónica por cobre.","El plomo interfiere en el metabolismo del calcio y del zinc.","Las respuestas A y C son correctas."],a:3,
n:"Examen de junio de 2017.<br>✓ <b>A</b>: el arsénico aumenta la excreción (biliar) del selenio; es la interacción clásica As-Se, aunque no aparece literal en tus apuntes.<br>✗ <b>B</b>: lo que agrava la intoxicación por cobre es la <b>carencia</b> de selenio y de molibdeno, no el exceso: «Carencia de selenio y molibdeno» figura entre los factores que aumentan la toxicidad del Cu (apuntes, p. 61). Quien aumenta la sensibilidad al cobre crónico es el desequilibrio Cu/Mo (apuntes, p. 60).<br>✓ <b>C</b>: el plomo interfiere en el metabolismo del Ca (se acumula en tejidos calcificados por su similitud con el calcio, apuntes, p. 47; «interfiere en el metabolismo del Ca y de la vit D», resumen de la recopilación, p. 56) y del zinc.<br>Como A y C son ciertas, la completa es <b>D</b>."},
/* recopilación, reco p. 18 (n.º 12) */
{t:2,q:"Respecto a la toxicología del cobre y el molibdeno, señale la correcta.",o:["La intoxicación por cobre puede deberse a una dosis elevada de este metal, a un desequilibrio de cobre/molibdeno en rumiantes o a la ingestión de plantas que producen desequilibrio mineral o que contienen alcaloides hepatotóxicos.","El ganado vacuno es más sensible que el ovino a la intoxicación por cobre, al contrario que para el molibdeno.","Ciertas razas de perros pueden presentar predisposición genética a acumular cobre en el hígado de forma similar a la enfermedad de Wilson en humanos.","La opción A y C son correctas."],a:3,
n:"Examen de junio de 2017. Ojo: la recopilación subraya en amarillo <b>las dos</b> opciones A y C y marca ambas con un ✓, así que la respuesta completa es <b>D</b>.<br>✓ <b>A</b>: entre las fuentes del cobre están los desequilibrios minerales Cu/Mo, el <i>Trifolium subterraneum</i> (crónica fitógena) y las plantas con alcaloides pirrolizidínicos —<i>Senecio</i>, <i>Heliotropum</i>, <i>Echium</i>— (crónica hepatógena) (apuntes, p. 60).<br>✗ <b>B</b>: es al revés; el <b>ovino</b> es mucho más sensible (dosis única letal 20-30 mg/kg en ovino frente a 200 mg/kg en vacuno) (apuntes, p. 61).<br>✓ <b>C</b>: la predisposición racial canina a acumular cobre hepático (tipo enfermedad de Wilson) no está en tus apuntes, pero es cierta y la clave la da por buena."},
/* recopilación, reco p. 18 (n.º 13) */
{t:2,q:"Respecto a la toxicidad del cadmio, señale la respuesta incorrecta.",o:["La relación de la concentración de Cd en hígado y riñón nos ayuda a interpretar el tipo de exposición: bajas concentraciones en el hígado y altas en riñón son indicativas de exposiciones recientes.","El cadmio está clasificado como carcinógeno humano por la Agencia Internacional para la Investigación del Cáncer (IARC) y es capaz de producir tumores en pulmón, testículos, próstata y riñón.","Uno de los mecanismos de acción es su capacidad de interferir con funciones del calcio y zinc.","El porcentaje de absorción del cadmio por vía inhalatoria es mayor, aunque es más frecuente la vía gastrointestinal."],a:0,
n:"Examen de junio de 2017.<br>✗ <b>A</b> (la incorrecta): está <b>al revés</b>. El cadmio se acumula de forma lenta y persistente en el riñón (vida media ~30 años, acumulación renal hasta los 50-60 años, unido a metalotioneínas), de modo que el predominio renal indica exposición <b>crónica</b>; el hígado alto con riñón bajo es lo propio de la exposición reciente (apuntes, pp. 47 y 58).<br>✓ <b>B</b>: el Cd figura entre los compuestos carcinogénicos e «induce anormalidades cromosómicas y tumores» (apuntes, p. 58).<br>✓ <b>C</b>: sustituye oligoelementos como cofactores, inhibe la absorción de Ca y P e interfiere con la vitamina D (apuntes, pp. 58-59).<br>✓ <b>D</b>: «su absorción es principalmente respiratoria, aunque también puede ser gastrointestinal» (apuntes, p. 58); la vía digestiva es la más frecuente pero absorbe poco (≈6 %) (apuntes, p. 47).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 41 (n.º 95).</span>"},
/* recopilación, reco p. 19 (n.º 14) */
{t:2,q:"Respecto a la toxicología del mercurio, marque la respuesta incorrecta.",o:["El selenio actúa como protector del efecto tóxico del Hg inorgánico debido a la formación de complejos Hg-selenio en proteínas.","El metilmercurio se acumula en encéfalo, riñón e hígado.","El órgano de elección para el análisis para el mercurio inorgánico es el riñón.","El metilmercurio no sufre recirculación hepática."],a:3,
n:"Examen de junio de 2017.<br>✗ <b>D</b> (la incorrecta): el mercurio <b>sí</b> cierra el círculo enterohepático; tus apuntes citan expresamente el Pb, el As y el Hg como metales en los que hay que vigilar la recirculación enterohepática (apuntes, p. 47).<br>✓ <b>A</b>: el selenio «reduce la toxicidad del metil-Hg» (apuntes, p. 67).<br>✓ <b>B</b> y <b>C</b>: el Hg se acumula en riñón mediado por metalotioneínas (apuntes, p. 47) y el metilmercurio es neurotóxico (efectos en el neurodesarrollo y alteraciones neurológicas, apuntes, p. 53).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 42 (n.º 96).</span>"},
/* recopilación, reco p. 19 (n.º 15) */
{t:2,q:"Señale la respuesta incorrecta con respecto a la toxicología del arsénico.",o:["La intoxicación aguda por arsénico produce síntomas a nivel hepático y óseo principalmente.","La intoxicación crónica produce síntomas inespecíficos de difícil diagnóstico.","La forma del arsénico afecta a su toxicidad, siendo las formas orgánicas menos tóxicas que las inorgánicas.","Las formas inorgánicas del arsénico sufren metilación dentro del organismo."],a:0,
n:"Examen de junio de 2017.<br>✗ <b>A</b> (la incorrecta): la intoxicación aguda es <b>gastrointestinal y nerviosa</b>: dolor abdominal agudo, diarrea líquida, vómito, salivación, atonía ruminal, marcha vacilante, temblores, postración y shock (apuntes, p. 72).<br>✓ <b>B</b>: la crónica da agotamiento general, pelo áspero y mucosas rojizas, cuadro inespecífico (apuntes, p. 72).<br>✓ <b>C</b>: los <b>trivalentes inorgánicos son los más tóxicos</b> (apuntes, p. 71).<br>✓ <b>D</b>: «las formas inorgánicas se metilan (dimetil As)» (apuntes, p. 71).<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 42 (n.º 97).</span>"},
/* recopilación, reco p. 24 (n.º 49) */
{t:2,q:"Una vez extraídos varios perdigones de la molleja de un ave acuática muerta, podemos diferenciar si son de plomo o de acero de la siguiente forma:",o:["Por el peso (el Pb pesa más y se puede deformar).","Por el color (el Pb no brilla, el acero sí).","Acercando un imán (se pega el acero).","Todas las respuestas son correctas."],a:3,
n:"Examen de junio de 2017. Las tres pistas son válidas y complementarias: el plomo es más denso y maleable (se deforma con la uña), tiene aspecto mate frente al brillo del acero y no es ferromagnético, así que solo el perdigón de acero se pega al imán. Es una diferenciación de prácticas: no viene desarrollada en tus apuntes, que para el plomo en aves solo recogen el diagnóstico por radiografía de los perdigones y el análisis de sangre, hígado, riñón y hueso (apuntes, p. 56; resumen de la recopilación, p. 56)."},
/* recopilación, reco p. 24 (n.º 50) */
{t:2,q:"De las siguientes afirmaciones sobre el plomo, señale la respuesta correcta.",o:["Las intoxicaciones por plomo solo afectan a las aves acuáticas.","Un perdigón de plomo puede permanecer durante varios meses en la molleja de un ave.","En los humedales se puede utilizar munición plomada.","En egagrópilas de aves rapaces se han encontrado perdigones de plomo."],a:3,
n:"Examen de junio de 2017.<br>✓ <b>D</b>: las rapaces ingieren los perdigones con sus presas y los expulsan en las egagrópilas; por eso el tratamiento del plomo incluye la eliminación de la fuente «lavado gástrico (intestinal/egagrópilas)» (resumen de la recopilación, p. 56).<br>✗ <b>A</b>: las especies afectadas son ovino, bovino y equino, aves silvestres (acuáticas) y perros; las acuáticas son las más llamativas, pero no las únicas (apuntes, p. 54).<br>✗ <b>B</b>: el perdigón de plomo se erosiona y se absorbe deprisa en la molleja (el que aguanta meses es el de acero).<br>✗ <b>C</b>: la munición plomada está prohibida en humedales.<br><span class=\"muted\">La recopilación repite esta pregunta, con las mismas opciones, en: reco p. 43 (n.º 12).</span>"},
/* recopilación, reco p. 53 (prácticas, supuestos 1, n.º 1) */
{t:2,q:"Supuesto de un ave con perdigones de plomo que llega con diarrea, vómitos y deshidratación. Ante la posible intoxicación, y teniendo en cuenta la sintomatología, la primera medida es estabilizar al paciente. Respecto a esta actuación, señale la respuesta correcta:",o:["Dejarlo tranquilo en un ambiente controlado.","Aplicar inmediatamente medidas de descontaminación.","Administrar sueroterapia y dejar en ambiente controlado.","Administrar alimento altamente digestible y dejar en ambiente controlado."],a:2,
n:"Supuesto práctico de la recopilación.<br>✓ <b>C</b>: razonamiento de la propia recopilación: «si el animal tiene diarrea, está vomitando y deshidratado lo más importante es administrar sueroterapia o fluidoterapia para estabilizarlo, y dejarlo en un ambiente controlado». La estabilización va <b>antes</b> que la descontaminación y que cualquier quelante.<br>Después, en el tratamiento del plomo: eliminar la exposición (lavado gástrico o extracción quirúrgica de los perdigones), tratamiento sintomático, barbitúricos, fluidoterapia y quelantes CaNa2 EDTA (±BAL), DMSA o D-penicilamina (apuntes, p. 56)."},
/* recopilación, reco p. 30 (n.º 62) */
{t:2,q:"Sobre la acumulación selectiva de tóxicos, señale la INCORRECTA",o:["Los organoclorados se acumulan en tejido adiposo y nervioso","El arsénico se acumula en uñas y pelo","El mercurio se acumula en riñón","El cadmio se acumula en huesos"],a:3,
n:"El <b>cadmio se acumula sobre todo en el riñón</b> (corteza renal), unido a metalotioneínas, con una vida media de unos 30 años (apuntes, p. 47 y 58). ✓ Organoclorados: muy liposolubles, se acumulan en grasa y tejido nervioso (apuntes, p. 12-13). ✓ Arsénico: hígado y riñón, y también uñas y pelo (apuntes, p. 71). ✓ Mercurio: acumulación renal mediada por metalotioneínas (apuntes, p. 47). ✗ El Cd sí afecta al hueso (inhibe la formación de colágeno óseo y el metabolismo de la vitamina D), pero su órgano de acumulación es el riñón."},
/* recopilación, reco p. 30 (n.º 66; repetida en p. 27 n.º 28) */
{t:2,q:"Con relación a los mecanismos de inhibición enzimática asociados a compuestos tóxicos, señale la INCORRECTA",o:["El ácido cianhídrico inhibe la citocromo oxidasa alterando así la respiración celular","El clorfenvinfos inhibe la glicina alterando la transmisión sináptica colinérgica","El plomo inhibe la hemosintetasa alterando la síntesis hemática","El arsénico inhibe la piruvato deshidrogenasa alterando el catabolismo oxidativo"],a:1,
n:"El clorfenvinfos es un <b>organofosforado</b>: inhibe la <b>acetilcolinesterasa</b>, no la glicina (apuntes, p. 16 y 18). Los receptores de glicina son la diana de la <b>estricnina</b> (apuntes, p. 26). ✓ El cianuro bloquea la citocromo oxidasa. ✓ El plomo interfiere en la síntesis del grupo hemo (ALAD/hemosintetasa), de ahí la anemia microcítica (apuntes, p. 55-56). ✓ El arsénico se une a grupos sulfhidrilo y paraliza la respiración celular y el catabolismo oxidativo (apuntes, p. 72).<br>Esta pregunta aparece dos veces en la recopilación (p. 27 n.º 28 y p. 30 n.º 66) con la misma opción marcada."},
/* recopilación, reco p. 31 (n.º 76) */
{t:2,q:"Relaciona las siguientes catástrofes con los tóxicos asociados: señale la relación correcta",o:["Seveso → dioxinas; Minamata → mercurio; Chernóbil → radiación; Aznalcóllar → metales (todas correctas)","Seveso → mercurio; Minamata → dioxinas; Chernóbil → radiación; Aznalcóllar → metales","Seveso → dioxinas; Minamata → cadmio; Chernóbil → radiación; Aznalcóllar → metales","Seveso → dioxinas; Minamata → mercurio; Chernóbil → metales; Aznalcóllar → radiación"],a:0,
n:"En la recopilación es una pregunta de relacionar y <b>las cuatro parejas son correctas</b>, así que se han agrupado en una sola opción (las demás se han reescrito con algún error). Seveso (Italia, 1976) → dioxinas; <b>Minamata</b> (Kumamoto, Japón) → mercurio (apuntes, p. 52); Chernóbil → radiaciones ionizantes; Aznalcóllar → vertido minero de metales. ✗ El <b>cadmio</b> corresponde a la enfermedad <b>itai-itai</b> (así lo anota a mano la recopilación), no a Minamata."},
/* recopilación, reco p. 31 (n.º 77) */
{t:2,q:"¿Cuáles de los siguientes compuestos son capaces de alterar la reproducción?",o:["Plomo, DES y cobre","Plomo, DES y aluminio","DES, zearalenona y DDT","DES, zearalenona y arsénico"],a:2,
n:"El <b>DES</b> (dietilestilbestrol) y la <b>zearalenona</b> (micotoxina estrogénica de Fusarium) son estrógenos, y el <b>DDT</b> es el disruptor endocrino clásico (altera la reproducción y adelgaza la cáscara del huevo en aves). ✗ El cobre, el aluminio y el arsénico no son los tóxicos reproductivos característicos: el plomo sí es embriotóxico (apuntes, p. 55) y el cadmio baja la motilidad espermática (apuntes, p. 59), pero las opciones que los incluyen añaden siempre un compuesto que no lo es."},
/* recopilación, reco p. 31 (n.º 78) */
{t:2,q:"Sobre los metales, señale la INCORRECTA",o:["El cadmio se acumula principalmente en la corteza renal","Dentro de los alimentos de origen animal, los riñones son los que más Cd presentan","De las formas en que se puede presentar el mercurio, la que más importancia tiene es el mercurio inorgánico, que es acumulado por los animales marinos y por tanto se incorpora a las cadenas tróficas con facilidad","Los peces y los mariscos son las principales fuentes de Hg"],a:2,
n:"La forma de mercurio con mayor trascendencia en la cadena trófica es la <b>orgánica (metilmercurio)</b>, que es la que se acumula en los organismos marinos y se biomagnifica; el inorgánico se absorbe mal por vía digestiva (solo un 2-4 %) (apuntes, p. 47 y 53). La recopilación lo corrige a mano con «orgánico». ✓ El cadmio se acumula en la corteza renal, por eso el riñón es el alimento de origen animal con más Cd (apuntes, p. 47, 51 y 58). ✓ El pescado y los productos de la pesca son la principal fuente de Hg (apuntes, p. 51 y 53)."},
/* recopilación, reco p. 31 (n.º 75) */
{t:2,q:"Sobre el mercurio, señale la correcta",o:["El mercurio es capaz de formar radicales mercaptídicos e inhibir sistemas enzimáticos con grupos –SH, y el BAL es el quelante específico de la intoxicación por mercurio inorgánico","El metilmercurio es la forma de presentación del mercurio menos tóxica, aunque tiene gran trascendencia desde la perspectiva ambiental por su capacidad acumulativa en todos los seres vivos","Solo el mercurio elemental es capaz de inducir la síntesis de metalotioneínas que se acumularán en el riñón","El mercurio forma radicales mercaptídicos, pero el BAL está contraindicado en la intoxicación por mercurio inorgánico"],a:0,m:1,d:true,
n:"El mercurio se une a los grupos sulfhidrilo (–SH) formando mercáptidos e inhibiendo múltiples sistemas enzimáticos; el <b>BAL o dimercaprol</b> (que aporta dos grupos –SH) es el quelante indicado en la intoxicación por <b>arsénico y mercurio inorgánico</b>, y está contraindicado en la de cadmio y mercurio orgánico (apuntes, p. 49). En la recopilación estas dos afirmaciones aparecían como opciones distintas y ambas son ciertas (el enunciado escribe «GAL» por BAL), así que se han unido en una sola. ✗ El <b>metilmercurio es la forma MÁS tóxica</b>, no la menos (apuntes, p. 53 y 75: solo el metilmercurio supera en toxicidad al talio): aunque la recopilación rodea esa opción, no puede ser la respuesta. ✗ También el Hg inorgánico induce metalotioneínas renales (apuntes, p. 47)."},
/* recopilación, reco p. 31-32 (n.º 76) */
{t:2,q:"Sobre el mercurio, señale la correcta",o:["De las formas en que se presenta el mercurio, la que más importancia tiene es la inorgánica, que se acumula en los animales marinos y por tanto se incorpora a la cadena trófica con facilidad","Dentro de las cadenas tróficas, el mercurio sufre procesos de bioconcentración, principalmente en los animales terrestres y en carnes de animales de abasto, lo que hay que tener muy en cuenta como fuente de contaminación accidental en humana","Los peces y mariscos son las principales fuentes de exposición de metilmercurio para los mamíferos, incluidos los seres humanos","Los efectos del Hg en mamíferos son muy diferentes a los que se observan en las aves: cáncer, problemas de adaptación, infecciones víricas, comportamiento agresivo"],a:2,
n:"El <b>metilmercurio del pescado y los productos de la pesca</b> es la principal vía de exposición de mamíferos y personas: por eso la ingesta semanal tolerable se fijó en 1,6 µg/kg p.c. y se avisa a gestantes, lactantes y niños sobre pez espada, tiburón, aguja, lucio y atún (apuntes, p. 51 y 53). ✗ La forma importante en la cadena trófica es la <b>orgánica</b>, no la inorgánica. ✗ La bioconcentración y biomagnificación del Hg ocurren sobre todo en la cadena trófica <b>acuática</b>. ✗ En mamíferos los efectos son neurológicos (parestesias, déficit de memoria, temblor, sordera, ceguera) y cardiovasculares (apuntes, p. 52-53)."},
/* recopilación, reco p. 32 (n.º 77) */
{t:2,q:"Sobre el mercurio elemental, señale la correcta",o:["El mercurio elemental atraviesa fácilmente la BHE y se absorbe bien por vía inhalatoria","El mercurio elemental se absorbe bien por vía inhalatoria, pero no atraviesa la BHE","El mercurio elemental se transporta por proteínas plasmáticas","No tiene uso terapéutico"],a:0,
n:"El vapor de mercurio elemental se absorbe por vía <b>inhalatoria</b> en proporciones muy elevadas (próximas al 80 %) y, por ser liposoluble y no ionizado, <b>atraviesa con facilidad la barrera hematoencefálica</b> (y la fetoplacentaria) antes de oxidarse a Hg²⁺ (apuntes, p. 47). En la recopilación las dos primeras afirmaciones aparecen marcadas como ciertas, así que se han unido en una sola opción. ✗ El Hg elemental viaja disuelto en sangre y eritrocitos; son las formas inorgánicas oxidadas las que se unen a proteínas plasmáticas. ✗ El mercurio ha tenido usos sanitarios (amalgamas dentales, antisépticos), apuntes, p. 52."},
/* recopilación, reco p. 32 (n.º 79) */
{t:2,q:"Sobre el cadmio, señale la correcta",o:["Es capaz de desacoplar la fosforilación oxidativa y de inhibir la síntesis de ADN, ARN y proteínas","Además de acumularse a nivel renal y dañar la estructura de este órgano, también inhibe la hidroxilación de la vitamina D y con ello su activación","Se ha asociado a alteraciones de la fertilidad por disminución de la motilidad espermática","Todas correctas"],a:3,
n:"Las tres afirmaciones están en tus apuntes (p. 58-59): el Cd <b>desacopla la fosforilación oxidativa</b> e inhibe la síntesis de ADN, ARN y proteínas (además de inducir anomalías cromosómicas y tumores); se acumula en el riñón, produce necrosis celular y disfunción renal e <b>inhibe la hidroxilación de la vitamina D</b>, que no se activa; y en el aparato reproductor inhibe la actividad enzimática disminuyendo la motilidad espermática."},
/* recopilación, reco p. 32 (n.º 81) */
{t:2,q:"Sobre la intoxicación crónica por cadmio, señale la correcta",o:["El cadmio se elimina rápidamente por orina","El cadmio tiene una vida media corta en el organismo","Se ha demostrado su relación con el cáncer de próstata","Provoca un síndrome gastrointestinal que es responsable de buena parte de los síntomas que produce"],a:2,d:true,
n:"Por descarte: ✗ la eliminación urinaria del Cd es <b>muy lenta</b> y su vida media ronda los <b>30 años</b> (apuntes, p. 58); ✗ la gastroenteritis por precipitación de proteínas corresponde a la intoxicación <b>aguda</b>, mientras que el cuadro crónico es renal y óseo (apuntes, p. 58-59; la recopilación tacha esa opción). ⚠ La relación concreta del cadmio con el <b>cáncer de próstata no está en tus apuntes</b> (sí que es carcinógeno y que induce tumores): se mantiene la respuesta que da la recopilación."},
/* recopilación, reco p. 32 (n.º 82) */
{t:2,q:"Las intoxicaciones por Cu se presentan de forma brusca, aunque como consecuencia de una exposición continuada. Síntoma característico:",o:["Anemia hemolítica","Gastroenteritis","Despigmentación de pelo","Todas las anteriores"],a:0,
n:"El cobre se acumula en el hígado y, cuando se libera de golpe, desencadena una <b>crisis hemolítica</b>: paso de Cu²⁺ a Cu⁺, caída del glutatión y aumento de peróxidos, metahemoglobina, hemoglobinuria, ictericia, fallo renal y shock (apuntes, p. 62-63). ✗ La gastroenteritis con vómitos y heces azuladas es propia de la intoxicación <b>aguda</b> por vía oral (p. 62). ✗ La despigmentación del pelo alrededor de los ojos es del exceso de <b>molibdeno</b>, que provoca carencia secundaria de Cu (p. 65)."},
/* recopilación, reco p. 32 (n.º 83) */
{t:2,q:"Una intoxicación por plomo producirá, tras su exposición crónica:",o:["Disminución de la actividad AChE","Osteoporosis y osteomalacia por alteraciones en el metabolismo de la Vit. D","Anemia hemolítica","Inhibición de la enzima hemosintetasa"],a:3,
n:"El plomo <b>interfiere en la síntesis del grupo hemo</b> (desciende la ALA-deshidratasa y se inhibe la hemosintetasa), de ahí la anemia con eritrocitos microcíticos e hipocrómicos (apuntes, p. 55-56 y 58). ✗ La inhibición de la AChE es de organofosforados y carbamatos. ✗ Las lesiones óseas por alteración de la vitamina D son del <b>cadmio</b>; en el hueso el plomo produce osteocondensación (apuntes, p. 55). ✗ La anemia del plomo no es hemolítica (esa es la del cobre)."},
/* recopilación, reco p. 32 (n.º 84) */
{t:2,q:"¿Qué biomarcador utilizarías para justificar una intoxicación por plomo?",o:["Método de Gutzeit","Método de Lee – Jones","Determinación de la δ-ALAD en sangre","Determinación cromatográfica en orina"],a:2,
n:"La <b>δ-ALA deshidratasa (ALAD) sanguínea</b> es el indicador precoz del plumbismo: desciende ya con 20-50 µg/dl en adultos y con 5-15 µg/dl en pollos, antes de que aparezcan signos clínicos (apuntes, p. 56). ✗ El método de Gutzeit es la prueba clásica del <b>arsénico</b> y el de Lee-Jones, la del <b>cianuro</b>. ✗ La cromatografía no es el método de elección para un metal (se usan AAS, ASV, voltamperometría)."},
/* recopilación, reco p. 32 (n.º 85) */
{t:2,q:"Señale la afirmación INCORRECTA sobre el plumbismo en aves",o:["Las aves acuáticas se intoxican de forma directa, tras la ingestión de los perdigones dispersos por el medio, mientras que las aves rapaces presentan intoxicación secundaria, tras la ingesta de las presas afectadas con el plumbismo","Se ha estimado que la vida media de un perdigón de plomo abandonado es de entre 30 y 300 años","Medicamentos anabolizantes, como el EDTA, al entrar en contacto con el plomo sustituyen el ión potasio por el de plomo, formando así un complejo tóxico que el ave elimina fácilmente","Los animales afectados por plumbismo tienen una deficiencia inmunológica que les hace mucho más sensibles a adquirir infecciones bacterianas oportunistas y parásitos"],a:2,
n:"El <b>EDTA no es un anabolizante, sino un quelante</b>: se usa como CaNa₂-EDTA y es el átomo de <b>calcio</b> (no el ión potasio) el que es reemplazado por el plomo, formando un complejo <b>hidrosoluble y no tóxico</b> que se elimina por orina (apuntes, p. 49 y 56). ✓ Las aves acuáticas ingieren los perdigones y las rapaces se intoxican de forma secundaria al comer las presas (apuntes, p. 54 y 57). ✓ El plomo deprime la inmunidad: baja la globulina sérica, la síntesis de anticuerpos, la lisozima y la fagocitosis (apuntes, p. 55)."},
/* recopilación, reco p. 32 (n.º 86) */
{t:2,q:"¿De cuál de las siguientes fuentes sospecharía si se encuentra ante una intoxicación crónica por Pb en el rebaño ovino de su cliente?",o:["Los animales pastan habitualmente a los bordes de una autopista muy transitada","A escasos kilómetros de la explotación ganadera hay una mina antigua romana de plomo que cesó su actividad hace más de 100 años","Muy cerca de donde pastan los animales hay un coto cinegético de gran actividad actualmente en el que se caza con perdigones de plomo","Los animales beben de un arroyo al que vierte la depuradora del pueblo"],a:1,
n:"El plomo de las <b>minas y escombreras antiguas</b> permanece en el suelo y en los pastos durante siglos, y es la fuente clásica de plumbismo crónico en rumiantes (ovino y bovino están entre las especies más afectadas; apuntes, p. 54). ✗ El plomo del tráfico dejó de ser relevante al retirarse las gasolinas con plomo tetraetilo, aunque los vegetales próximos a vías de circulación figuran como origen histórico (p. 54). ✗ Los perdigones son la fuente típica de las <b>aves</b> acuáticas y de las rapaces, no del ganado que pasta. ✗ El vertido de una depuradora orienta a otros contaminantes."},
/* recopilación, reco p. 32 (n.º 87) */
{t:2,q:"Sobre el arsénico, señale la correcta",o:["BAL y DMPS son quelantes de elección para este","Es tóxico a nivel capilar, lo cual provoca trasudación de plasma y finalmente shock","Los compuestos trivalentes de arsénico son más tóxicos que los pentavalentes","Todas son ciertas"],a:3,
n:"Las tres afirmaciones están en tus apuntes: el antídoto específico del arsénico es el <b>BAL (dimercaprol)</b> junto con el <b>DMPS</b> (p. 49 y 73); es <b>tóxico capilar</b> y produce trasudación de plasma → reducción del volumen sanguíneo → shock, con dilatación de capilares glomerulares y oliguria (p. 72); y los compuestos <b>trivalentes son más tóxicos</b> que los pentavalentes (p. 71)."},
/* recopilación, reco p. 32 (n.º 88) */
{t:2,q:"La seleniosis aguda produce",o:["Enfermedad de la cola cortada","Cojera","Alargamiento de pezuñas y cascos","Poliuria, mucosas pálidas y postración"],a:3,
n:"La intoxicación <b>aguda</b> por selenio cursa con vómitos rápidos, debilidad, jadeos y estertores con moco y espuma, depresión del SNC, abdomen hinchado y dolor abdominal, <b>poliuria</b>, <b>mucosas pálidas</b> o cianóticas, pupilas dilatadas, marcha errante, <b>postración</b>, pulso rápido y débil y muerte por fallo respiratorio (apuntes, p. 67). ✗ La enfermedad de la cola cortada (enfermedad del álcali), la cojera y el alargamiento de pezuñas y cascos pertenecen al cuadro <b>crónico</b>, como anota la propia recopilación."},
/* recopilación, reco p. 33 (n.º 89) */
{t:2,q:"La enfermedad alcalina (selenio) se caracteriza por",o:["Ser una enfermedad miocárdica nutricional","Provocar miodistrofia de la musculatura esquelética","Producir caída del pelo y alargamiento de las uñas y pezuñas, además de piel agrietada","Inducir la pérdida de visión, lo que explica que los animales tropiecen y caminen en círculo"],a:2,
n:"La <b>enfermedad del álcali</b> («enfermedad de la cola cortada») es la seleniosis <b>crónica</b> por granos y pastos seleníferos: cojera, pérdida de vitalidad, <b>alargamiento de pezuñas y cascos</b> y <b>caída del pelo</b> de melena y cola (apuntes, p. 67). ✗ La enfermedad miocárdica nutricional y la miodistrofia esquelética (enfermedad del músculo blanco) son por <b>deficiencia</b> de selenio y vitamina E, no por exceso. ✗ La ceguera con marcha en círculo corresponde al cuadro llamado «blind staggers», que no es la enfermedad alcalina."},
/* recopilación, reco p. 33 (n.º 90) */
{t:2,q:"Deyecciones de color verde brillante que pueden teñir las plumas pericloacales, disminución del reflejo de conservación, impactación y atonía de molleja son algunos de los síntomas que pueden presentarse en aves intoxicadas por",o:["Cobre","Plomo metálico o sales de plomo","Sales de cadmio","Insecticidas organofosforados"],a:1,
n:"Es el cuadro del <b>plumbismo aviar</b>: diarrea verdosa que mancha las plumas pericloacales, anorexia con pérdida de peso, parálisis y alteraciones de la locomoción, letargia, ausencia de reflejos e incapacidad para el vuelo y la huida; a nivel digestivo, <b>implantación del plomo en la molleja</b> (apuntes, p. 57-58). ✗ El cadmio en aves da descalcificación ósea, hiperqueratosis de molleja, nefritis y enteritis (p. 59). ✗ Los organofosforados producen un cuadro colinérgico agudo (miosis, hipersalivación, diarrea, temblores)."},
/* recopilación, reco p. 33 (n.º 91) */
{t:2,q:"¿Cuál de los siguientes minerales y/o productos apenas contiene plomo?",o:["Baterías recargables","Vidrio","Barniz","Cuarzo"],a:3,
n:"El <b>cuarzo</b> es dióxido de silicio: no lleva plomo. ✗ Entre los usos del plomo tus apuntes citan expresamente <b>baterías recargables de automóviles, pintura, vidrio, barnices, esmaltes y materias plásticas</b>, además de cañerías, perdigones y antidetonantes de las gasolinas (apuntes, p. 53-54)."},
/* recopilación, reco p. 29 (n.º 53) */
{t:2,q:"Sobre los antídotos, señale la INCORRECTA",o:["Una vez que los tóxicos han sido absorbidos, se debe elegir un antídoto para contrarrestar la acción del tóxico, entre los que tenemos antídotos químicos, quelantes, sustitutivos, biológicos y fisiológicos","Los antídotos fisiológicos o antagonistas no actúan contra la molécula de tóxico pero anulan sus efectos nocivos","Los antídotos sustitutivos son moléculas biológicas que inducen la producción de Ac específicos que sustituyen o desplazan a las moléculas tóxicas","Los quelantes se unen a minerales y metaloides formando complejos insolubles, no iónicos, y en general de menor o nula toxicidad"],a:2,d:true,
n:"Los antídotos <b>sustitutivos</b> corrigen el trastorno metabólico producido por el tóxico aportando el sustrato que falta o desplazándolo de su diana (tiosulfato sódico en el cianuro y en el arsénico, apuntes, p. 73; azul de metileno en los metahemoglobinizantes, p. 37): <b>no inducen anticuerpos</b>, eso corresponde a los antídotos <b>biológicos</b> (antivenenos y antitoxinas). ✓ Los <b>fisiológicos o antagonistas</b> no tocan la molécula de tóxico, solo anulan sus efectos (atropina en los organofosforados, p. 20). ⚠ Ojo con la última opción: los quelantes forman complejos <b>hidrosolubles</b> que se eliminan por orina (el CaNa₂-EDTA forma un complejo PbNa₂EDTA hidrosoluble; apuntes, p. 49), de modo que decir «insolubles» también choca con tus apuntes; la recopilación marca como falsa la de los sustitutivos. La clasificación general de los antídotos no está en tus apuntes, que solo desarrollan la terapia quelante (p. 48-50)."},
/* recopilación, reco p. 29 (n.º 54) */
{t:2,q:"De los siguientes antídotos, ¿cuál no es un antídoto químico?",o:["Ácido etilendiaminotetraacético (EDTA)","Dimercaprol (BAL)","Atropina","Antivenenos"],a:3,d:true,
n:"Los <b>antivenenos</b> son antídotos <b>biológicos</b> (sueros con anticuerpos frente a la toxina), como anota a mano la recopilación. ✓ El <b>EDTA</b> y el <b>BAL</b> son quelantes, antídotos que actúan químicamente sobre el tóxico: el CaNa₂-EDTA se usa frente al plomo y al cinc y el BAL (dimercaprol) frente al arsénico y el mercurio inorgánico, estando contraindicado en las intoxicaciones por cadmio y mercurio orgánico (apuntes, p. 49). ⚠ Fíjate en que la <b>atropina</b> es un antídoto <b>fisiológico</b> (antagonista de los receptores muscarínicos en la intoxicación por organofosforados y carbamatos, apuntes, p. 20), así que en sentido estricto tampoco es un antídoto químico; la recopilación responde «antivenenos» por ser el único de naturaleza biológica. Esta clasificación no está en tus apuntes."},
/* recopilación, reco p. 39 (n.º 59) */
{t:2,q:"Uno de los siguientes compuestos no es un quelante:",o:["EDTA – difosfato","Deferroxamina","N-acetil-penicilamina","Dimercaprol"],a:0,
n:"El quelante que existe es el <b>EDTA dicobalto</b> (antídoto del cianuro); el «EDTA-difosfato» no existe, y así lo anota la propia recopilación («es dicobalto»).<br>✓ Los otros tres sí son quelantes: el <b>dimercaprol (BAL)</b> y la <b>D-penicilamina</b> figuran entre los quelantes de tus apuntes (apuntes, p. 49-50); la deferroxamina (quelante del hierro) y la N-acetil-penicilamina también lo son, aunque no están en tus apuntes."},
/* recopilación, reco p. 39 (n.º 65) */
{t:2,q:"Señale la INCORRECTA:",o:["El plomo es inductor de metalotioneínas","El cadmio se absorbe más por vía respiratoria que digestiva","El mercurio se usa como fungicida e insecticida","La enfermedad de Wilson es una afección genética relacionada con depósitos de Cu en el hígado, cerebro, riñón, ojo…"],a:0,
n:"✗ Los inductores de metalotioneínas son el <b>cadmio, el cinc, el selenio, el cobalto y el arsénico</b> (apuntes, p. 59 —inducir metalotioneínas con Zn, Se o Co es el tratamiento del cadmio— y p. 72 —el arsénico es inductor de metalotioneínas in vivo—). El plomo se acumula en tejidos calcificados e interfiere en la síntesis del grupo hemo, pero no induce metalotioneínas.<br>✓ B: la absorción del cadmio es principalmente respiratoria (apuntes, p. 58).<br>✓ C: hay fungicidas mercuriales inorgánicos y orgánicos (apuntes, p. 43-44).<br>✓ D: la enfermedad de Wilson (acúmulo de cobre) no está en tus apuntes, pero sí el acúmulo hepático de Cu y su papel en la intoxicación (apuntes, p. 62)."},
/* recopilación, reco p. 41 (n.º 93) */
{t:2,q:"Señale la respuesta correcta respecto a las interacciones entre los metales:",o:["El arsénico puede aumentar la excreción de selenio (el selenio protege de la toxicidad del cadmio y el mercurio)","Dietas ricas en selenio provocan mayor sensibilidad a la intoxicación crónica por cobre","El plomo interfiere en el metabolismo del calcio y del cinc (también interfiere en el metabolismo de la vitamina D y en la síntesis del grupo hemo)","Las respuestas A y C son correctas"],a:3,
n:"✓ A: el tratamiento de la intoxicación por selenio es administrar <b>sales de arsénico</b> en la dieta (apuntes, p. 68), precisamente porque el As aumenta su excreción; y el selenio protege frente al cadmio (acumulación e hipertensión) y reduce la toxicidad del metil-Hg (apuntes, p. 67).<br>✓ C: el plomo se acumula en tejidos calcificados por su similitud con el calcio, interfiere en la conversión de la vitamina D y en la síntesis del grupo hemo (ALAD, enzima dependiente de cinc) (apuntes, p. 47, 55 y 58).<br>✗ B: es la <b>carencia</b> de selenio y molibdeno la que aumenta la toxicidad del cobre, y el Se incluso mejora su absorción (apuntes, p. 60-61)."},
/* recopilación, reco p. 41 (n.º 94) */
{t:2,q:"Respecto a la toxicología del cobre y el molibdeno, señale la correcta:",o:["La intoxicación por cobre puede deberse a una dosis elevada de este metal, a un desequilibrio cobre/molibdeno en rumiantes o a la ingestión de plantas que producen desequilibrio mineral o que contienen alcaloides hepatotóxicos; además, ciertas razas de perros pueden presentar predisposición genética a acumular cobre en el hígado, de forma similar a la enfermedad de Wilson en humanos","El ganado vacuno es más sensible que el ovino a la intoxicación por cobre, al contrario que para el molibdeno","Ciertas razas de perros pueden presentar predisposición genética a acumular cobre en el hígado de forma similar a la enfermedad de Wilson en humanos, y el ganado vacuno es más sensible que el ovino a la intoxicación por cobre","La intoxicación por cobre puede deberse a una dosis elevada de este metal o a un desequilibrio cobre/molibdeno en rumiantes, y el ganado vacuno es más sensible que el ovino a la intoxicación por cobre"],a:0,
n:"En el original eran cuatro enunciados sueltos (A: causas de la intoxicación; B: vacuno más sensible que ovino; C: razas de perros con predisposición genética —la marcada—; D: «la opción B y C son correctas»). Como <b>A y C son ciertas a la vez</b>, se han unido en una sola opción para que solo haya una respuesta correcta.<br>✓ Causas: dosis elevada, desequilibrio Cu/Mo en rumiantes, intoxicación secundaria fitógena (<i>Trifolium subterraneum</i>) y hepatógena por alcaloides pirrolizidínicos —<i>Senecio</i>, <i>Heliotropum</i>, <i>Echium</i>— (apuntes, p. 60-61).<br>✓ Perros: predisposición genética al acúmulo hepático de cobre (tipo Wilson); no está en tus apuntes, pero sí el acúmulo hepático y la inducción de metalotioneínas (apuntes, p. 62).<br>✗ El <b>ovino es mucho más sensible</b> que el vacuno: dosis única letal 20-30 mg/kg en ovino frente a 200 mg/kg en vacuno (apuntes, p. 61) —la recopilación lo corrige con un «al revés, + sensib ovi»—."},
/* recopilación, reco p. 43 (n.º 11) */
{t:2,q:"Una vez extraídos varios perdigones de la molleja de un ave acuática muerta, podemos diferenciar si son de plomo o de acero de la siguiente forma:",o:["Por el peso","Por el color","Acercando un imán","Todas las respuestas son correctas"],a:3,
n:"✓ El plomo es mucho más denso, gris mate y <b>no magnético</b>; el acero es más ligero, brillante y se pega al imán, así que las tres formas valen.<br>Tus apuntes tratan el plumbismo en aves y la implantación del plomo en la molleja (apuntes, p. 57-58), pero esta forma de diferenciar los perdigones <b>no está en tus apuntes</b>."},
/* recopilación, reco p. 43 (n.º 18) */
{t:2,q:"Respecto a la acumulación de tóxicos, señale la incorrecta:",o:["Organoclorados en grasa y SNC","Arsénico en uña y pelo","Cadmio en hueso y dientes","Mercurio en riñón"],a:2,
n:"✗ C: el cadmio se acumula en <b>hígado y riñón</b> (50-75 % de la carga corporal, unido a metalotioneínas), como corrige la recopilación («hígado y riñón») (apuntes, p. 47 y 58). En hueso y dientes se acumula el <b>flúor</b> (apuntes, p. 69).<br>✓ A: los organoclorados son muy liposolubles, se acumulan en grasa y atraviesan la BHE (apuntes, p. 12-13).<br>✓ B: el arsénico se acumula en hígado, riñón, uñas y pelo (apuntes, p. 71).<br>✓ D: el mercurio se acumula en riñón mediado por metalotioneínas (apuntes, p. 47)."},
/* recopilación, reco p. 45 (n.º 36) */
{t:2,q:"Respecto al tratamiento con quelantes de los siguientes metales, señale la falsa:",o:["El Hg orgánico se puede tratar con DMSA, D-penicilamina y BAL","El Cd no se puede tratar con BAL porque forma un complejo tóxico","El Pb se puede tratar con CaNaEDTA, DMSA y D-penicilamina","El As se puede tratar con DMSA, DMPS, BAL y sulfato sódico"],a:0,
n:"✗ A: el <b>BAL (dimercaprol) está contraindicado en la intoxicación por mercurio orgánico y por cadmio</b> (apuntes, p. 49) —la recopilación lo anota como «Hg org ∅ BAL»—. Para el Hg orgánico sí valen el DMPS y el DMSA, y la D-penicilamina se ha utilizado frente al mercurio (apuntes, p. 49-50).<br>✓ B: por eso en el cadmio se induce la síntesis de metalotioneínas con Zn, Se o Co en lugar de usar BAL (apuntes, p. 59).<br>✓ C: en el plomo se usan CaNa2EDTA (muy utilizado), DMSA y D-penicilamina (apuntes, p. 56).<br>✓ D: BAL, DMPS y DMSA están indicados en la intoxicación por arsénico (apuntes, p. 49); el sulfato sódico no es un quelante (se usa como purgante salino), pero la recopilación da la opción por buena. En el original pone «DMSC» por errata de DMPS."},
/* examen del 3er parcial (15/5/25) */
{t:3,q:"Sobre el bisfenol A (BPA), señale la afirmación verdadera",o:["Produce alteraciones en el aparato reproductor y afecta a la fertilidad","Solo produce irritación digestiva y no afecta al aparato reproductor","Sus efectos se limitan a la piel y no alcanzan al sistema hormonal","Es un disruptor endocrino que no produce ningún efecto sobre el feto"],a:0,
n:"Cayó en el 3er parcial (15/5/25): pedía la verdadera, y era la del aparato reproductor y la función reproductiva.<br>En los efectos del BPA (p. 81): «<b>Alteraciones en el sistema reproductor</b> (afectación de la fertilidad)». Los demás efectos de la lista son cáncer, alteraciones en el desarrollo y a nivel neuronal, producción de especies reactivas de oxígeno con daño en el material genético, enfermedades metabólicas y cardiovasculares.<br>Es un <b>disruptor endocrino</b>, y la exposición es crónica, con mayor riesgo en fetos, bebés y niños (p. 80)."},
/* examen del 3er parcial (15/5/25) */
{t:3,q:"Sobre los retardantes de llama bromados (BFR), señale la afirmación FALSA",o:["Se acumulan en el hueso y en la grasa del animal expuesto","No hay evidencias de carcinogenicidad de estos compuestos","Producen daños en el DNA de las células del organismo","Se acumulan en las grasas y pasan a la cadena alimentaria"],a:0,
n:"Cayó en el 3er parcial (15/5/25): había que marcar la falsa, y era la del hueso.<br>La tabla de tus apuntes (p. 79) dice literalmente: «<b>Se acumulan en las grasas pasando a la cadena alimentaria</b> (pescado, carne, leche y productos derivados)», «<b>No hay evidencias de carcinogenicidad</b>» y «<b>Daños en DNA</b>». El hueso no aparece por ningún lado: los BFR aditivos son muy lipofílicos y se acumulan en la grasa.<br>Sus órganos diana son <b>hígado, sistema nervioso, endocrino y reproductor</b>."},
/* recopilación, reco p. 40 (n.º 80) */
{t:3,q:"Señale la correcta:",o:["Los efectos del bisfenol A presente en plásticos policarbonatados se asocian a una desregulación del sistema endocrino y la producción de hormonas","El CO2 contribuye al aumento de la temperatura de la atmósfera: efecto invernadero","Los bifenilos policlorados se caracterizan por su persistencia alta en el medio","Todas son correctas"],a:3,
n:"✓ A: el BPA se emplea en plásticos y resinas epoxi (envases, vajillas, papel térmico, material dental) y es un <b>disruptor endocrino</b> que interfiere con la biosíntesis y el metabolismo de las hormonas (apuntes, p. 79-81).<br>✓ B: efecto invernadero.<br>✓ C: los bifenilos policlorados (en la recopilación, «bisfenoles policlorados») son compuestos muy persistentes; la propia recopilación da por falsa la afirmación contraria («su baja persistencia en el medio ambiente», reco p. 39, n.º 61). No están en tus apuntes de este bloque."}
];
QUESTIONS.forEach((q, i) => q.id = i);
